// 【命定之诗】命定论坛（阿斯塔利亚表版/里版）v1.8.0 · 线索世界书 + 🛠️Gemini工具一次调用 + 🎲6000字符头部破缓存乱码注入
// - 支持表版/里版切换、世界书动态扫描、分槽位提示词组装、魔导留影石 × st-chatu8 文生图联动、单帖收藏夹与线索世界书🔵蓝灯同步
// - 1:1 复刻《命定之诗 Prime-1.18》「消息后处理 + 🔌 Gemini工具一次调用」：保留完整 user 破限上下文，将 <Participant_input> 提取塞入伪造工具 submit_recorder_output 的 description 中，通过单次函数调用输出并实时流式解包渲染
// - 内置「🎲 头部乱码（6000字符破缓存）」开关：在请求头部注入 <system_entropy_padding> 包裹的 6000 字符纯 ASCII 加密盐值与防推理死循环元指令
(() => {
  "use strict";

  /* ============================================================================
   * 1. 生命周期管理与旧实例清理
   * ============================================================================ */
  function runCleanup(callbacks) {
    for (const cb of callbacks) {
      try {
        cb();
      } catch (err) {
        console.warn("[命定论坛] 清理旧实例监听异常:", err);
      }
    }
  }

  function disposePreviousForumUi(host, doc, key, rootId) {
    runCleanup([() => host[key]?.dispose?.()]);
    for (const prev of doc.querySelectorAll("#" + rootId)) {
      runCleanup([() => prev.__dlcForumUiDispose?.(), () => prev.remove()]);
    }
  }

  /* ============================================================================
   * 2. 悬浮球与底部脚本按钮双入口控制器（含手机版顶部防遮挡安全留白）
   * ============================================================================ */
  function createForumScriptEntry({
    host,
    doc,
    root,
    panel,
    backdrop,
    launcher,
    toolbar,
    name,
    getMobileTopOffset,
    onToggle,
    onLayout,
    onModeChange,
  }) {
    const query = host.matchMedia("(max-width: 1000px)");
    let disposed = false,
      mobile = false,
      frame = 0,
      eventType = "",
      scriptId = "",
      observer = null,
      wantedBottom = false;
    let expanded = false,
      nativeConfirmed = false;
    let nativeGroup = null,
      styledButton = null,
      panelObserver = null;
    const settleTimers = new Set();
    const entryStyle = doc.createElement("style");
    const entryOrder = 3;

    // 探测浏览器原生 env(safe-area-inset-top / bottom)
    const safeAreaProbe = doc.createElement("div");
    safeAreaProbe.style.cssText =
      "position:fixed;top:0;left:0;width:0;height:0;visibility:hidden;pointer-events:none;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);z-index:-1;";
    doc.body?.appendChild(safeAreaProbe);

    entryStyle.textContent = `
      [data-dlc-native-entry-group="${root.id}"]{width:auto!important;flex:0 1 auto!important;max-width:calc(50% - 4px)!important;min-width:0!important;order:${entryOrder}!important}
      [data-dlc-native-entry-button="${root.id}"]{order:${entryOrder}!important;white-space:nowrap}
    `;

    const available =
      typeof getScriptButtons === "function" &&
      typeof replaceScriptButtons === "function" &&
      typeof getButtonEvent === "function" &&
      typeof getScriptId === "function" &&
      typeof eventOn === "function";

    const initialDisplay = launcher.style.getPropertyValue("display"),
      initialDisplayPriority = launcher.style.getPropertyPriority("display");

    panel.classList.add("bottom-entry-panel");
    launcher.classList.add("floating-entry");

    const toggle = doc.createElement("button");
    toggle.type = "button";
    toggle.className = "icon entry-mode-toggle";
    toolbar.insertBefore(toggle, toolbar.querySelector(".close-panel-btn"));

    const preferenceKey = () =>
      root.id + ":entry-mode:" + (query.matches ? "narrow" : "wide");

    function readPreference() {
      try {
        const value = host.localStorage.getItem(preferenceKey());
        if (value === "bottom" || value === "floating") return value === "bottom";
      } catch {}
      return false;
    }

    wantedBottom = readPreference();

    function paintToggle() {
      toggle.title = wantedBottom ? "切换为悬浮球入口" : "切换为底部脚本按钮";
      toggle.setAttribute("aria-label", toggle.title);
      toggle.setAttribute("aria-pressed", String(wantedBottom));
      const drawing = wantedBottom
        ? '<rect x="3" y="3" width="18" height="14" rx="2"/><path d="M3 7h18"/><rect x="13" y="13" width="8" height="8" rx="4"/>'
        : '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 15h18M7 18h3M14 18h3"/>';
      toggle.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
        drawing +
        "</svg>";
    }

    function nativeButton() {
      const container = scriptId && doc.getElementById("script_container_" + scriptId);
      return container
        ? [...container.querySelectorAll(".qr--button")].find(
            (node) => node.textContent.trim() === name
          )
        : null;
    }

    function syncNativeLayout(button) {
      const next = wantedBottom ? button : null,
        group = next?.parentElement || null;
      if (nativeGroup !== group) {
        nativeGroup?.removeAttribute("data-dlc-native-entry-group");
        nativeGroup = group;
      }
      if (styledButton !== next) {
        styledButton?.removeAttribute("data-dlc-native-entry-button");
        styledButton = next;
      }
      if (group && group.getAttribute("data-dlc-native-entry-group") !== root.id)
        group.setAttribute("data-dlc-native-entry-group", root.id);
      if (next && next.getAttribute("data-dlc-native-entry-button") !== root.id)
        next.setAttribute("data-dlc-native-entry-button", root.id);
      if (next && !entryStyle.isConnected) doc.head.append(entryStyle);
    }

    function usableButton(button) {
      if (!button?.isConnected || !button.getClientRects().length) return false;
      const style = host.getComputedStyle(button);
      if (
        style.visibility === "hidden" ||
        style.visibility === "collapse" ||
        style.pointerEvents === "none"
      )
        return false;
      for (let node = button; node; node = node.parentElement) {
        if (node.hidden || node.inert) return false;
        const css = host.getComputedStyle(node);
        if (
          css.display === "none" ||
          (css.display !== "contents" && Number(css.opacity) === 0)
        )
          return false;
      }
      return true;
    }

    function registeredNativeEntry() {
      const get =
        typeof getAllEnabledScriptButtons === "function"
          ? getAllEnabledScriptButtons
          : host.TavernHelper?.getAllEnabledScriptButtons;
      if (!get || !scriptId) return null;
      try {
        const all = get();
        if (!all || typeof all !== "object" || typeof all.then === "function")
          return null;
        return (
          Array.isArray(all[scriptId]) &&
          all[scriptId].some((button) => button.button_name === name)
        );
      } catch {
        return null;
      }
    }

    function applyEntryVisibility() {
      const isPanelOpen = !panel.hidden;
      root.dataset.bottomEntry = String(mobile);
      panel.dataset.bottomEntry = String(mobile);
      const hideOrb = mobile || isPanelOpen;
      launcher.hidden = hideOrb;
      launcher.setAttribute("aria-hidden", String(hideOrb));
      if (hideOrb) {
        launcher.style.setProperty("display", "none", "important");
      } else if (initialDisplay) {
        launcher.style.setProperty("display", initialDisplay, initialDisplayPriority);
      } else {
        launcher.style.removeProperty("display");
      }
      if (backdrop) {
        backdrop.hidden = !isPanelOpen;
      }
    }

    function syncExpanded(value) {
      if (expanded !== value) {
        expanded = value;
        if (value) {
          layoutViewportPanel();
          settleLayout();
        }
      }
      applyEntryVisibility();
      const button = nativeButton();
      if (button) {
        button.setAttribute("aria-expanded", String(value));
        button.setAttribute("aria-label", (value ? "收起" : "打开") + name);
      }
    }

    function readSafeAreaInsets() {
      let safeTop = 0,
        safeBottom = 0;
      try {
        if (safeAreaProbe.isConnected) {
          const cs = host.getComputedStyle(safeAreaProbe);
          safeTop = parseFloat(cs.paddingTop) || 0;
          safeBottom = parseFloat(cs.paddingBottom) || 0;
        }
      } catch {}
      return { safeTop, safeBottom };
    }

    // 统一基于 visualViewport 计算面板的固定居中尺寸与位置，并为手机版预留充足的顶部防遮挡留白
    function layoutViewportPanel() {
      if (disposed || panel.hidden) return;
      const view = host.visualViewport;
      const vw = view?.width || host.innerWidth || 375;
      const vh = view?.height || host.innerHeight || 667;
      const vTop = view?.offsetTop || 0;
      const vLeft = view?.offsetLeft || 0;

      const isMobileViewport =
        vw <= 820 ||
        query.matches ||
        host.matchMedia?.("(pointer: coarse)")?.matches ||
        /iPhone|iPad|iPod|Android|Mobile/i.test(host.navigator?.userAgent || "");

      const { safeTop, safeBottom } = readSafeAreaInsets();
      const configuredMobileTop = Number(getMobileTopOffset?.());
      const userTopOffset = Number.isFinite(configuredMobileTop)
        ? Math.max(0, configuredMobileTop)
        : 54;

      const marginX = vw <= 640 ? 8 : 16;
      const topMargin = isMobileViewport
        ? Math.max(safeTop + 14, userTopOffset)
        : Math.max(safeTop + 14, 18);
      const bottomMargin = isMobileViewport
        ? Math.max(safeBottom + 12, 14)
        : Math.max(safeBottom + 12, 18);

      const availW = Math.max(260, vw - marginX * 2);
      const availH = Math.max(220, vh - topMargin - bottomMargin);
      const targetW = Math.min(860, availW);
      const targetMaxH = Math.min(880, availH);

      const leftPx = Math.round(vLeft + (vw - targetW) / 2);
      const topPx = Math.round(vTop + topMargin);

      root.style.setProperty("--ast-panel-left", leftPx + "px");
      root.style.setProperty("--ast-panel-top", topPx + "px");
      root.style.setProperty("--ast-panel-width", targetW + "px");
      root.style.setProperty("--ast-panel-max-height", targetMaxH + "px");
    }

    function refreshPresence() {
      const button = nativeButton();
      syncNativeLayout(button);
      const registered = registeredNativeEntry();
      const next = !!(
        wantedBottom &&
        (registered ?? (nativeConfirmed || usableButton(button)))
      );
      if (next !== mobile) {
        runCleanup([() => onModeChange?.()]);
        mobile = next;
        if (mobile) settleLayout();
      }
      applyEntryVisibility();
      syncExpanded(!panel.hidden);
    }

    function schedule() {
      if (disposed || frame) return;
      frame = host.requestAnimationFrame(() => {
        frame = 0;
        if (disposed) return;
        refreshPresence();
        layoutViewportPanel();
        onLayout?.();
      });
    }

    function settleLayout() {
      for (const timer of settleTimers) host.clearTimeout(timer);
      settleTimers.clear();
      for (const delay of [60, 180, 450]) {
        const timer = host.setTimeout(() => {
          settleTimers.delete(timer);
          if (!panel.hidden) schedule();
        }, delay);
        settleTimers.add(timer);
      }
    }

    function setVisible(visible) {
      if (!available) return;
      try {
        const buttons = getScriptButtons(),
          existing = buttons.find((button) => button.name === name);
        if (existing?.visible === visible) return;
        replaceScriptButtons(
          existing
            ? buttons.map((button) =>
                button.name === name ? { ...button, visible } : button
              )
            : [...buttons, { name, visible }]
        );
      } catch (error) {
        console.warn("[命定论坛] 无法更新底部按钮，保留悬浮球入口。", error);
      }
    }

    function onBreakpoint() {
      const next = readPreference();
      if (next !== wantedBottom) nativeConfirmed = false;
      wantedBottom = next;
      paintToggle();
      setVisible(wantedBottom);
      schedule();
    }

    function switchMode() {
      wantedBottom = !wantedBottom;
      nativeConfirmed = false;
      try {
        host.localStorage.setItem(
          preferenceKey(),
          wantedBottom ? "bottom" : "floating"
        );
      } catch {}
      paintToggle();
      setVisible(wantedBottom);
      schedule();
    }

    toggle.addEventListener("click", switchMode);

    const onClick = () => {
      if (disposed) return;
      nativeConfirmed = true;
      refreshPresence();
      onToggle();
    };

    if (available) {
      try {
        scriptId = getScriptId();
        eventType = getButtonEvent(name);
        eventOn(eventType, onClick);
      } catch (error) {
        console.warn("[命定论坛] 底部按钮未就绪，使用悬浮球入口。", error);
        scriptId = "";
      }
      if (scriptId) {
        observer = new host.MutationObserver((records) => {
          const button = nativeButton();
          if (
            records.some(
              (record) =>
                record.type === "childList" ||
                (button && record.target.contains(button))
            )
          )
            schedule();
        });
        observer.observe(doc.documentElement, {
          childList: true,
          subtree: true,
          attributes: true,
          attributeFilter: ["class", "style", "hidden", "inert"],
        });
        onBreakpoint();
      }
    }

    if (!toggle.innerHTML) paintToggle();
    if (!scriptId) {
      toggle.disabled = true;
      toggle.title = "底部按钮模式需在酒馆助手脚本库中启用脚本按钮";
      toggle.setAttribute("aria-label", toggle.title);
    }

    let unbindQuery = () => {};
    if (typeof query.addEventListener === "function") {
      query.addEventListener("change", onBreakpoint);
      unbindQuery = () => query.removeEventListener("change", onBreakpoint);
    }

    host.addEventListener("resize", schedule);
    host.visualViewport?.addEventListener("resize", schedule);
    host.visualViewport?.addEventListener("scroll", schedule);

    if (typeof host.ResizeObserver === "function") {
      panelObserver = new host.ResizeObserver(() => {
        if (!panel.hidden) schedule();
      });
      panelObserver.observe(panel);
    }

    return {
      isMobile: () => mobile,
      layout: layoutViewportPanel,
      syncExpanded,
      focus() {
        const button = mobile ? nativeButton() : launcher;
        if (button && !button.hidden) {
          try {
            button.focus({ preventScroll: true });
          } catch {
            button.focus();
          }
        }
      },
      dispose() {
        if (disposed) return;
        disposed = true;
        runCleanup([
          () => host.cancelAnimationFrame(frame),
          () => observer?.disconnect(),
          () => panelObserver?.disconnect(),
          () => {
            for (const timer of settleTimers) host.clearTimeout(timer);
            settleTimers.clear();
          },
          () => {
            nativeGroup?.removeAttribute("data-dlc-native-entry-group");
            styledButton?.removeAttribute("data-dlc-native-entry-button");
            entryStyle.remove();
            safeAreaProbe.remove();
          },
          () => toggle.removeEventListener("click", switchMode),
          () => toggle.remove(),
          unbindQuery,
          () => host.removeEventListener("resize", schedule),
          () => host.visualViewport?.removeEventListener("resize", schedule),
          () => host.visualViewport?.removeEventListener("scroll", schedule),
          () => {
            if (eventType && typeof eventRemoveListener === "function")
              eventRemoveListener(eventType, onClick);
          },
          () => {
            if (scriptId) setVisible(false);
          },
        ]);
      },
    };
  }

  /* ============================================================================
   * 3. 命定论坛原版设定与板块常量
   * ============================================================================ */
  const FORUM_BOARDS = {
    surface: [
      { id: "全站热榜", name: "🔥 全站热榜", desc: "置顶展示全站点赞最高、讨论最激烈的 1~2 条跨板块王炸神帖 (Hot Top)" },
      { id: "真实爆料", name: "⚡ 真实爆料", desc: "法环管理员认证真实情报、灾难预警、遗迹异动、跨国政军摩擦、强者私生活或神明抓拍" },
      { id: "大佬分享", name: "👑 大佬分享", desc: "高层级人物日常自述、未公开炼金配方(含具体材料)与技能分享、潜规则与硬核测评" },
      { id: "情感树洞", name: "🌙 情感树洞", desc: "情感经历求助、生活吐槽、复杂道德伦理探讨、激进社会改革讨论" },
      { id: "冒险世界", name: "⚔️ 冒险世界", desc: "个人冒险经历、装备推荐、直播探索、高难任务组队、新冒险地信息与紧急求助" },
      { id: "日常吃瓜", name: "🍉 日常吃瓜", desc: "大贵族/高层级丑闻、名人绯闻、知名学院/机构八卦、离谱见闻、白嫖渠道与近期焦点" },
      { id: "同城交流", name: "📍 同城交流", desc: "仅限与主角同城的发帖人：本地吐槽、当地特殊事件/人物、私下交易、在线求助（可含主角相关）" },
    ],
    dark: [
      { id: "全站热榜", name: "🔥 全站热榜", desc: "置顶展示里版当前点赞最高、最刺激的 1~2 条跨板块王炸神帖 (Hot Top)" },
      { id: "实战分享", name: "💦 实战分享", desc: "最直接的实际做爱经验与经历分享，有图有真相（纯爱/异种/调教/NTR/稀有种族或高地位实战）" },
      { id: "XP交流", name: "🎭 XP交流", desc: "分享和交流各种正常或古怪色情的 XP、意淫讨论或附带实战过程" },
      { id: "自拍偷拍", name: "📸 自拍偷拍", desc: "魔导留影石真实记录（严禁幻象法术预制菜）：福利自拍、露出、高层级私密流出、地下派对偷拍" },
      { id: "禁忌伦理", name: "🩸 禁忌伦理", desc: "破坏伦理道德快感：背德、师生、乱伦、背叛、亵渎、NTR、种族伦理与情感破坏" },
      { id: "深度测评", name: "🧪 深度测评", desc: "媚药测评、风俗探店打分、性玩具测评、紧致度与性技能分享、异种族繁育调教记录" },
      { id: "同城交流", name: "📍 同城暗巷", desc: "同城线下：寻主/寻奴、单男、致幻/非法炼金药剂交易、乱交派对、私密悬赏（可含主角相关）" },
    ],
  };

  const FORUM_COMMON_RULES = `<论坛输出公共要求>
论坛设定:
  定义: 这是一个最近才由伯伦斯法环研制、使用魔力构筑的魔法网络论坛，学名命定论坛（Astaria Astral-Net）
  区分: 分为表版普通论坛（阿斯塔利亚论坛）与里版论坛（阿斯塔利亚里版论坛）
  接入方式: 使用特定的魔力频段即可接入大脑随时随地进行浏览；也可通过特定魔导终端接入，用于上传留影石画面
  限制: 目前**仅第三层级以上**才可接入魔力查看（严禁出现第三层级以下人员作为发帖人或层主！）
  审查: R18限制级内容仅限里版论坛讨论，表版讨论相关内容会被自动检测魔法程序删帖或限制回复；里版无审查，发言人自己对自己言论负责
  管理员权限: 仅伯伦斯法环穹境三席拥有，且承诺只有在紧急状况下三人同时同意才可使用管理员权限
  身份迷雾: 除拥有管理权限者之外，论坛的所有发言者均不知道任何其他人的真实姓名、真实身份、层级、地址等信息
  新事物: 由于是新鲜事物，部分高层级大人物也喜欢看

{{user}}特权（穹境三席后台管理员界面）:
  - 系统核心为{{user}}打开与穹境三席相同的后台管理员界面
  - {{user}}在该界面下可以看到所有人(包括发帖者与回复者)的真实姓名、真实身份，以及发帖地址。你必须展示为管理员界面，在每个发帖人与回复者匿名昵称旁的 <span class="ast-admin"> 标签内展示真实姓名（符合西幻角色命名指导），并用括号在姓名后附加其身份及层级、等级、发帖地址（例如：真实身份：奥古斯汀（圣灵教会驻港司祭｜第四层级 Lv.14｜雾晶港·圣职公署））。不得省略或简化、禁止使用“某xx”之类的身份代指、严禁出现第三层级以下人员！

论坛内容要求:
  - 论坛内所有的一切都要符合<世界主设定>、阿斯塔利亚世界观以及生命层级相关设定，并紧密结合【当前世界时间、地点、最新剧情与世界时局动态】
  {{forum_user_post_rule}}
  - 发帖格式: 必须包含极具吸引力的完整标题（严禁使用数字1或占位符敷衍）、发帖人匿名昵称、浏览量、点击、点赞、收藏等内容（浏览 ≥ 点击 > 点赞 > 收藏；数据的数量级必须根据第三层级以上的人口比例与数量确定）
  - 论坛用户: 论坛用户全员匿名，使用符合西幻论坛风味的昵称。用户性别可与其真实性别不同
