        macroRegexList.some((re) => re.test(text)) ||
        /\{\{[\s\S]+?\}\}|<(?:user|char|bot)>/i.test(text)
      );
    }

    function getScopes(host, localWin) {
      return [
        ...new Set(
          [localWin, host, localWin?.TavernHelper, host?.TavernHelper].filter(Boolean)
        ),
      ];
    }

    function getStContext(host, localWin) {
      try {
        return (
          localWin?.SillyTavern?.getContext?.() ||
          host?.SillyTavern?.getContext?.() ||
          null
        );
      } catch {
        return null;
      }
    }

    function deepClone(val) {
      if (val == null || typeof val !== "object") return val;
      try {
        return JSON.parse(JSON.stringify(val));
      } catch {
        return Array.isArray(val) ? [...val] : { ...val };
      }
    }

    // 解析点路径与方括号路径，如 a.b['c']["d"][0]
    function parsePathSegments(pathInput) {
      if (Array.isArray(pathInput)) return pathInput.map((x) => String(x));
      const s = String(pathInput ?? "").trim();
      if (!s) return [];
      const segments = [];
      const re = /([^.[\]]+)|\[(?:\s*(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^[\]]+?))\s*)\]/g;
      let m;
      while ((m = re.exec(s)) !== null) {
        if (m[1] !== undefined) segments.push(m[1].trim());
        else if (m[2] !== undefined) segments.push(m[2].replace(/\\"/g, '"'));
        else if (m[3] !== undefined) segments.push(m[3].replace(/\\'/g, "'"));
        else if (m[4] !== undefined) segments.push(m[4].trim());
      }
      return segments.filter(Boolean);
    }

    function getByPath(obj, pathInput, defaultVal = undefined) {
      if (obj == null || typeof obj !== "object") return defaultVal;
      if (typeof pathInput === "string" && Object.prototype.hasOwnProperty.call(obj, pathInput)) {
        return obj[pathInput] !== undefined ? obj[pathInput] : defaultVal;
      }
      const segs = parsePathSegments(pathInput);
      if (!segs.length) return defaultVal;
      let cur = obj;
      for (const seg of segs) {
        if (cur == null || typeof cur !== "object") return defaultVal;
        cur = cur[seg];
      }
      return cur === undefined ? defaultVal : cur;
    }

    function setByPath(obj, pathInput, value) {
      if (!isObj(obj) && !Array.isArray(obj)) return obj;
      const segs = parsePathSegments(pathInput);
      if (!segs.length) return obj;
      let cur = obj;
      for (let i = 0; i < segs.length - 1; i++) {
        const seg = segs[i];
        const nextSeg = segs[i + 1];
        if (cur[seg] == null || typeof cur[seg] !== "object") {
          cur[seg] = /^\d+$/.test(nextSeg) ? [] : {};
        }
        cur = cur[seg];
      }
      cur[segs[segs.length - 1]] = value;
      return obj;
    }

    // 剥离 <%# char-info-ejs-builder:start:v2 %>...<%# char-info-ejs-builder:end:v2 %>
    // 与 <%# poem-workshop-meta:v1-start ... poem-workshop-meta:v1-end %> 块
    // 可选通过 onCharInfoBlock 回调先执行 char-info-ejs-builder 内部的 setLocalVar
    function stripEjsMetaBlocks(text, onCharInfoBlock = null) {
      if (!text || typeof text !== "string") return "";
      return text
        .replace(
          /<%#\s*char-info-ejs-builder:start(?::[^\s%>]+)?\s*%>([\s\S]*?)<%#\s*char-info-ejs-builder:end(?::[^\s%>]+)?\s*%>[ \t]*\r?\n?/gi,
          (_, innerBlock) => {
            if (typeof onCharInfoBlock === "function" && innerBlock) {
              try {
                onCharInfoBlock(innerBlock);
              } catch {}
            }
            return "";
          }
        )
        .replace(/<%#\s*char-info-ejs-builder:(?:start|end)(?::[^\s%>]+)?\s*%>[ \t]*\r?\n?/gi, "")
        .replace(
          /<%#\s*poem-workshop-meta:[^\s%>]*-start[\s\S]*?poem-workshop-meta:[^\s%>]*-end\s*%>[ \t]*\r?\n?/gi,
          ""
        )
        .replace(/<%#\s*poem-workshop-meta:[\s\S]*?%>[ \t]*\r?\n?/gi, "");
    }

    // 预扫描提取 {{setvar::key::val}} 至沙箱变量字典（不改变主聊天变量）
    function extractSetvarMacrosToSandbox(text, sandbox, onlyIfMissing = false) {
      if (!text || typeof text !== "string" || !sandbox) return;
      const setRe = /\{\{\s*set(?:global)?var\s*::\s*([^:}]+?)\s*::\s*([\s\S]*?)\}\}/gi;
      let m;
      while ((m = setRe.exec(text)) !== null) {
        const k = String(m[1] || "").trim();
        const v = String(m[2] ?? "");
        if (!k) continue;
        if (onlyIfMissing && sandbox.resolveVar(k) !== undefined) continue;
        sandbox.writeVar(k, v);
      }
    }

    // 屏蔽写操作宏，防止后台扫描世界书时篡改主聊天变量，同时将 setvar 值记录到沙箱
    function stripMutatingMacros(text, sandbox = null) {
      const src = String(text || "");
      if (sandbox) {
        extractSetvarMacrosToSandbox(src, sandbox, false);
      }
      return src.replace(
        /\{\{\s*(?:setvar|addvar|incvar|decvar|deletevar|flushvar|setglobalvar|addglobalvar|incglobalvar|decglobalvar|deleteglobalvar|flushglobalvar)\s*::[\s\S]*?\}\}/gi,
        ""
      );
    }

    // 内置轻量级 Lodash 兼容实现（供世界书 EJS 使用）
    function createLodashFallback(externalLodash) {
      const base = {
        get: (obj, path, def) => getByPath(obj, path, def),
        set: (obj, path, val) => setByPath(obj, path, val),
        has: (obj, path) => getByPath(obj, path, undefined) !== undefined,
        cloneDeep: (val) => deepClone(val),
        isNumber: (v) => typeof v === "number" && !Number.isNaN(v),
        isObjectLike: (v) => typeof v === "object" && v !== null,
        isEmpty: (v) => {
          if (v == null) return true;
          if (Array.isArray(v) || typeof v === "string") return v.length === 0;
          if (typeof v === "object") return Object.keys(v).length === 0;
          return false;
        },
        size: (v) => {
          if (v == null) return 0;
          if (Array.isArray(v) || typeof v === "string") return v.length;
          if (typeof v === "object") return Object.keys(v).length;
          return 0;
        },
        trim: (v) => String(v ?? "").trim(),
        pick: (obj, keys) => {
          if (!isObj(obj)) return {};
          const keyList = Array.isArray(keys) ? keys.flat() : [keys];
          const out = {};
          for (const k of keyList) {
            if (k != null && Object.prototype.hasOwnProperty.call(obj, k)) {
              out[k] = obj[k];
            }
          }
          return out;
        },
        omit: (obj, keys) => {
          if (!isObj(obj)) return {};
          const keySet = new Set(Array.isArray(keys) ? keys.flat() : [keys]);
          const out = {};
          for (const [k, v] of Object.entries(obj)) {
            if (!keySet.has(k)) out[k] = v;
          }
          return out;
        },
        omitBy: (obj, predicate) => {
          if (!isObj(obj)) return {};
          const out = {};
          for (const [k, v] of Object.entries(obj)) {
            if (!predicate(v, k)) out[k] = v;
          }
          return out;
        },
        mapKeys: (obj, iteratee) => {
          if (!isObj(obj)) return {};
          const out = {};
          for (const [k, v] of Object.entries(obj)) {
            out[iteratee(v, k, obj)] = v;
          }
          return out;
        },
        mapValues: (obj, iteratee) => {
          if (!isObj(obj)) return {};
          const out = {};
          for (const [k, v] of Object.entries(obj)) {
            out[k] = iteratee(v, k, obj);
          }
          return out;
        },
        forEach: (collection, iteratee) => {
          if (Array.isArray(collection)) {
            collection.forEach(iteratee);
          } else if (isObj(collection)) {
            for (const [k, v] of Object.entries(collection)) iteratee(v, k, collection);
          }
        },
        forOwn: (obj, iteratee) => {
          if (isObj(obj)) {
            for (const [k, v] of Object.entries(obj)) iteratee(v, k, obj);
          }
          return obj;
        },
        keyBy: (arr, iteratee) => {
          const out = {};
          if (!Array.isArray(arr)) return out;
          for (const item of arr) {
            if (item == null) continue;
            const k = typeof iteratee === "function" ? iteratee(item) : item[iteratee];
            if (k !== undefined) out[k] = item;
          }
          return out;
        },
        chain: (val) => {
          let cur = Array.isArray(val) ? [...val] : val;
          const wrapper = {
            filter: (fn) => {
              if (Array.isArray(cur)) {
                cur = cur.filter(typeof fn === "function" ? fn : (x) => Boolean(x?.[fn]));
              }
              return wrapper;
            },
            flatMap: (fn) => {
              if (Array.isArray(cur)) {
                cur = cur.flatMap(typeof fn === "function" ? fn : (x) => x?.[fn] ?? []);
              }
              return wrapper;
            },
            map: (fn) => {
              if (Array.isArray(cur)) {
                cur = cur.map(typeof fn === "function" ? fn : (x) => x?.[fn]);
              }
              return wrapper;
            },
            value: () => cur,
          };
          return wrapper;
        },
      };
      return externalLodash ? Object.assign({}, base, externalLodash) : base;
    }

    function simpleYamlStringify(data, indent = 0) {
      const pad = "  ".repeat(indent);
      if (data === null || data === undefined) return "null";
      if (typeof data === "boolean" || typeof data === "number") return String(data);
      if (typeof data === "string") {
        if (data.includes("\n")) {
          return "|\n" + data.split("\n").map((l) => pad + "  " + l).join("\n");
        }
        return JSON.stringify(data);
      }
      if (Array.isArray(data)) {
        if (!data.length) return "[]";
        return data
          .map((item) => {
            if (item && typeof item === "object") {
              return `${pad}-\n${simpleYamlStringify(item, indent + 1)}`;
            }
            return `${pad}- ${simpleYamlStringify(item, 0)}`;
          })
          .join("\n");
      }
      if (typeof data === "object") {
        const keys = Object.keys(data);
        if (!keys.length) return "{}";
        return keys
          .map((k) => {
            const v = data[k];
            if (
              v &&
              typeof v === "object" &&
              (Array.isArray(v) ? v.length > 0 : Object.keys(v).length > 0)
            ) {
              return `${pad}${k}:\n${simpleYamlStringify(v, indent + 1)}`;
            }
            return `${pad}${k}: ${simpleYamlStringify(v, 0)}`;
          })
          .join("\n");
      }
      return String(data);
    }

    // 编译并运行 EJS 模板（支持 <% ... %>, <%_ ... _%>, <%= ... %>, <%- ... %>, <%# ... %>）
    function compileAndRunEjs(templateStr, sandboxEnv) {
      if (!templateStr || typeof templateStr !== "string" || !templateStr.includes("<%")) {
        return templateStr || "";
      }

      const tagRe = /<%([_=#-]?)([\s\S]*?)([_-]?)%>/g;
      let lastIdx = 0;
      let match;
      const tokens = [];

      while ((match = tagRe.exec(templateStr)) !== null) {
        if (match.index > lastIdx) {
          tokens.push({ type: "text", value: templateStr.slice(lastIdx, match.index) });
        }
        tokens.push({
          type: "tag",
          openMod: match[1] || "",
          code: match[2] || "",
          closeMod: match[3] || "",
        });
        lastIdx = tagRe.lastIndex;
      }
      if (lastIdx < templateStr.length) {
        tokens.push({ type: "text", value: templateStr.slice(lastIdx) });
      }

      for (let i = 0; i < tokens.length; i++) {
        const tok = tokens[i];
        if (tok.type === "tag") {
          if (tok.openMod === "_" && i > 0 && tokens[i - 1].type === "text") {
            tokens[i - 1].value = tokens[i - 1].value.replace(/(^|\r?\n)[ \t]*$/, "$1");
          }
          if (tok.closeMod === "_" && i + 1 < tokens.length && tokens[i + 1].type === "text") {
            tokens[i + 1].value = tokens[i + 1].value.replace(/^[ \t]*\r?\n?/, "");
          } else if (tok.closeMod === "-" && i + 1 < tokens.length && tokens[i + 1].type === "text") {
            tokens[i + 1].value = tokens[i + 1].value.replace(/^\r?\n/, "");
          }
        }
      }

      let fnBody =
        'let __out = "";\nconst __append = (v) => { if (v !== undefined && v !== null) __out += String(v); };\n';
      for (const tok of tokens) {
        if (tok.type === "text") {
          if (tok.value) {
            fnBody += `__out += ${JSON.stringify(tok.value)};\n`;
          }
        } else {
          if (tok.openMod === "#") continue;
          const cleanCode = tok.code.replace(/\bawait\b/g, " ");
          if (tok.openMod === "=" || tok.openMod === "-") {
            fnBody += `__append(${cleanCode.trim()});\n`;
          } else {
            fnBody += `${cleanCode}\n`;
          }
        }
      }
      fnBody += "return __out;";

      const paramNames = Object.keys(sandboxEnv);
      const paramValues = paramNames.map((k) => sandboxEnv[k]);
      const runner = new Function(...paramNames, fnBody);
      return runner(...paramValues);
    }

    function getOrInitSandbox(contextData, host, localWin) {
      if (contextData && isObj(contextData._ejsSandbox)) {
        return contextData._ejsSandbox;
      }

      const scopes = getScopes(host, localWin);
      const stCtx = getStContext(host, localWin);
      const userName =
        contextData?.user ||
        contextData?.userName ||
        stCtx?.name1 ||
        "莎莉";
      const charName =
        contextData?.char ||
        contextData?.charName ||
        stCtx?.name2 ||
        "阿斯塔利亚";

      const vars = deepClone(contextData?.chatVars || {});
      const stat = deepClone(contextData?.statData || vars.stat_data || {});
      // 剥离论坛自身扩展变量 (forum_data / stat_data.事件.命定论坛 / stat_data.命定论坛)，确保论坛不提取论坛自身的变量
      if (isObj(vars)) {
        delete vars.forum_data;
        delete vars.命定论坛;
        if (isObj(vars.stat_data)) {
          delete vars.stat_data.forum_data;
          delete vars.stat_data.命定论坛;
          if (isObj(vars.stat_data.事件)) {
            delete vars.stat_data.事件.forum_data;
            delete vars.stat_data.事件.命定论坛;
          }
        }
      }
      if (isObj(stat)) {
        delete stat.forum_data;
        delete stat.命定论坛;
        if (isObj(stat.事件)) {
          delete stat.事件.forum_data;
          delete stat.事件.命定论坛;
        }
      }
      const cleanedMsgs = Array.isArray(contextData?.cleanedMessages)
        ? contextData.cleanedMessages
        : [];
      const lastMsgId =
        typeof contextData?.lastMessageId === "number"
          ? contextData.lastMessageId
          : cleanedMsgs.length > 0
          ? Number(cleanedMsgs.at(-1)?.message_id ?? cleanedMsgs.length)
          : 10;

      const resolveVar = (rawPath, opts) => {
        const def = isObj(opts) ? opts.defaults : undefined;
        const clean = String(rawPath ?? "").trim().replace(/^[.$]/, "");
        if (!clean) return def;
        if (
          clean === "forum_data" ||
          clean.startsWith("forum_data.") ||
          clean === "命定论坛" ||
          clean.startsWith("命定论坛.") ||
          clean === "stat_data.forum_data" ||
          clean.startsWith("stat_data.forum_data.") ||
          clean === "stat_data.命定论坛" ||
          clean.startsWith("stat_data.命定论坛.") ||
          clean === "stat_data.事件.forum_data" ||
          clean.startsWith("stat_data.事件.forum_data.") ||
          clean === "stat_data.事件.命定论坛" ||
          clean.startsWith("stat_data.事件.命定论坛.")
        ) {
          return def;
        }
        if (clean === "stat_data") return stat;
        if (clean.startsWith("stat_data.")) {
          const sub = clean.slice("stat_data.".length);
          const found = getByPath(stat, sub, undefined);
          if (found !== undefined) return found;
          if (def !== undefined) return def;
          if (sub === "主角.生命层级") return "第一层级";
          if (sub === "世界.地点") return "";
          if (sub === "关系列表.羡愚") return null;
          return undefined;
        }
        const v1 = getByPath(vars, clean, undefined);
        if (v1 !== undefined) return v1;
        const v2 = getByPath(stat, clean, undefined);
        if (v2 !== undefined) return v2;
        for (const s of scopes) {
          if (typeof s.getLocalVar === "function") {
            try {
              const hv = s.getLocalVar(clean);
              if (hv !== undefined && !(hv && typeof hv.then === "function")) return hv;
            } catch {}
          }
        }
        return def;
      };

      const writeVar = (rawPath, val, opts) => {
        const clean = String(rawPath ?? "").trim();
        if (!clean) return;
        if (clean.startsWith("stat_data.")) {
          setByPath(stat, clean.slice("stat_data.".length), val);
        } else {
          vars[clean] = val;
          setByPath(vars, clean, val);
          // 对 char_info / status.externalAvatars 等立绘元数据同步透传至宿主 setLocalVar
          if (/^(?:char_info|status\.external(?:Avatars|Galleries))/.test(clean)) {
            for (const s of scopes) {
              if (typeof s.setLocalVar === "function") {
                try {
                  s.setLocalVar(clean, val, opts);
                  break;
                } catch {}
              }
            }
          }
        }
      };

      const externalLodash = localWin?._ || host?._ || null;
      const _ = createLodashFallback(externalLodash);
      const externalYaml = localWin?.YAML || host?.YAML || null;
      const YAML =
        externalYaml && typeof externalYaml.stringify === "function"
          ? externalYaml
          : { stringify: (obj) => simpleYamlStringify(obj, 0) };

      const getChatMessage = (idx = -1, role = "") => {
        let pool = cleanedMsgs;
        if (role === "user") pool = cleanedMsgs.filter((m) => m.is_user || m.role === "user");
        else if (role === "assistant" || role === "char")
          pool = cleanedMsgs.filter((m) => !m.is_user && m.role !== "user");
        if (!pool.length) {
          if (role === "user") return String(contextData?.lastUserMessage || "");
          if (role === "assistant" || role === "char")
            return String(contextData?.lastCharMessage || "");
          return String(contextData?.lastMessage || "");
        }
        const item = idx < 0 ? pool[pool.length + idx] : pool[idx];
        return String(item?.text ?? item?.message ?? item?.mes ?? "");
      };

      const getChatMessages = (start = -4, end = undefined, role = "") => {
        let pool = cleanedMsgs;
        if (role === "user") pool = cleanedMsgs.filter((m) => m.is_user || m.role === "user");
        else if (role === "assistant" || role === "char")
          pool = cleanedMsgs.filter((m) => !m.is_user && m.role !== "user");
        return pool.slice(start).map((m) => String(m?.text ?? m?.message ?? m?.mes ?? ""));
      };

      const matchChatMessages = (patterns, opts = {}) => {
        const list = Array.isArray(patterns) ? patterns : [patterns];
        const role = opts?.role || "";
        const start = typeof opts?.start === "number" ? opts.start : -4;
        const msgs = getChatMessages(start, undefined, role);
        const joined = msgs.join("\n");
        if (!joined) return false;
        return list.some((p) => {
          if (!p) return false;
          if (p instanceof RegExp) return p.test(joined);
          return joined.includes(String(p));
        });
      };

      const wiRecursionGuard = new Set();
      const getEnabledWorldInfoEntries = () => {
        return Array.isArray(contextData?.enabledWorldInfoEntries)
          ? contextData.enabledWorldInfoEntries
          : [];
      };

      const getwi = (world, uid) => {
        const list = getEnabledWorldInfoEntries();
        const targetUid = uid !== undefined ? uid : world;
        const found = list.find((e) => String(e.uid) === String(targetUid));
        if (!found || !found.content) return "";
        const guardKey = `${found.world || ""}::${found.uid}`;
        if (wiRecursionGuard.has(guardKey)) return "";
        wiRecursionGuard.add(guardKey);
        try {
          const stripped = stripEjsMetaBlocks(found.content, (inner) => {
            compileAndRunEjs(inner, env);
          });
          return compileAndRunEjs(stripped, env);
        } catch {
          return "";
        } finally {
          wiRecursionGuard.delete(guardKey);
        }
      };

      const env = {
        stat_data: stat,
        getMessageVar: (path, opts) => resolveVar(path, opts),
        setMessageVar: (path, val, opts) => writeVar(path, val, opts),
        getLocalVar: (path, opts) => resolveVar(path, opts),
        setLocalVar: (path, val, opts) => writeVar(path, val, opts),
        getGlobalVar: (path, opts) => resolveVar(path, opts),
        setGlobalVar: (path, val, opts) => writeVar(path, val, opts),
        getChatVar: (path, opts) => resolveVar(path, opts),
        setChatVar: (path, val, opts) => writeVar(path, val, opts),
        getvar: (path, opts) => resolveVar(path, opts),
        setvar: (path, val, opts) => writeVar(path, val, opts),
        getChatMessage,
        getChatMessages,
        matchChatMessages,
        getEnabledWorldInfoEntries,
        getwi,
        lastMessageId: lastMsgId,
        lastUserMessageId: Math.max(0, lastMsgId - 1),
        message_id: lastMsgId,
        lastMessage: String(contextData?.lastMessage || ""),
        lastUserMessage: String(contextData?.lastUserMessage || ""),
        lastCharMessage: String(contextData?.lastCharMessage || ""),
        userName,
        charName,
        user: userName,
        char: charName,
        _,
        YAML,
        toastr: { info() {}, success() {}, warning() {}, error() {} },
        alert: () => {},
        $: () => {
          const recentTexts = cleanedMsgs.slice(-4).map((m) => String(m?.text || ""));
          return {
            slice: () => ({
              each: (cb) => {
                recentTexts.forEach((t) => {
                  try {
                    cb.call({ text: () => t });
                  } catch {}
                });
              },
            }),
            each: () => {},
            text: () => recentTexts.join("\n"),
          };
        },
        TavernHelper: {
          getLastMessageId: () => lastMsgId,
          getVariables: () => ({ stat_data: stat, ...vars }),
          insertOrAssignVariables: () => {},
          triggerSlash: (cmd) => (String(cmd || "").includes("{{user}}") ? userName : ""),
        },
      };

      const sandbox = { vars, stat, resolveVar, writeVar, env };
      if (isObj(contextData)) {
        Object.defineProperty(contextData, "_ejsSandbox", {
          value: sandbox,
          enumerable: false,
          configurable: true,
          writable: true,
        });
      }
      return sandbox;
    }

    function evalEjsTemplate(text, sandbox) {
      if (!text || typeof text !== "string") return "";
      let working = stripEjsMetaBlocks(text, (innerBlock) => {
        if (sandbox?.env) {
          compileAndRunEjs(innerBlock, sandbox.env);
        }
      });
      if (!working.includes("<%")) return working;
      try {
        return compileAndRunEjs(working, sandbox.env);
      } catch (err) {
        console.warn("[命定论坛] EJS 模板编译执行异常，已剥离残留 EJS 标签:", err);
        return working.replace(/<%[\s\S]*?%>/g, "");
      }
    }

    function rollDiceExpression(expr) {
      const m = String(expr || "")
        .trim()
        .match(/^(\d+)?d(\d+)([+-]\d+)?$/i);
      if (!m) {
        const n = Number(expr);
        return Number.isFinite(n) && n > 0
          ? String(Math.floor(Math.random() * n) + 1)
          : "1";
      }
      const count = Math.min(100, Math.max(1, Number(m[1] || 1)));
      const sides = Math.max(1, Number(m[2] || 6));
      const mod = Number(m[3] || 0);
      let sum = mod;
      for (let i = 0; i < count; i++) {
        sum += Math.floor(Math.random() * sides) + 1;
      }
      return String(sum);
    }

    function splitMacroList(raw) {
      const s = String(raw || "");
      if (s.includes("::")) return s.split("::").map((x) => x.trim());
      return s.split(",").map((x) => x.trim());
    }

    function evalMacroTemplate(
      templateString,
      contextData = {},
      { host = window.parent || window, localWin = window, replaceXmlTags = true } = {}
    ) {
      if (!templateString || typeof templateString !== "string") return "";
      if (
        !templateString.includes("{{") &&
        !templateString.includes("<%") &&
        !/<(?:user|char|bot)>/i.test(templateString) &&
        typeof contextData?.evaltemplate !== "function"
      ) {
        return templateString;
      }

      const sandbox = getOrInitSandbox(contextData, host, localWin);

      // 0. 预提取 {{setvar::Key::Val}} 到沙箱（供同一条目内的 EJS getvar 读取），再剥离元数据块并执行 EJS
      extractSetvarMacrosToSandbox(templateString, sandbox, true);
      let text = evalEjsTemplate(templateString, sandbox);
      text = stripMutatingMacros(text, sandbox);

      // 若 contextData 提供了自定义 evaltemplate 函数则调用
      if (contextData && typeof contextData.evaltemplate === "function") {
        try {
          text = contextData.evaltemplate(text);
        } catch {}
      }

      const stCtx = getStContext(host, localWin);
      const userName =
        contextData.user ||
        contextData.userName ||
        stCtx?.name1 ||
        "莎莉";
      const charName =
        contextData.char ||
        contextData.charName ||
        stCtx?.name2 ||
        "阿斯塔利亚";

      // 1. 解析任务模板语法 {{task:任务名称}} 与 {{提取写入标签名}} 及自定义字典宏
      if (isObj(contextData.tasks)) {
        text = text.replace(/\{\{\s*task\s*:\s*([^}]+?)\s*\}\}/gi, (_, tName) => {
          const k = String(tName || "").trim();
          return String(contextData.tasks[k] ?? contextData.tasks.default ?? "");
        });
      }

      if (isObj(contextData.extractedTags)) {
        for (const [tagKey, tagVal] of Object.entries(contextData.extractedTags)) {
          const escaped = tagKey.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
          text = text.replace(
            new RegExp(`\\{\\{\\s*${escaped}\\s*\\}\\}`, "gi"),
            () => String(tagVal ?? "")
          );
        }
      }

      if (isObj(contextData.customMacros)) {
        for (const [k, v] of Object.entries(contextData.customMacros)) {
          const val = typeof v === "function" ? String(v() ?? "") : String(v ?? "");
          const escaped = k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
          text = text.replace(new RegExp(`\\{\\{\\s*${escaped}\\s*\\}\\}`, "gi"), () => val);
        }
      }

      // 2. 将 <user> / <char> 归一为标准酒馆宏
      if (replaceXmlTags) {
        text = text
          .replace(/<user>/gi, "{{user}}")
          .replace(/<char>/gi, "{{char}}")
          .replace(/<bot>/gi, "{{char}}");
      }

      // 3. 先用沙箱变量解析 {{getvar::...}} 与 {{hasvar::...}}（确保 EJS setLocalVar / {{setvar}} 写入的值优先命中）
      const resolveVar = (rawKey) => sandbox.resolveVar(rawKey);

      text = text
        .replace(/\{\{\/\/[\s\S]*?\}\}/g, "")
        .replace(/\{\{\s*noop\s*\}\}/gi, "")
        .replace(/\r?\n?\{\{\s*trim\s*\}\}\r?\n?/gi, "")
        .replace(/\{\{\s*has(?:global)?var\s*::\s*([^}]+?)\s*\}\}/gi, (_, keyPath) => {
          return resolveVar(keyPath) !== undefined ? "true" : "false";
        })
        .replace(/\{\{\s*get(?:global)?var\s*::\s*([^}]+?)\s*\}\}/gi, (_, keyPath) => {
          const found = resolveVar(keyPath);
          if (found == null) return "";
          return typeof found === "object" ? JSON.stringify(found) : String(found);
        });

      // 4. 调用酒馆助手 substitudeMacros 或 SillyTavern 原生 substituteParamsExtended / substituteParams
      let nativeEvaluated = false;
      const scopes = getScopes(host, localWin);
      for (const s of scopes) {
        const fn =
          typeof s.substitudeMacros === "function"
            ? s.substitudeMacros.bind(s)
            : typeof s.substituteMacros === "function"
            ? s.substituteMacros.bind(s)
            : null;
        if (fn) {
          try {
            const res = fn(text);
            if (typeof res === "string") {
              text = res;
              nativeEvaluated = true;
              break;
            }
          } catch (err) {
            console.warn("[命定论坛] TavernHelper 宏引擎调用异常，切换备用宏引擎:", err);
          }
        }
      }

      if (!nativeEvaluated && stCtx) {
        try {
          if (typeof stCtx.substituteParamsExtended === "function") {
            text = stCtx.substituteParamsExtended(text, contextData.customMacros || {});
            nativeEvaluated = true;
          } else if (typeof stCtx.substituteParams === "function") {
            text = stCtx.substituteParams(
              text,
              userName,
              charName,
              "",
              "",
              true,
              contextData.customMacros || {}
            );
            nativeEvaluated = true;
          }
        } catch (err) {
          console.warn("[命定论坛] SillyTavern substituteParams 调用异常:", err);
        }
      }

      // 5. 本地兜底宏解析（覆盖 {{$var}}、{{random}}、{{pick}}、{{roll}}、{{user}}、{{char}} 等）
      const now = new Date();
      const weekdays = ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"];

      text = text
        .replace(/\{\{\s*([.$][A-Za-z0-9_.\u4e00-\u9fa5]+)\s*\}\}/g, (_, shortVar) => {
          const found = resolveVar(shortVar);
          if (found == null) return "";
          return typeof found === "object" ? JSON.stringify(found) : String(found);
        })
        .replace(/\{\{\s*(?:random|pick)(?:\s*::\s*|\s*:\s*|\s+)([\s\S]*?)\}\}/gi, (_, listStr) => {
          const items = splitMacroList(listStr).filter(Boolean);
          if (!items.length) return "";
          return items[Math.floor(Math.random() * items.length)];
        })
        .replace(/\{\{\s*roll(?:\s*::\s*|\s*:\s*|\s+)([^}]+?)\s*\}\}/gi, (_, expr) =>
          rollDiceExpression(expr)
        )
        .replace(/\{\{\s*user\s*\}\}/gi, () => userName)
        .replace(/\{\{\s*(?:char|bot)\s*\}\}/gi, () => charName)
        .replace(/\{\{\s*persona\s*\}\}/gi, () => String(contextData.persona || ""))
        .replace(/\{\{\s*description\s*\}\}/gi, () => String(contextData.charDescription || ""))
        .replace(/\{\{\s*scenario\s*\}\}/gi, () => String(contextData.charScenario || ""))
        .replace(/\{\{\s*time\s*\}\}/gi, () =>
          now.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false })
        )
        .replace(/\{\{\s*date\s*\}\}/gi, () => now.toLocaleDateString("zh-CN"))
        .replace(/\{\{\s*isotime\s*\}\}/gi, () => now.toTimeString().slice(0, 8))
        .replace(/\{\{\s*isodate\s*\}\}/gi, () => now.toISOString().slice(0, 10))
        .replace(/\{\{\s*weekday\s*\}\}/gi, () => weekdays[now.getDay()])
        .replace(/\{\{\s*lastMessage\s*\}\}/gi, () => String(contextData.lastMessage || ""))
        .replace(/\{\{\s*lastUserMessage\s*\}\}/gi, () => String(contextData.lastUserMessage || ""))
        .replace(/\{\{\s*lastCharMessage\s*\}\}/gi, () => String(contextData.lastCharMessage || ""))
        .replace(/\{\{\s*maxPrompt\s*\}\}/gi, () => String(contextData.maxTokens || 20000));

      if (replaceXmlTags) {
        text = text
          .replace(/<user>/gi, userName)
          .replace(/<char>/gi, charName)
          .replace(/<bot>/gi, charName);
      }

      return text;
    }

    return {
      evaluate: evalMacroTemplate,
      evalMacroTemplate,
      stripEjsMetaBlocks,
      evalEjsTemplate,
      extractSetvarMacrosToSandbox,
      getOrInitSandbox,
      hasMacros,
      getStContext,
      stripMutatingMacros,
    };
  })();

  /* ============================================================================
   * 5.5 SillyTavern 文生图插件 (st-chatu8) 桥接器 (ForumChatu8Bridge)
   *     - 自动读取 st-chatu8 的 extension_settings 配置（角色预设、通用模板、服装预设、起止标签）
