          if (s.document?.getElementById("st-chatu8-settings-container")) return true;
        } catch {}
      }
      return false;
    }

    // 复刻 st-chatu8 原生 generateCharacterListText：生成 {{角色启用列表}}
    function generateCharacterListText(host, localWin) {
      const ext = getChatu8Settings(host, localWin);
      if (!ext) return "无";
      const enablePresetId = ext.characterEnablePresetId || "default";
      const enablePresets = ext.characterEnablePresets || {};
      const currentPreset = enablePresets[enablePresetId];
      if (
        !currentPreset ||
        !Array.isArray(currentPreset.characters) ||
        currentPreset.characters.length === 0
      ) {
        return "无";
      }
      const charPresets = ext.characterPresets || {};
      const outfitPresets = ext.outfitPresets || {};
      const lines = [];
      let idx = 1;
      for (const charKey of currentPreset.characters) {
        const c = charPresets[charKey];
        if (!c) continue;
        const nameCN = c.nameCN || charKey;
        const nameEN = c.nameEN || charKey;
        let line = `${idx}.人物名称:${nameCN}-${nameEN}`;
        if (Array.isArray(c.outfits) && c.outfits.length > 0) {
          const outfitParts = [];
          for (const oKey of c.outfits) {
            const o = outfitPresets[oKey];
            if (o) {
              outfitParts.push(`${o.nameCN || oKey}-${o.nameEN || oKey}`);
            }
          }
          if (outfitParts.length > 0) {
            line += " 人物专属服装:" + outfitParts.join("，");
          }
        }
        lines.push(line);
        idx++;
      }
      return lines.length > 0 ? lines.join("\n") : "无";
    }

    // 复刻 st-chatu8 原生 generateCommonCharacterListText：生成 {{通用角色启用列表}}
    function generateCommonCharacterListText(host, localWin) {
