        a = II(a, b, c, d, x[k + 0], S41, 0xf4292244);
        d = II(d, a, b, c, x[k + 7], S42, 0x432aff97);
        c = II(c, d, a, b, x[k + 14], S43, 0xab9423a7);
        b = II(b, c, d, a, x[k + 5], S44, 0xfc93a039);
        a = II(a, b, c, d, x[k + 12], S41, 0x655b59c3);
        d = II(d, a, b, c, x[k + 3], S42, 0x8f0ccc92);
        c = II(c, d, a, b, x[k + 10], S43, 0xffeff47d);
        b = II(b, c, d, a, x[k + 1], S44, 0x85845dd1);
        a = II(a, b, c, d, x[k + 8], S41, 0x6fa87e4f);
        d = II(d, a, b, c, x[k + 15], S42, 0xfe2ce6e0);
        c = II(c, d, a, b, x[k + 6], S43, 0xa3014314);
        b = II(b, c, d, a, x[k + 13], S44, 0x4e0811a1);
        a = II(a, b, c, d, x[k + 4], S41, 0xf7537e82);
        d = II(d, a, b, c, x[k + 11], S42, 0xbd3af235);
        c = II(c, d, a, b, x[k + 2], S43, 0x2ad7d2bb);
        b = II(b, c, d, a, x[k + 9], S44, 0xeb86d391);
        a = addUnsigned(a, AA);
        b = addUnsigned(b, BB);
        c = addUnsigned(c, CC);
        d = addUnsigned(d, DD);
      }
      return (wordToHex(a) + wordToHex(b) + wordToHex(c) + wordToHex(d)).toLowerCase();
    }

    function computeTagMd5(pureTag, host, localWin) {
      for (const s of getScopes(host, localWin)) {
        try {
          const cjs = s.stChatu8CryptoJS || s.CryptoJS;
          if (cjs && typeof cjs.MD5 === "function") {
            return cjs.MD5(String(pureTag || "")).toString();
          }
        } catch {}
      }
      return md5Fallback(String(pureTag || ""));
    }

    function arrayBufferToBase64(buffer) {
      let binary = "";
      const bytes = new Uint8Array(buffer);
      const len = bytes.byteLength;
      for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
      }
      return window.btoa(binary);
    }

    // 从 st-chatu8 的 IndexedDB (chatu8_gallery -> tupianhuancun) 或 jiuguanStorage 读取已生成的缓存图片
    async function getCachedImage(pureTag, host, localWin) {
      const cleanTag = String(pureTag || "").trim();
      if (!cleanTag) return null;
      if (memoryImageCache.has(cleanTag)) {
        return memoryImageCache.get(cleanTag);
      }
      const md5Key = computeTagMd5(cleanTag, host, localWin);

      // 1. 检查 jiuguanStorage 服务端路径缓存
      try {
        const ext = getChatu8Settings(host, localWin);
        const jg = ext?.jiuguanStorage?.[md5Key];
        if (jg && Array.isArray(jg.images) && jg.images.length > 0) {
          const idx = Math.min(Math.max(0, Number(jg.index) || 0), jg.images.length - 1);
          const item = jg.images[idx] || jg.images[jg.images.length - 1];
          if (item?.path) {
            const cachedObj = {
              imageData: item.path,
              isVideo: Boolean(item.isVideo),
              prompt: cleanTag,
              source: "server",
            };
            memoryImageCache.set(cleanTag, cachedObj);
            return cachedObj;
          }
        }
      } catch {}

      // 2. 检查 IndexedDB chatu8_gallery -> tupianhuancun
      const idb = host?.indexedDB || localWin?.indexedDB || window.indexedDB;
      if (!idb) return null;

      return new Promise((resolve) => {
        try {
          const req = idb.open("chatu8_gallery");
          req.onerror = () => resolve(null);
          req.onsuccess = (ev) => {
            const db = ev.target.result;
            if (!db.objectStoreNames.contains("tupianhuancun")) {
              db.close();
              resolve(null);
              return;
            }
            try {
              const tx = db.transaction(["tupianhuancun"], "readonly");
              const store = tx.objectStore("tupianhuancun");
              const metaReq = store.get("tupianshuju");
              metaReq.onerror = () => {
                db.close();
                resolve(null);
              };
              metaReq.onsuccess = () => {
                const meta = metaReq.result?.data;
                const entry = meta?.[md5Key];
                if (!entry || !Array.isArray(entry.images) || entry.images.length === 0) {
                  db.close();
                  resolve(null);
                  return;
                }
                const idx = Math.min(
                  Math.max(0, Number(entry.index) || 0),
                  entry.images.length - 1
                );
                const imgMeta = entry.images[idx] || entry.images[entry.images.length - 1];
                if (!imgMeta?.uuid) {
                  db.close();
                  resolve(null);
                  return;
                }
                const dataReq = store.get(imgMeta.uuid);
                dataReq.onerror = () => {
                  db.close();
                  resolve(null);
                };
                dataReq.onsuccess = () => {
                  const rec = dataReq.result;
                  db.close();
                  if (rec && rec.data) {
                    const isVideo = Boolean(imgMeta.isVideo);
                    const mime = isVideo ? "video/mp4" : "image/png";
                    const base64Url =
                      typeof rec.data === "string"
                        ? rec.data.startsWith("data:")
                          ? rec.data
                          : `data:${mime};base64,${rec.data}`
                        : `data:${mime};base64,${arrayBufferToBase64(rec.data)}`;
                    const cachedObj = {
                      imageData: base64Url,
                      isVideo,
                      prompt: cleanTag,
                      source: "indexeddb",
                    };
                    memoryImageCache.set(cleanTag, cachedObj);
                    resolve(cachedObj);
                  } else {
                    resolve(null);
                  }
                };
              };
            } catch {
              db.close();
              resolve(null);
            }
          };
        } catch {
          resolve(null);
        }
      });
    }

    // 绑定 SillyTavern eventSource 的 generate-image-response 事件
    function ensureResponseListener(host, localWin) {
      if (listenerBound) return;
      const handleResponse = (payload) => {
        if (!payload || !payload.id) return;
        if (payload.success && payload.imageData && payload.prompt) {
          memoryImageCache.set(String(payload.prompt).trim(), {
            imageData: payload.imageData,
            isVideo: Boolean(payload.isVideo),
            format: payload.format || "png",
            originalUrl: payload.originalUrl || "",
            prompt: payload.prompt,
          });
        }
        const entry = pendingCallbacks.get(payload.id);
        if (entry) {
          pendingCallbacks.delete(payload.id);
          clearTimeout(entry.timer);
          entry.resolve(payload);
        }
      };

      for (const s of getScopes(host, localWin)) {
        try {
          const evSrc = s.SillyTavern?.getContext?.()?.eventSource || s.eventSource;
          if (evSrc && typeof evSrc.on === "function" && !boundEventSources.includes(evSrc)) {
            evSrc.on(EVENT_GENERATE_RESPONSE, handleResponse);
            boundEventSources.push({ evSrc, fn: handleResponse });
            listenerBound = true;
          }
        } catch {}
      }

      const evOn =
        typeof eventOn === "function"
          ? eventOn
          : localWin?.eventOn || host?.eventOn || localWin?.TavernHelper?.eventOn || host?.TavernHelper?.eventOn;
      if (typeof evOn === "function" && !listenerBound) {
        try {
          evOn(EVENT_GENERATE_RESPONSE, handleResponse);
          listenerBound = true;
        } catch {}
      }
    }

    // 触发 st-chatu8 生成图片
    function requestImageGeneration({ purePrompt, host, localWin, change, width = null, height = null, timeoutMs = 180000 }) {
      const cleanPrompt = String(purePrompt || "").trim();
      if (!cleanPrompt) {
        return Promise.reject(new Error("画图提示词 Tag 为空"));
      }
      ensureResponseListener(host, localWin);

      const requestId = `${generateStableId(cleanPrompt)}-forum-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;

      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          pendingCallbacks.delete(requestId);
          reject(
            new Error(
              "等待 st-chatu8 生图响应超时（180s）。请确认已启用 st-chatu8 插件且后端（SD / NAI / ComfyUI / Nano Banana）连接正常。"
            )
          );
        }, timeoutMs);

        pendingCallbacks.set(requestId, {
          timer,
          resolve: (res) => {
            if (res && res.success && res.imageData) {
              memoryImageCache.set(cleanPrompt, {
                imageData: res.imageData,
                isVideo: Boolean(res.isVideo),
                format: res.format || "png",
                originalUrl: res.originalUrl || "",
                prompt: cleanPrompt,
              });
              resolve(res);
            } else {
              reject(new Error(res?.error || "st-chatu8 生图未返回有效图像数据"));
            }
          },
        });

        const reqPayload = {
          id: requestId,
          prompt: cleanPrompt,
          width,
          height,
          change,
        };

        let emitted = false;
        for (const s of getScopes(host, localWin)) {
          try {
            const evSrc = s.SillyTavern?.getContext?.()?.eventSource || s.eventSource;
            if (evSrc && typeof evSrc.emit === "function") {
              evSrc.emit(EVENT_GENERATE_REQUEST, reqPayload);
              emitted = true;
              break;
            }
          } catch {}
        }

        if (!emitted) {
          const evEmit =
            typeof eventEmit === "function"
              ? eventEmit
              : localWin?.eventEmit ||
                host?.eventEmit ||
                localWin?.TavernHelper?.eventEmit ||
                host?.TavernHelper?.eventEmit;
          if (typeof evEmit === "function") {
            try {
              evEmit(EVENT_GENERATE_REQUEST, reqPayload);
              emitted = true;
            } catch {}
          }
        }

        if (!emitted) {
          clearTimeout(timer);
          pendingCallbacks.delete(requestId);
          reject(
            new Error(
              "未能连接到酒馆 eventSource 事件总线，请确认 SillyTavern 与 st-chatu8 插件已正常加载。"
            )
          );
        }
      });
    }

    // 解析帖子或 .ast-img 内的 <image>...image###...###</image> 及自定义前后缀标签（含超强容错与深度剥离思考链）
    function extractImagePromptFromText(rawText, host, localWin) {
      let text = String(rawText || "").trim();
      if (!text) return null;

      // 彻底剥离可能存在的模型思考链（如 DeepSeek-R1 / Gemini / Claude <think> 标签）与代码围栏
      text = text
        .replace(/<(?:recorder_thinking|thinking|think)\b[^>]*>[\s\S]*?<\/(?:recorder_thinking|thinking|think)>/gi, "")
        .replace(/^```(?:html|xml)?\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

      let imgThinkContent = "";
      const thinkMatch = text.match(/<imgthink\b[^>]*>([\s\S]*?)<\/imgthink>/i);
      if (thinkMatch) {
        imgThinkContent = thinkMatch[1].trim();
      }

      // 1. 优先匹配标准 image###...###（兼容末尾 ### 遗漏或被截断的情况）
      const stdMatch = text.match(/image###([\s\S]*?)(?:###|<\/image>|$)/i);
      if (stdMatch && stdMatch[1].trim()) {
        const cleaned = stdMatch[1]
          .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>/gi, "")
          .replace(/\r?\n/g, " ")
          .replace(/\s{2,}/g, " ")
          .trim();
        if (cleaned) {
          return {
            purePrompt: cleaned,
            imgThink: imgThinkContent,
          };
        }
      }

      // 2. 兼容 st-chatu8 自定义 startTag / endTag
      const ext = getChatu8Settings(host, localWin);
      const startTag = ext?.startTag && ext.startTag !== "image###" ? ext.startTag : null;
      const endTag = ext?.endTag || "###";
      if (startTag && endTag) {
        try {
          const escStart = startTag.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&");
          const escEnd = endTag.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&");
          const customRe = new RegExp(`${escStart}([\s\S]*?)(?:${escEnd}|<\/image>|$)`, "i");
          const cMatch = text.match(customRe);
          if (cMatch && cMatch[1].trim()) {
            const cleaned = cMatch[1]
              .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>/gi, "")
              .replace(/\r?\n/g, " ")
              .replace(/\s{2,}/g, " ")
              .trim();
            if (cleaned) {
              return {
                purePrompt: cleaned,
                imgThink: imgThinkContent,
              };
            }
          }
        } catch {}
      }

      // 3. 匹配 <image>...</image> 内部除去 <imgthink> 后的英文 Tag
      const imageBlockMatch = text.match(/<image\b[^>]*>([\s\S]*?)(?:<\/image>|$)/i);
      if (imageBlockMatch) {
        const inner = imageBlockMatch[1]
          .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>/gi, "")
          .replace(/^\s*image###/i, "")
          .replace(/###\s*$/i, "")
          .replace(/\r?\n/g, " ")
          .replace(/\s{2,}/g, " ")
          .trim();
        if (inner && inner.length >= 4) {
          return {
            purePrompt: inner,
            imgThink: imgThinkContent,
          };
        }
      }

      // 4. 容错兜底：若模型直接输出了逗号分隔的英文 Stable Diffusion Tag（如 nsfw, 1girl...）或以 Prompt:/Tags: 开头
      const linesArr = text.split(/\r?\n/);
      for (const line of linesArr) {
        const trimmed = line.replace(/^(?:prompt|tags|positive|正面提示词)\s*[:：]\s*/i, "").trim();
        if (
          trimmed.includes(",") &&
          /(?:nsfw|1girl|1boy|solo|breasts|thighs|hair|eyes|dress|skin|body|cum|pussy|penis|sex|masterpiece|best quality|ass)/i.test(trimmed)
        ) {
          const cleanLine = trimmed
            .replace(/^image###/i, "")
            .replace(/###$/i, "")
            .trim();
          if (cleanLine) {
            return {
              purePrompt: cleanLine,
              imgThink: imgThinkContent,
            };
          }
        }
      }

      return null;
    }

    function dispose() {
      for (const { evSrc, fn } of boundEventSources) {
        try {
          evSrc.removeListener?.(EVENT_GENERATE_RESPONSE, fn);
          evSrc.off?.(EVENT_GENERATE_RESPONSE, fn);
        } catch {}
      }
      boundEventSources = [];
      for (const { timer } of pendingCallbacks.values()) {
        clearTimeout(timer);
      }
      pendingCallbacks.clear();
      listenerBound = false;
    }

    return {
      getChatu8Settings,
      isPluginInstalled,
      generateCharacterListText,
      generateCommonCharacterListText,
      generateOutfitEnableListText,
      generateStableId,
      getCachedImage,
      requestImageGeneration,
      extractImagePromptFromText,
      dispose,
    };
  })();

  /* ============================================================================
   * 6. 世界书获取与扫描器 (checkWorldInfo & checkAndScanWorldbooks)
   * ============================================================================ */
  const ForumWorldbookScanner = (() => {
    const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
    const str = (v) => (typeof v === "string" || typeof v === "number" ? String(v).trim() : "");

    function getScopes(host, localWin) {
      return [
        ...new Set(
          [localWin, host, localWin?.TavernHelper, host?.TavernHelper].filter(Boolean)
        ),
      ];
    }

    function findMethod(scopes, name) {
      for (const s of scopes) {
        if (typeof s[name] === "function") return s[name].bind(s);
      }
      return null;
    }

    function splitKeyStringPreservingRegexAndMacros(rawStr) {
      const s = String(rawStr || "").trim();
      if (!s) return [];
      if (/^\/.+\/[gimsuy]*$/.test(s)) return [s];
      const result = [];
      let current = "";
      let braceDepth = 0;
      let inRegex = false;
      for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        const next = s[i + 1];
        if (!inRegex && ch === "{" && next === "{") {
          braceDepth++;
          current += "{{";
          i++;
          continue;
        }
        if (!inRegex && ch === "}" && next === "}" && braceDepth > 0) {
          braceDepth--;
          current += "}}";
          i++;
          continue;
        }
        if (braceDepth === 0 && ch === "/" && (i === 0 || s[i - 1] !== "\\")) {
          if (!inRegex && current.trim() === "") {
            inRegex = true;
          } else if (inRegex) {
            inRegex = false;
          }
        }
        if (!inRegex && braceDepth === 0 && ch === ",") {
          const trimmed = current.trim();
          if (trimmed) result.push(trimmed);
          current = "";
        } else {
          current += ch;
        }
      }
      const tail = current.trim();
      if (tail) result.push(tail);
      return result;
    }

    function normalizeKeyItem(item) {
      if (!item && item !== 0) return [];
      if (item instanceof RegExp || Object.prototype.toString.call(item) === "[object RegExp]") {
        return [`/${item.source}/${item.flags || ""}`];
      }
      if (isObj(item)) {
        const src = str(item.regex ?? item.pattern ?? item.key ?? item.value);
        if (!src) return [];
        if (item.regex || item.pattern) {
          return [`/${src.replace(/^\/|\/[gimsuy]*$/g, "")}/${str(item.flags)}`];
        }
        return splitKeyStringPreservingRegexAndMacros(src);
      }
      if (typeof item === "string" || typeof item === "number") {
        const s = String(item).trim();
        if (!s) return [];
        return [s];
      }
      return [];
    }

    function normalizeKeyArray(rawKeys) {
      if (Array.isArray(rawKeys)) {
        const out = [];
        for (const k of rawKeys) {
          for (const norm of normalizeKeyItem(k)) {
            if (norm) out.push(norm);
          }
        }
        return out;
      }
      if (typeof rawKeys === "string") {
        return splitKeyStringPreservingRegexAndMacros(rawKeys);
      }
      if (rawKeys instanceof RegExp || isObj(rawKeys)) {
        return normalizeKeyItem(rawKeys);
      }
      return [];
    }

    function normalizeSelectiveLogic(rawLogic) {
      if (typeof rawLogic === "number") {
        if (rawLogic === 0) return "and_any";
        if (rawLogic === 1) return "not_all";
        if (rawLogic === 2) return "not_any";
        if (rawLogic === 3) return "and_all";
      }
      if (typeof rawLogic === "string") {
        const lower = rawLogic.toLowerCase().trim().replace(/[\s-]+/g, "_");
        if (lower === "0" || lower === "and_any" || lower === "andany") return "and_any";
        if (lower === "1" || lower === "not_all" || lower === "notall") return "not_all";
        if (lower === "2" || lower === "not_any" || lower === "notany") return "not_any";
        if (lower === "3" || lower === "and_all" || lower === "andall") return "and_all";
      }
      return "and_any";
    }

    function normalizePositionType(rawPos) {
      if (typeof rawPos === "string") {
        const lower = rawPos.toLowerCase().trim();
        if (lower) return lower;
      }
      if (typeof rawPos === "number") {
        const map = {
          0: "before_character_definition",
          1: "after_character_definition",
          2: "before_author_note",
          3: "after_author_note",
          4: "at_depth",
          5: "before_example_messages",
          6: "after_example_messages",
        };
        return map[rawPos] || "before_character_definition";
      }
      return "before_character_definition";
    }

    function normalizeRole(rawRole) {
      if (typeof rawRole === "string") {
        const lower = rawRole.toLowerCase().trim();
        if (["system", "user", "assistant"].includes(lower)) return lower;
      }
      if (rawRole === 1) return "user";
      if (rawRole === 2) return "assistant";
      return "system";
    }

    function normalizeEntry(rawEntry, bookName, index) {
      if (!isObj(rawEntry)) return null;
      const enabled = rawEntry.enabled !== false && rawEntry.disable !== true;
      const content = str(rawEntry.content);
      if (!enabled || !content) return null;

      const name = str(rawEntry.name || rawEntry.comment || `条目#${rawEntry.uid ?? index}`);
      const strategyObj = isObj(rawEntry.strategy) ? rawEntry.strategy : {};
      const posObj = isObj(rawEntry.position) ? rawEntry.position : {};
      const recObj = isObj(rawEntry.recursion) ? rawEntry.recursion : {};

      let strategyType = "selective";
      if (strategyObj.type === "constant" || rawEntry.constant === true) {
        strategyType = "constant";
      } else if (strategyObj.type === "vectorized" || rawEntry.vectorized === true) {
        strategyType = "vectorized";
      }

      // 主要关键词 (Primary Keys)
      const keys = normalizeKeyArray(
        strategyObj.keys ?? rawEntry.key ?? rawEntry.keys ?? rawEntry.primary_keys
      );

      // 可选过滤器 (Optional Filter / Secondary Keys + Selective Logic)
      // 在 SillyTavern 原生结构中，selective=false 表示禁用次要关键词过滤器；默认或 TavernHelper keys_secondary 存在时启用
      const selectiveFilterEnabled =
        rawEntry.selective === false && !isObj(strategyObj.keys_secondary) ? false : true;
      const secObj = isObj(strategyObj.keys_secondary) ? strategyObj.keys_secondary : {};
      const secondaryKeys = selectiveFilterEnabled
        ? normalizeKeyArray(
            secObj.keys ??
              rawEntry.keysecondary ??
              rawEntry.keys_secondary ??
              rawEntry.secondary_keys ??
              rawEntry.keySecondary
          )
        : [];
      const secondaryLogic = normalizeSelectiveLogic(
        secObj.logic ??
          rawEntry.selectiveLogic ??
          rawEntry.selective_logic ??
          rawEntry.secondary_logic
      );

      const rawScanDepth =
        strategyObj.scan_depth ?? rawEntry.scanDepth ?? rawEntry.scan_depth;
      const parsedScanDepth =
        rawScanDepth !== null &&
        rawScanDepth !== undefined &&
        rawScanDepth !== "" &&
        rawScanDepth !== "same_as_global"
          ? Number(rawScanDepth)
          : NaN;
      const scanDepth =
        Number.isFinite(parsedScanDepth) && parsedScanDepth >= 0 ? parsedScanDepth : null;

      const positionType = normalizePositionType(posObj.type ?? rawEntry.position);
      const order = Number.isFinite(Number(posObj.order ?? rawEntry.order ?? rawEntry.insertion_order))
        ? Number(posObj.order ?? rawEntry.order ?? rawEntry.insertion_order)
        : 100;
      const depth = Number.isFinite(Number(posObj.depth ?? rawEntry.depth))
        ? Number(posObj.depth ?? rawEntry.depth)
        : 4;
      const role = normalizeRole(posObj.role ?? rawEntry.role);

      const probability = Number.isFinite(Number(rawEntry.probability ?? rawEntry.prob))
        ? Number(rawEntry.probability ?? rawEntry.prob)
        : 100;
      const useProbability = rawEntry.use_probability !== false && rawEntry.useProbability !== false;

      const caseSensitive = Boolean(
        strategyObj.case_sensitive ??
          strategyObj.caseSensitive ??
          rawEntry.case_sensitive ??
          rawEntry.caseSensitive ??
          false
      );
      const matchWholeWords = Boolean(
        strategyObj.match_whole_words ??
          strategyObj.matchWholeWords ??
          rawEntry.match_whole_words ??
          rawEntry.matchWholeWords ??
          false
      );

      const preventIncoming = Boolean(
        recObj.prevent_incoming ??
          rawEntry.excludeRecursion ??
          rawEntry.exclude_recursion ??
          false
      );
      const preventOutgoing = Boolean(
        recObj.prevent_outgoing ??
          rawEntry.preventRecursion ??
          rawEntry.prevent_recursion ??
          false
      );
      const delayUntil = Number.isFinite(
        Number(
          recObj.delay_until ??
            rawEntry.delayUntilRecursion ??
            rawEntry.delay_until_recursion
        )
      )
        ? Number(
            recObj.delay_until ??
              rawEntry.delayUntilRecursion ??
              rawEntry.delay_until_recursion
          )
        : 0;

      return {
        uid: `${bookName}::${rawEntry.uid ?? index}`,
        rawUid: rawEntry.uid ?? index,
        bookName,
        name,
        content,
        strategyType,
        selectiveFilterEnabled,
        keys,
        secondaryKeys,
        secondaryLogic,
        scanDepth,
        positionType,
        order,
        depth,
        role,
        probability,
        useProbability,
        caseSensitive,
        matchWholeWords,
        preventIncoming,
        preventOutgoing,
        delayUntil,
      };
    }

    function isMainChatTechnicalNoise(entry, forumMode) {
      const title = entry.name;
      const body = entry.content;

      // 彻底剥离我们为酒馆主聊天 AI 同步写入的蓝灯世界书条目，防止论坛自身推演重复读取
      if (
        title.includes("【命定论坛】已注入行动线索") ||
        title.includes("已注入行动线索变量树") ||
        body.includes("<forum_data_variables")
      ) {
        return true;
      }

      if (/论坛|命定论坛|Astaria\s*Astral/i.test(title)) {
        if (forumMode === "surface" && /里版论坛/.test(title) && !/表版/.test(title)) {
          return true;
        }
        if (forumMode === "dark" && /表版/.test(title) && !/里版/.test(title)) {
          return true;
        }
        return false;
      }

      if (forumMode === "surface" && /性服务产业|淫乱|调教指南/.test(title)) {
        return true;
      }

      const noiseTitlePattern =
        /变量更新|变量初始化|变量列表|UpdateVariable|状态栏|输出格式|格式要求|思维链|thinking|recorder_thinking|战斗协议|战斗检定|生产制作协议|检定公式|行动选项|options要求|字数要求|文风要求|正文要求|写作规范|防代写|视角要求|开局初始化/i;
      if (noiseTitlePattern.test(title)) {
        return true;
      }

      if (
        /<UpdateVariable>|JSON\s*Patch|stat_data\s*更新|<gametxt>|<action_options>/i.test(body) &&
        !/虚海规则|世界主设定|生命层级|种族|势力|地理|命定论坛|规则/.test(title)
      ) {
        return true;
      }

      return false;
    }

    // 发现当前所有可用世界书（角色主世界书 + 附加世界书 + 聊天世界书 + 全局世界书）
    async function discoverActiveLorebooks(host, localWin) {
      const scopes = getScopes(host, localWin);
      const charBooks = [];
      const globalBooks = [];
      const addUnique = (arr, b) => {
        const name = str(b);
        if (name && !arr.includes(name)) arr.push(name);
      };

      const getCharBooks = findMethod(scopes, "getCharLorebooks");
      if (getCharBooks) {
        try {
          const res = await getCharBooks();
          if (isObj(res)) {
            addUnique(charBooks, res.primary);
            if (Array.isArray(res.additional)) {
              res.additional.forEach((b) => addUnique(charBooks, b));
            }
          } else if (Array.isArray(res)) {
            res.forEach((b) => addUnique(charBooks, b));
          }
        } catch {}
      }

      const getPrimary = findMethod(scopes, "getCurrentCharPrimaryLorebook");
      if (getPrimary) {
        try {
          addUnique(charBooks, await getPrimary());
        } catch {}
      }

      const getChatBook = findMethod(scopes, "getChatLorebook");
      if (getChatBook) {
        try {
          addUnique(charBooks, await getChatBook());
        } catch {}
      }

      const getGlobalBooks = findMethod(scopes, "getGlobalLorebooks");
      if (getGlobalBooks) {
        try {
          const globals = await getGlobalBooks();
          if (Array.isArray(globals)) globals.forEach((b) => addUnique(globalBooks, b));
        } catch {}
      }

      const stCtx = ForumMacroEngine.getStContext(host, localWin);
      if (stCtx) {
        try {
          const charObj = stCtx.characters?.[stCtx.characterId];
          addUnique(charBooks, charObj?.data?.extensions?.world || charObj?.world);
          const extraWorlds = charObj?.data?.extensions?.extra_world_info;
          if (Array.isArray(extraWorlds)) extraWorlds.forEach((b) => addUnique(charBooks, b));
          addUnique(charBooks, stCtx.chatMetadata?.world_info);
          const globalSelect = stCtx.worldInfo?.globalSelect;
          if (Array.isArray(globalSelect)) globalSelect.forEach((b) => addUnique(globalBooks, b));
        } catch {}
      }

      const allLorebooks = [];
      [...charBooks, ...globalBooks].forEach((b) => addUnique(allLorebooks, b));
      return { charLorebooks: charBooks, globalLorebooks: globalBooks, allLorebooks };
    }

    async function loadEntriesFromBooks(host, localWin, bookNames) {
      const scopes = getScopes(host, localWin);
      const getEntries = findMethod(scopes, "getLorebookEntries");
      const allNormalized = [];

      if (getEntries && bookNames.length > 0) {
        const results = await Promise.all(
          bookNames.map(async (bName) => {
            try {
              const rawList = await getEntries(bName);
              if (Array.isArray(rawList)) return { bName, rawList };
              if (isObj(rawList?.entries)) {
                return { bName, rawList: Object.values(rawList.entries) };
              }
            } catch (err) {
              console.warn(`[命定论坛] 读取世界书「${bName}」条目失败:`, err);
            }
            return { bName, rawList: [] };
          })
        );

        for (const { bName, rawList } of results) {
          rawList.forEach((raw, idx) => {
            const norm = normalizeEntry(raw, bName, idx);
            if (norm) allNormalized.push(norm);
          });
        }
      }

      if (allNormalized.length === 0) {
        const stCtx = ForumMacroEngine.getStContext(host, localWin);
        const charObj = stCtx?.characters?.[stCtx?.characterId];
        const charBook = charObj?.data?.character_book;
        const rawEntries = Array.isArray(charBook?.entries)
          ? charBook.entries
          : isObj(charBook?.entries)
          ? Object.values(charBook.entries)
          : [];
        const bName = str(charBook?.name || charObj?.name || "角色内嵌世界书");
        rawEntries.forEach((raw, idx) => {
          const norm = normalizeEntry(raw, bName, idx);
          if (norm) allNormalized.push(norm);
        });
      }

      return allNormalized;
    }

    function testPreparedNeedle(needleStr, haystack, caseSensitive, matchWholeWords) {
      const trimmed = String(needleStr || "").trim();
      if (!trimmed || !haystack) return false;

      const regexMatch = trimmed.match(/^\/(.+)\/([gimsuy]*)$/);
      if (regexMatch) {
        try {
          let flags = regexMatch[2] || "";
          if (!caseSensitive && !flags.includes("i")) {
            flags += "i";
          }
          const re = new RegExp(regexMatch[1], flags);
          re.lastIndex = 0;
          return re.test(haystack);
        } catch {}
      }

      const targetText = caseSensitive ? haystack : haystack.toLowerCase();
      const needle = caseSensitive ? trimmed : trimmed.toLowerCase();

      if (matchWholeWords && /^[A-Za-z0-9_]+$/.test(needle)) {
        const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const re = new RegExp(`\\b${escaped}\\b`, caseSensitive ? "" : "i");
        return re.test(haystack);
      }

      return targetText.includes(needle);
    }

    function expandKeyCandidates(rawKey, macroEnv, host, localWin) {
      if (!rawKey && rawKey !== 0) return [];
      if (rawKey instanceof RegExp || Object.prototype.toString.call(rawKey) === "[object RegExp]") {
        return [`/${rawKey.source}/${rawKey.flags || ""}`];
      }
      const rawStr = String(rawKey).trim();
      if (!rawStr) return [];

      // 若是纯正则表达式且不含酒馆宏/EJS，直接保留正则避免花括号量词 {1,3} 被误处理
      if (/^\/.+\/[gimsuy]*$/.test(rawStr) && !/\{\{[\s\S]+?\}\}|<%[\s\S]*?%>/.test(rawStr)) {
        return [rawStr];
      }

      // 纯文本关键词短路：不含宏/EJS/<user>/<char> 时直接切分返回，避免上千次无意义跨上下文宏调用
      if (!ForumMacroEngine.hasMacros(rawStr)) {
        return rawStr.includes(",")
          ? rawStr.split(",").map((s) => s.trim()).filter(Boolean)
          : [rawStr];
      }

      const expanded = ForumMacroEngine.evalMacroTemplate(rawStr, macroEnv, {
        host,
        localWin,
        replaceXmlTags: true,
      }).trim();
      if (!expanded) return [];

      if (/^\/.+\/[gimsuy]*$/.test(expanded)) {
        return [expanded];
      }

      // 若包含逗号（如同一个关键词框内写了多个逗号分隔词，或宏展开后为逗号分隔词），拆分为独立候选词
      if (expanded.includes(",")) {
        return expanded
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean);
      }
      return [expanded];
    }

    // 单条目激活判定 checkWorldInfo(entry, context)
    // 严格遵循酒馆世界书规则：
    // - 蓝灯 (constant)：常驻激活
    // - 绿灯 (selective)：【主要关键词 (keys) 至少命中 1 个】 ➕ 【可选过滤器 (secondaryKeys + secondaryLogic) 满足对应逻辑】
    function checkWorldInfo(entry, scanContext) {
      const {
        scanMessages = [],
        taskScanText = "",
        recursionBuffer = "",
        defaultScanDepth = 2,
        macroEnv = {},
        host,
        localWin,
        isRecursionPass = false,
        recursionStep = 0,
      } = scanContext;

      if (!entry) return false;
      if (entry.useProbability && entry.probability < 100) {
        if (entry.probability <= 0 || Math.random() * 100 > entry.probability) {
          return false;
        }
      }

      // 1. 蓝灯 (constant) 条目：首轮直接激活（不参与递归轮重复触发）
      if (entry.strategyType === "constant") {
        return !isRecursionPass;
      }

      // 2. 绿灯 (selective / vectorized) 条目：检查递归限制与延迟轮数
      if (isRecursionPass && entry.preventIncoming) return false;
      if (entry.delayUntil > recursionStep) return false;

      // 展开并获取有效的主要关键词列表
      const primaryCandidates = [];
      for (const rawK of entry.keys || []) {
        const expandedList = expandKeyCandidates(rawK, macroEnv, host, localWin);
        for (const item of expandedList) {
          if (item) primaryCandidates.push(item);
        }
      }
      // 绿灯条目必须至少配置 1 个有效主要关键词
      if (!primaryCandidates.length) return false;

      // 按条目独立 scanDepth 或默认 defaultScanDepth 截取最近 N 条聊天记录 + 当前论坛任务上下文 + 递归缓冲池
      const effectiveDepth =
        entry.scanDepth != null ? Math.max(0, entry.scanDepth) : Math.max(1, defaultScanDepth);
      const chatSlice = effectiveDepth > 0 ? scanMessages.slice(0, effectiveDepth) : [];
      const haystackParts = [];
      if (taskScanText) haystackParts.push(taskScanText);
      if (chatSlice.length) haystackParts.push(chatSlice.join("\n"));
      if (recursionBuffer) haystackParts.push(recursionBuffer);
      const haystack = haystackParts.join("\n");
      if (!haystack) return false;

      // 第一步：主要关键词 (Primary Keys) 判定 —— 至少命中其中 1 个主要关键词
      const primaryHit = primaryCandidates.some((cand) =>
        testPreparedNeedle(cand, haystack, entry.caseSensitive, entry.matchWholeWords)
      );
      if (!primaryHit) return false;

      // 第二步：可选过滤器 (Optional Filter / Secondary Keys) 判定
      if (entry.selectiveFilterEnabled === false || !Array.isArray(entry.secondaryKeys) || !entry.secondaryKeys.length) {
        return true;
      }

      // 展开次要关键词列表（若一个次要关键词框或宏展开出多个逗号分隔词，分别作为次要关键词项）
      const secondaryCandidates = [];
      for (const rawSecK of entry.secondaryKeys) {
        const expandedSecList = expandKeyCandidates(rawSecK, macroEnv, host, localWin);
        for (const item of expandedSecList) {
          if (item) secondaryCandidates.push(item);
        }
      }
      if (!secondaryCandidates.length) {
        // 若配置了次要关键词但含有的宏全部展开为空字符串：
        // 对于 and_any / and_all 视为未满足过滤条件；对于 not_any / not_all 视为无冲突放行
        return entry.secondaryLogic === "not_any" || entry.secondaryLogic === "not_all";
      }

      const secHits = secondaryCandidates.map((cand) =>
        testPreparedNeedle(cand, haystack, entry.caseSensitive, entry.matchWholeWords)
      );

      switch (entry.secondaryLogic) {
        case "and_all":
          // 与所有 (AND ALL)：所有次要关键词必须全部命中
          return secHits.every(Boolean);
        case "not_any":
          // 非任意 (NOT ANY)：次要关键词一个都不能命中（命中任意一个即排除）
          return !secHits.some(Boolean);
        case "not_all":
          // 非所有 (NOT ALL)：次要关键词不能全部同时命中
          return !secHits.every(Boolean);
        case "and_any":
        default:
          // 与任意 (AND ANY)：至少命中 1 个次要关键词
          return secHits.some(Boolean);
      }
    }

    function buildScanMessages({
      recentMessages = [],
      statData = null,
      forumMode = "surface",
      targetBoard = "all",
      customDirection = "",
      userPostData = null,
      replyTargetData = null,
    }) {
      const taskParts = [];
      if (targetBoard && targetBoard !== "all") {
        taskParts.push(`当前板块：${targetBoard}`);
      }
      if (customDirection) taskParts.push(`舆论焦点：${customDirection}`);
      if (userPostData) {
        taskParts.push(
          `玩家发帖：${userPostData.board} ${userPostData.title} ${userPostData.content} ${
            userPostData.imageDesc || ""
          }`
        );
      }
      if (replyTargetData) {
        taskParts.push(
          `玩家回帖：${replyTargetData.board} ${replyTargetData.title} ${replyTargetData.userReply} ${
            replyTargetData.htmlContent || ""
          }`
        );
      }
      if (isObj(statData)) {
        const w = isObj(statData.世界) ? statData.世界 : {};
        if (w.地点) {
          taskParts.push(
            typeof w.地点 === "object" ? Object.values(w.地点).join(" ") : String(w.地点)
          );
        }
      }

      const reversedChat = [...recentMessages].reverse();
      return {
        scanMessages: reversedChat,
        taskScanText: taskParts.join("\n"),
      };
    }

    // 多源世界书扫描与组装 checkAndScanWorldbooks(context, config = defaultPlotWorldbookConfig)
    async function checkAndScanWorldbooks(context, config = defaultPlotWorldbookConfig) {
      const {
        host,
        localWin,
        forumMode = "surface",
        targetBoard = "all",
        customDirection = "",
        userPostData = null,
        replyTargetData = null,
        recentMessages = [],
        statData = null,
        macroEnv = {},
      } = context || {};

      const mergedCfg = { ...defaultPlotWorldbookConfig, ...(config || {}) };
      const emptyResult = {
        wiBefore: "",
        wiAfter: "",
        wiAuthorNote: "",
        wiDepthEntries: [],
        combinedText: "",
        worldbookForumRules: "",
        matchedEntries: [],
        scanStats: {
          allDiscoveredBooks: [],
          books: [],
          totalEntries: 0,
          activatedCount: 0,
          constantCount: 0,
          selectiveCount: 0,
          recursiveCount: 0,
          activatedNames: [],
        },
      };

      const { allLorebooks } = await discoverActiveLorebooks(host, localWin);
      emptyResult.scanStats.allDiscoveredBooks = allLorebooks;

      if (!mergedCfg.enabled) return emptyResult;

      // 若 affectedBooks 指定了作用世界书子集，则按 affectedBooks 过滤，否则默认扫描全部绑定世界书
      const targetBooks =
        Array.isArray(mergedCfg.affectedBooks) && mergedCfg.affectedBooks.length > 0
          ? allLorebooks.filter((b) => mergedCfg.affectedBooks.includes(b))
          : allLorebooks;

      const effectiveBooks = targetBooks.length > 0 ? targetBooks : allLorebooks;
      emptyResult.scanStats.books = effectiveBooks;

      const rawEntries = await loadEntriesFromBooks(host, localWin, effectiveBooks);
      if (!rawEntries.length) return emptyResult;

      if (isObj(macroEnv)) {
        macroEnv.enabledWorldInfoEntries = rawEntries.map((e) => ({
          uid: e.rawUid,
          world: e.bookName,
          comment: e.name,
          content: e.content,
          disable: false,
        }));
        const sandbox = ForumMacroEngine.getOrInitSandbox(macroEnv, host, localWin);
        for (const e of rawEntries) {
          ForumMacroEngine.extractSetvarMacrosToSandbox(e.content, sandbox, true);
        }
      }

      const worldbookForumRuleParts = [];
      const candidateEntries = [];

      const enableImageGenMode = Boolean(context?.enableImageGenMode);
      for (const entry of rawEntries) {
        if (isMainChatTechnicalNoise(entry, forumMode)) continue;
        const isImageGenLoreEntry =
          /^(?:画图主体|色色指导)$/.test(entry.name) ||
          /<imageTag>|<可用绘图角色列表>|<画图特色关键词参考/.test(entry.content);
        if (isImageGenLoreEntry) {
          if (!enableImageGenMode) continue;
          const expandedImgRule = ForumMacroEngine.evalMacroTemplate(entry.content, macroEnv, {
            host,
            localWin,
            replaceXmlTags: true,
          })
            .replace(/在生成tag之前需要使用imgthink进行思考\s*/gi, "直接根据画面描述输出英文画图tag（严禁输出<imgthink>思考块）\n")
            .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>\s*/gi, "")
            .trim();
          if (expandedImgRule) {
            worldbookForumRuleParts.push(`<!-- 世界书原生画图规则：${entry.name} -->\n${expandedImgRule}`);
          }
          continue;
        }
        if (/论坛输出公共要求|阿斯塔利亚(?:里版)?论坛/.test(entry.name)) {
          const expandedRule = ForumMacroEngine.evalMacroTemplate(entry.content, macroEnv, {
            host,
            localWin,
            replaceXmlTags: true,
          }).trim();
          if (expandedRule) {
            worldbookForumRuleParts.push(`<!-- 世界书原生规则：${entry.name} -->\n${expandedRule}`);
          }
          continue;
        }
        candidateEntries.push(entry);
      }

      const { scanMessages, taskScanText } = buildScanMessages({
        recentMessages,
        statData,
        forumMode,
        targetBoard,
        customDirection,
        userPostData,
        replyTargetData,
      });

      const activatedMap = new Map();
      let constantCount = 0;
      let selectiveCount = 0;
      let recursiveCount = 0;
      let recursionBuffer = "";

      const defaultScanDepth = Number.isFinite(Number(mergedCfg.scanDepth))
        ? Math.max(1, Number(mergedCfg.scanDepth))
        : 2;
      const maxRecursionSteps = Number.isFinite(Number(mergedCfg.maxRecursionSteps))
        ? Math.max(0, Number(mergedCfg.maxRecursionSteps))
        : 0;
      const maxTotalChars = Number(mergedCfg.maxTotalChars) || 2000000;

      // 第 0 轮：调用 checkWorldInfo 扫描蓝灯常驻 (constant) 与绿灯 (selective: 主要关键词 + 可选过滤器) 触发条目
      for (const entry of candidateEntries) {
        const matched = checkWorldInfo(entry, {
          scanMessages,
          taskScanText,
          recursionBuffer: "",
          defaultScanDepth,
          macroEnv,
          host,
          localWin,
          isRecursionPass: false,
          recursionStep: 0,
          forumMode,
        });
        if (matched) {
          const isConst = entry.strategyType === "constant";
          activatedMap.set(entry.uid, {
            entry,
            reason: isConst ? "constant" : "selective",
            step: 0,
          });
          if (isConst) constantCount++;
          else selectiveCount++;
        }
      }

      const appendOutgoingToRecursionBuffer = (stepIndex) => {
        let added = false;
        for (const { entry, step } of activatedMap.values()) {
          if (step === stepIndex && !entry.preventOutgoing) {
            const expanded = ForumMacroEngine.evalMacroTemplate(entry.content, macroEnv, {
              host,
              localWin,
              replaceXmlTags: true,
            });
            if (expanded) {
              recursionBuffer += "\n" + expanded;
              added = true;
            }
          }
        }
        return added;
      };

      // 多级递归扫描
      for (let step = 1; step <= maxRecursionSteps; step++) {
        const hasNewOutgoing = appendOutgoingToRecursionBuffer(step - 1);
        if (!hasNewOutgoing && !recursionBuffer) break;

        let newlyActivatedInStep = 0;
        for (const entry of candidateEntries) {
          if (activatedMap.has(entry.uid)) continue;
          const matched = checkWorldInfo(entry, {
            scanMessages,
            taskScanText,
            recursionBuffer,
            defaultScanDepth,
            macroEnv,
            host,
            localWin,
            isRecursionPass: true,
            recursionStep: step,
            forumMode,
          });
          if (matched) {
            activatedMap.set(entry.uid, { entry, reason: "recursive", step });
            recursiveCount++;
            newlyActivatedInStep++;
          }
        }
        if (newlyActivatedInStep === 0) break;
      }

      // 按 position / depth / order 排序（对齐酒馆 WorldInfo 顺序）
      const matchedEntries = [...activatedMap.values()].map((v) => v.entry);
      matchedEntries.sort((a, b) => {
        const aCore = /世界主设定|生命层级|社会构成|种族|天穹|势力|角色|地理|阿斯塔利亚/.test(a.name) ? 0 : 1;
        const bCore = /世界主设定|生命层级|社会构成|种族|天穹|势力|角色|地理|阿斯塔利亚/.test(b.name) ? 0 : 1;
        if (aCore !== bCore) return aCore - bCore;
        return (a.order || 0) - (b.order || 0);
      });

      const beforeParts = [];
      const afterParts = [];
      const anParts = [];
      const depthEntries = [];
      const allParts = [];
      const activatedNames = [];
      const seenContentFingerprints = new Set();
      let usedChars = 0;

      for (const entry of matchedEntries) {
        const expandedContent = ForumMacroEngine.evalMacroTemplate(entry.content, macroEnv, {
          host,
          localWin,
          replaceXmlTags: true,
        }).trim();
        if (!expandedContent) continue;

        const fingerprint = expandedContent.slice(0, 160);
        if (seenContentFingerprints.has(fingerprint)) continue;
        seenContentFingerprints.add(fingerprint);

        const entryText = expandedContent;

        if (usedChars + entryText.length > maxTotalChars && usedChars > 0) {
          continue;
        }
        usedChars += entryText.length;
        activatedNames.push(entry.name);

        const formattedBlock = entryText;
        allParts.push(formattedBlock);

        if (entry.positionType === "before_character_definition") {
          beforeParts.push(formattedBlock);
        } else if (
          entry.positionType === "after_character_definition" ||
          entry.positionType === "before_example_messages" ||
          entry.positionType === "after_example_messages"
        ) {
          afterParts.push(formattedBlock);
        } else if (
          entry.positionType === "before_author_note" ||
          entry.positionType === "after_author_note"
        ) {
          anParts.push(formattedBlock);
        } else if (entry.positionType === "at_depth") {
          depthEntries.push({
            name: entry.name,
            depth: entry.depth,
            order: entry.order,
            role: entry.role,
            content: formattedBlock,
          });
        } else {
          afterParts.push(formattedBlock);
        }
      }

      depthEntries.sort((a, b) => b.depth - a.depth || (a.order || 0) - (b.order || 0));

      return {
        wiBefore: beforeParts.join("\n\n"),
        wiAfter: afterParts.join("\n\n"),
        wiAuthorNote: anParts.join("\n\n"),
        wiDepthEntries: depthEntries,
        combinedText: allParts.join("\n\n"),
        worldbookForumRules: worldbookForumRuleParts.join("\n\n"),
        matchedEntries,
        scanStats: {
          allDiscoveredBooks: allLorebooks,
          books: effectiveBooks,
          totalEntries: rawEntries.length,
          activatedCount: activatedNames.length,
          constantCount,
          selectiveCount,
          recursiveCount,
          activatedNames,
        },
      };
    }

    return {
      checkWorldInfo,
      checkAndScanWorldbooks,
      discoverActiveLorebooks,
    };
  })();

  /* ============================================================================
   * 7. 上下文提取与标签清洗器 (boundaryRules / regexRules / cleanChatHistory)
   * ============================================================================ */
  const ForumContextReader = (() => {
    const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
    const str = (v) => (typeof v === "string" || typeof v === "number" ? String(v).trim() : "");

    function getScopes(host, localWin) {
      return [
        ...new Set(
          [localWin, host, localWin?.TavernHelper, host?.TavernHelper].filter(Boolean)
        ),
      ];
    }

    function findMethod(scopes, name) {
      for (const s of scopes) {
        if (typeof s[name] === "function") return s[name].bind(s);
      }
      return null;
    }

    // 区分边界标签规则 (mode !== 'regex') 与正则规则 (mode === 'regex')
    function boundaryRules(rules = []) {
      return (Array.isArray(rules) ? rules : []).filter(
        (rule) => rule && rule.enabled !== false && rule.mode !== "regex"
      );
    }

    function regexRules(rules = []) {
      return (Array.isArray(rules) ? rules : []).filter(
        (rule) => rule && rule.enabled !== false && rule.mode === "regex"
      );
    }

    function escapeRegExp(s) {
      return String(s || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }

    // 清洗聊天历史记录 cleanChatHistory(chatHistory, config)
    function cleanChatHistory(chatHistory = [], config = defaultTaskContextConfig) {
      const extBoundary = boundaryRules(config?.extractRules);
      const extRegex = regexRules(config?.extractRules);
      const excBoundary = boundaryRules(config?.excludeRules);
      const excRegex = regexRules(config?.excludeRules);

      const extractedTags = {};
      let latestTp = "";

      // 预编译所有提取与排除规则正则，避免在每条消息循环内重复构造 RegExp
      const compiledExtBoundary = extBoundary
        .map((r) => {
          const tagName = str(r.name);
          return tagName
            ? {
                tagName,
                lower: tagName.toLowerCase(),
                re: new RegExp(`<${escapeRegExp(tagName)}\\b[^>]*>([\\s\\S]*?)<\\/${escapeRegExp(tagName)}>`, "gi"),
              }
            : null;
        })
        .filter(Boolean);

      const compiledExtRegex = extRegex
        .map((r) => {
          if (!r.pattern) return null;
          try {
            return { name: r.name, re: new RegExp(r.pattern, r.flags || "gi") };
          } catch {
            return null;
          }
        })
        .filter(Boolean);

      const compiledExcBoundary = excBoundary
        .map((r) => {
          const tagName = str(r.name);
          return tagName
            ? new RegExp(`<${escapeRegExp(tagName)}\\b[^>]*>[\\s\\S]*?<\\/${escapeRegExp(tagName)}>`, "gi")
            : null;
        })
        .filter(Boolean);

      const compiledExcRegex = excRegex
        .map((r) => {
          if (!r.pattern) return null;
          try {
            return { re: new RegExp(r.pattern, r.flags || "gi"), replacement: r.replacement ?? "" };
          } catch {
            return null;
          }
        })
        .filter(Boolean);

      const cleanedMessages = [];

      for (const message of chatHistory) {
        const raw = String(message.message ?? message.mes ?? message.text ?? "");
        if (!raw) continue;

        let workingText = raw;
        for (const item of compiledExtBoundary) {
          const matches = [...raw.matchAll(item.re)];
          if (matches.length > 0) {
            const lastCaptured = matches.at(-1)[1].trim();
            extractedTags[item.tagName] = lastCaptured;
            if (item.lower === "tp") {
              latestTp = lastCaptured.replace(/\s+/g, " ").trim();
            } else if (item.lower === "gametxt") {
              workingText = matches.map((m) => m[1]).join("\n\n");
            }
          }
        }

        for (const item of compiledExtRegex) {
          const matches = [...raw.matchAll(item.re)];
          if (matches.length > 0) {
            const captured = matches.at(-1)[1] ?? matches.at(-1)[0];
            if (item.name) extractedTags[item.name] = String(captured).trim();
          }
        }

        for (const tagPattern of compiledExcBoundary) {
          workingText = workingText.replace(tagPattern, "");
        }

        for (const item of compiledExcRegex) {
          workingText = workingText.replace(item.re, item.replacement);
        }

        // 彻底剥离任何残留的 <image>...</image>、<imgthink>...</imgthink> 与 image###...### 生图提示词，防止其因剥离 HTML 外壳后裸露在上下文中
        workingText = workingText
          .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>/gi, "")
          .replace(/<image\b[^>]*>[\s\S]*?<\/image>/gi, "")
          .replace(/image###[\s\S]*?###/gi, "");

        // 剥离剩余内联 HTML 标签并压缩空白
        const cleanText = workingText
          .replace(/<[^>]+>/g, " ")
          .replace(/[ \t]+/g, " ")
          .replace(/\n{3,}/g, "\n\n")
          .trim();

        if (cleanText) {
          const isUser = message.role === "user" || Boolean(message.is_user);
          cleanedMessages.push({
            ...message,
            role: isUser ? "user" : "assistant",
            is_user: isUser,
            text: cleanText,
          });
        }
      }

      return { cleanedMessages, extractedTags, latestTp };
    }

    async function readVariables(host, localWin) {
      const scopes = getScopes(host, localWin);
      let statData = null,
        addonData = null,
        postProcessTags = null,
        chatVarsRaw = {},
        coreName = "命定之灵";

      for (const s of scopes) {
        if (s.Mvu && typeof s.Mvu.getMvuData === "function") {
          try {
            const mvu = await s.Mvu.getMvuData({ type: "message", message_id: -1 });
            if (isObj(mvu?.stat_data)) statData = mvu.stat_data;
            else if (isObj(mvu)) statData = mvu;
            if (statData) break;
          } catch {}
        }
      }

      const getVars = findMethod(scopes, "getVariables");
      if (getVars) {
        try {
          const msgVars = await getVars({ type: "message", message_id: -1 });
          if (isObj(msgVars)) chatVarsRaw = { ...chatVarsRaw, ...msgVars };
          if (!statData && isObj(msgVars?.stat_data)) statData = msgVars.stat_data;
          if (isObj(msgVars?.addon_data)) addonData = msgVars.addon_data;
          if (isObj(msgVars?.post_process_tags)) postProcessTags = msgVars.post_process_tags;
        } catch {}
        try {
          const localVars = await getVars({ type: "local" });
          if (isObj(localVars)) chatVarsRaw = { ...localVars, ...chatVarsRaw };
        } catch {}
        try {
          const chatVars = await getVars({ type: "chat" });
          if (isObj(chatVars)) chatVarsRaw = { ...chatVars, ...chatVarsRaw };
          if (!statData && isObj(chatVars?.stat_data)) statData = chatVars.stat_data;
          if (!addonData && isObj(chatVars?.addon_data)) addonData = chatVars.addon_data;
          if (!postProcessTags && isObj(chatVars?.post_process_tags))
            postProcessTags = chatVars.post_process_tags;
          if (chatVars?.系统核心名) coreName = str(chatVars.系统核心名);
        } catch {}
      }

      const getMsgs = findMethod(scopes, "getChatMessages");
      const getLastIdFn = findMethod(scopes, "getLastMessageId");
      if (!statData && getMsgs && getVars) {
        try {
          let rangeExpr = "0-{{lastMessageId}}";
          if (getLastIdFn) {
            const lid = await getLastIdFn();
            if (typeof lid === "number" && lid > 12) {
              rangeExpr = `${lid - 12}-${lid}`;
            }
          }
          const history = await getMsgs(rangeExpr, {
            role: "assistant",
            include_swipes: false,
          });
          for (const item of [...(history || [])].reverse().slice(0, 10)) {
            try {
              const v = await getVars({ type: "message", message_id: item.message_id });
              if (isObj(v?.stat_data)) {
                statData = v.stat_data;
                if (!addonData && isObj(v?.addon_data)) addonData = v.addon_data;
                if (!postProcessTags && isObj(v?.post_process_tags))
                  postProcessTags = v.post_process_tags;
                break;
              }
            } catch {}
          }
        } catch {}
      }

      if (!statData) {
        const stCtx = ForumMacroEngine.getStContext(host, localWin);
        if (stCtx) {
          try {
            const chatArr = Array.isArray(stCtx.chat) ? stCtx.chat : [];
            for (let i = chatArr.length - 1, minIdx = Math.max(0, chatArr.length - 15); i >= minIdx; i--) {
              const msg = chatArr[i];
              if (!msg) continue;
              const rawVars = msg.variables;
              const swipeIdx = typeof msg.swipe_id === "number" ? msg.swipe_id : 0;
              const vObj = Array.isArray(rawVars)
                ? rawVars[swipeIdx] || rawVars[0] || rawVars.find((x) => isObj(x?.stat_data))
                : rawVars;
              if (isObj(vObj?.stat_data)) {
                statData = vObj.stat_data;
                if (!addonData && isObj(vObj?.addon_data)) addonData = vObj.addon_data;
                if (!postProcessTags && isObj(vObj?.post_process_tags))
                  postProcessTags = vObj.post_process_tags;
                chatVarsRaw = { ...vObj, ...chatVarsRaw };
                break;
              }
            }
          } catch {}
          if (!statData && isObj(stCtx.chatMetadata?.variables?.stat_data)) {
            const metaVars = stCtx.chatMetadata.variables;
            statData = metaVars.stat_data;
            if (!addonData && isObj(metaVars.addon_data)) addonData = metaVars.addon_data;
            if (!postProcessTags && isObj(metaVars.post_process_tags))
              postProcessTags = metaVars.post_process_tags;
            chatVarsRaw = { ...metaVars, ...chatVarsRaw };
          }
        }
      }

      // 彻底剥离论坛自身变量 (forum_data / stat_data.事件.命定论坛 / stat_data.命定论坛)，论坛推演与世界书扫描不提取论坛的变量
      if (isObj(statData)) {
        try {
          statData = JSON.parse(JSON.stringify(statData));
          delete statData.forum_data;
          delete statData.命定论坛;
          if (isObj(statData.事件)) {
            delete statData.事件.forum_data;
            delete statData.事件.命定论坛;
          }
        } catch {}
      }
      if (isObj(addonData)) {
        try {
          addonData = JSON.parse(JSON.stringify(addonData));
          delete addonData.forum_data;
          delete addonData.命定论坛;
        } catch {}
      }
      if (isObj(chatVarsRaw)) {
        delete chatVarsRaw.forum_data;
        delete chatVarsRaw.命定论坛;
        if (isObj(chatVarsRaw.stat_data)) {
          try {
            chatVarsRaw.stat_data = JSON.parse(JSON.stringify(chatVarsRaw.stat_data));
            delete chatVarsRaw.stat_data.forum_data;
            delete chatVarsRaw.stat_data.命定论坛;
            if (isObj(chatVarsRaw.stat_data.事件)) {
              delete chatVarsRaw.stat_data.事件.forum_data;
              delete chatVarsRaw.stat_data.事件.命定论坛;
            }
          } catch {}
        }
      }
      return { statData, addonData, postProcessTags, chatVarsRaw, coreName };
    }

    async function readCharacterAndPersona(host, localWin) {
      const scopes = getScopes(host, localWin);
      const stCtx = ForumMacroEngine.getStContext(host, localWin);
      let charDescription = "";
      let charScenario = "";
      let persona = "";
      try {
        const charObj = stCtx?.characters?.[stCtx?.characterId];
        charDescription = str(charObj?.description || charObj?.data?.description);
        charScenario = str(charObj?.scenario || charObj?.data?.scenario);
        persona = str(stCtx?.powerUserSettings?.persona_description);
      } catch {}

      if (!persona) {
        for (const s of scopes) {
          try {
            const pu = s.power_user || s.SillyTavern?.getContext?.()?.powerUserSettings;
            if (pu) {
              if (str(pu.persona_description)) {
                persona = str(pu.persona_description);
                break;
              }
              const activeAvatar =
                str(s.user_avatar) ||
                str(stCtx?.userAvatar) ||
                str(pu.default_persona);
              if (activeAvatar && isObj(pu.personas) && str(pu.personas[activeAvatar])) {
                persona = str(pu.personas[activeAvatar]);
                break;
              }
            }
            if (typeof s.getPersonaDescription === "function") {
              const pDesc = str(await s.getPersonaDescription());
              if (pDesc) {
                persona = pDesc;
                break;
              }
            }
            const subFn =
              s.SillyTavern?.getContext?.()?.substituteParams ||
              s.substituteParams ||
              s.substitudeMacros;
            if (typeof subFn === "function") {
              const subbed = str(subFn("{{persona}}"));
              if (subbed && !/^\{\{\s*persona\s*\}\}$/i.test(subbed)) {
                persona = subbed;
                break;
              }
            }
            const domPersonaEl = s.document?.getElementById?.("persona_description");
            if (domPersonaEl && str(domPersonaEl.value)) {
              persona = str(domPersonaEl.value);
              break;
            }
          } catch {}
        }
      }

      return { charDescription, charScenario, persona };
    }

    async function readRecentChat(
      host,
      localWin,
      turnCount = 2,
      contextConfig = defaultTaskContextConfig
    ) {
      const scopes = getScopes(host, localWin);
      const getMsgs = findMethod(scopes, "getChatMessages");
      const getLastIdFn = findMethod(scopes, "getLastMessageId");
      let rawSlice = [];
      const sliceCount = Math.max(2, turnCount * 2);

      if (getMsgs) {
        try {
          let rangeExpr = "0-{{lastMessageId}}";
          if (getLastIdFn) {
            const lid = await getLastIdFn();
            if (typeof lid === "number" && lid >= sliceCount) {
              rangeExpr = `${Math.max(0, lid - sliceCount - 2)}-${lid}`;
            }
          }
          const all = await getMsgs(rangeExpr, { include_swipes: false });
          rawSlice = (all || []).slice(-sliceCount);
        } catch (e) {
          console.warn("[命定论坛] 读取聊天记录异常:", e);
        }
      }

      if (!rawSlice.length) {
        try {
          const chat = host.SillyTavern?.getContext?.()?.chat || [];
          rawSlice = chat.slice(-Math.max(2, turnCount * 2));
        } catch {}
      }

      const { cleanedMessages, extractedTags, latestTp } = cleanChatHistory(
        rawSlice,
        contextConfig
      );

      let lastMessage = "";
      let lastUserMessage = "";
      let lastCharMessage = "";
      const snippets = [];
      const plainMessagesForScan = [];

      for (const msg of cleanedMessages) {
        const roleLabel = msg.is_user ? "【玩家行动】" : "【剧情正文】";
        snippets.push(`${roleLabel} ${msg.text.slice(0, 1200)}`);
        plainMessagesForScan.push(msg.text);
        lastMessage = msg.text;
        if (msg.is_user) lastUserMessage = msg.text;
        else lastCharMessage = msg.text;
      }

      return {
        latestTp,
        extractedTags,
        cleanedMessages,
        recentText: snippets.join("\n\n"),
        plainMessagesForScan,
        lastMessage,
        lastUserMessage,
        lastCharMessage,
      };
    }

    const HERO_ALLOWED_KEYS = ["种族", "身份", "职业", "生命层级", "等级", "装备"];
    const REL_CHAR_ALLOWED_KEYS = [
      "种族",
      "身份",
      "职业",
      "生命层级",
      "性格",
      "喜爱",
      "外貌",
      "着装",
      "等级",
      "好感度",
      "心里话",
      "背景故事",
    ];

    function pickStatHeroAndRelations(statData) {
      const heroPicked = {};
      const relsPicked = {};
      if (!isObj(statData)) return { heroPicked, relsPicked };

      const hero = isObj(statData.主角) ? statData.主角 : {};
      for (const k of HERO_ALLOWED_KEYS) {
        if (hero[k] !== undefined) {
          heroPicked[k] = hero[k];
        }
      }

      const rels = isObj(statData.关系列表) ? statData.关系列表 : {};
      for (const [cName, cData] of Object.entries(rels)) {
        if (!isObj(cData) || cData._隐藏 === true) continue;
        const item = {};
        for (const k of REL_CHAR_ALLOWED_KEYS) {
          if (cData[k] !== undefined) {
            item[k] = cData[k];
          }
        }
        relsPicked[cName] = item;
      }

      return { heroPicked, relsPicked };
    }

    function formatStatSummary(statData, latestTp, userName, allowUserPosts = false, persona = "") {
      const cleanPersona = str(persona);
      if (!isObj(statData)) {
        const fallbackLines = [];
        if (latestTp) fallbackLines.push(`当前时间地点天气：${latestTp}`);
        if (cleanPersona) {
          fallbackLines.push(`<当前用户人设>
${cleanPersona}
</当前用户人设>`);
        }
        return fallbackLines.length ? fallbackLines.join("\n\n") : "（未读取到 stat_data 变量树）";
      }
      const lines = [];
      const world = isObj(statData.世界) ? statData.世界 : {};
      const timeStr = str(world.时间) || latestTp || "未知时间";
      const locStr = isObj(world.地点)
        ? Object.values(world.地点).filter(Boolean).join("-")
        : str(world.地点) || "未知地点";
      lines.push(`- 当前世界时间：${timeStr}`);
      lines.push(`- ${userName}当前所在位置（同城交流锚点）：${locStr}`);
      if (latestTp) lines.push(`- 最新场景标识(<tp>)：${latestTp}`);

      const hero = isObj(statData.主角) ? statData.主角 : {};
      if (Object.keys(hero).length) {
        const hName = str(hero.姓名 || hero.名称 || userName);
        const hRace = str(hero.种族);
        const hTier = str(hero.生命层级);
        const hLvl = hero.等级 != null ? `Lv.${hero.等级}` : "";
        const hId = Array.isArray(hero.身份) ? hero.身份.join("、") : str(hero.身份);
        if (allowUserPosts) {
          lines.push(
            `- 当前主角(${userName})信息：${hName}（种族：${hRace}｜生命层级：${hTier} ${hLvl}｜身份：${hId}）【已开启生成主角帖子：请结合 ${hName} 的最新剧情经历、人设口吻与当前处境，在本次论坛中生成由 ${hName} 本人发布的帖子与楼层回复，以及围绕 ${hName} 展开讨论的帖子（即使 ${hName} 低于第三层级，系统核心也已赋予其特权准入）！】`
          );
        } else {
          lines.push(
            `- 当前旁观主角(${userName})信息：${hName}（种族：${hRace}｜生命层级：${hTier} ${hLvl}｜身份：${hId}）【注意：主角仅在后台浏览论坛，除玩家主动发帖外，严禁将 ${hName} 作为发帖人或回复层主！】`
          );
        }
      }

      const newsData = statData.新闻 ?? world.新闻;
      if (isObj(newsData) || Array.isArray(newsData)) {
        try {
          lines.push(`- 当前世界新闻栏 (stat_data.新闻)：\n${JSON.stringify(newsData, null, 2)}`);
        } catch {}
      }

      // 已剥离 forum_data / stat_data.事件.命定论坛：论坛自身推演不提取论坛变量

      const rels = isObj(statData.关系列表) ? statData.关系列表 : {};
      const presentChars = [];
      const absentChars = [];
      for (const [cName, cData] of Object.entries(rels)) {
        if (!isObj(cData) || cData._隐藏 === true) continue;
        const cTier = str(cData.生命层级);
        const cLvl = cData.等级 != null ? `Lv.${cData.等级}` : "";
        const cId = Array.isArray(cData.身份) ? cData.身份.join("/") : str(cData.身份);
        const info = `${cName}（${cId || "未知身份"}｜${cTier} ${cLvl}｜好感:${cData.好感度 ?? "?"}）`;
        if (cData.在场 === true || cData.在场 === "true") {
          presentChars.push(info);
        } else {
          absentChars.push(info);
        }
      }
      if (presentChars.length) {
        lines.push(
          `- 【当前在场角色（正在与${userName}当面互动，严禁在同一时间莫名发长帖或刷屏）】：${presentChars.join("；")}`
        );
      }
      if (absentChars.length) {
        lines.push(
          `- 【不在场已知角色（可挑选其中第三层级以上角色作为论坛发帖人或回复嘉宾）】：${absentChars.join("；")}`
        );
      }

      if (cleanPersona) {
        lines.push(`\n<当前用户人设>\n${cleanPersona}\n</当前用户人设>`);
      }

      const { heroPicked, relsPicked } = pickStatHeroAndRelations(statData);
      if (Object.keys(heroPicked).length) {
        try {
          lines.push(
            `\n<stat_data.主角>\n${JSON.stringify(heroPicked, null, 2)}\n</stat_data.主角>`
          );
        } catch {}
      }

      if (Object.keys(relsPicked).length) {
        try {
          lines.push(
            `\n<stat_data.关系列表>\n${JSON.stringify(relsPicked, null, 2)}\n</stat_data.关系列表>`
          );
        } catch {}
      }

      return lines.join("\n");
    }

    function formatWorldPaperSummary(addonData, postProcessTags) {
      const parts = [];
      // 已剥离 forum_data：论坛自身不提取论坛变量
      if (isObj(addonData)) {
        try {
          parts.push(
            `【世界时局与社交圈 (addon_data)】：\n${JSON.stringify(addonData, null, 2).slice(0, 2600)}`
          );
        } catch {}
      }
      if (isObj(postProcessTags)) {
        try {
          parts.push(
            `【角色后台动态与世界摘要 (post_process_tags)】：\n${JSON.stringify(postProcessTags, null, 2).slice(0, 2200)}`
          );
        } catch {}
      }
      return parts.join("\n\n");
    }

    async function collectFullContext(
      host,
      localWin,
      settings,
      {
        actionType = "browse",
        userPostData = null,
        replyTargetData = null,
        customDirection = "",
      } = {}
    ) {
      const contextCfg = settings.taskContextConfig || defaultTaskContextConfig;
      const [
        { statData, addonData, postProcessTags, chatVarsRaw, coreName },
        {
          latestTp,
          extractedTags,
          cleanedMessages,
          recentText,
          plainMessagesForScan,
          lastMessage,
          lastUserMessage,
          lastCharMessage,
        },
