          if (!ForumMacroEngine.hasMacros(armorRaw)) {
            return armorRaw;
          }
          rawSlotText = armorRaw;
          break;
        }

        default:
          rawSlotText = String(slot.customContent || "");
      }

      if (!rawSlotText) return "";

      return ForumMacroEngine.evalMacroTemplate(rawSlotText, promptMacroEnv, {
        host,
        localWin,
        // 严禁把协议内的 <user> 替换为角色名，严格保持《命定·黄昏 Prime-1.11》中 <user> 与 Participant 的解耦定义
        replaceXmlTags: false,
      })
        .replace(/\n{3,}/g, "\n\n")
        .trim();
    }

    // 组装分槽位消息列表 promptAutoSegments(slots, context)
    function promptAutoSegments(slots, assemblyCtx) {
      const messages = [];
      const activeSlots = Array.isArray(slots) && slots.length ? slots : defaultPromptSlotsConfig;
      const chatHistorySlotEnabled = activeSlots.some(
        (s) => s && s.id === "chat_history" && s.enabled !== false
      );
      const mergedCtx = { ...assemblyCtx, chatHistorySlotEnabled };

      for (const slot of activeSlots) {
        if (!slot || slot.enabled === false) continue;
        const rawRole = slot.role || (slot.id === "system" ? "system" : "user");
        const role = slot.id === "assistant" && rawRole === "system" ? "user" : normalizeSlotRole(rawRole);
        const content = resolveSlotContent(slot, mergedCtx);
        if (content) {
          messages.push({
            role,
            content,
            slotId: slot.id,
            slotLabel: slot.label || slot.id,
          });
        }
      }
      return messages;
    }

    // 1:1 复刻《命定·黄昏 Prime-1.11》processDestinedMessages 的三段式消息结构：
    // [head(system), body(user: 合并 char_defs + world_info + chat_history + task_instruction), tail(user: 独立尾部消息 🔌 Gemini非预填充)]
    function mergeAdjacentRoleMessages(segmentMessages) {
      const merged = [];
      for (const msg of segmentMessages) {
        if (!msg || !msg.content) continue;
        // 保持尾部 assistant 槽位（🔌 Gemini非预填充）作为独立的第 3 条消息，与 processDestinedMessages 的 [...outerMessages(head), {role:'user', content:body}, ...outerMessages(tail)] 完全一致
        if (msg.slotId === "assistant") {
          merged.push({ role: msg.role, content: msg.content });
          continue;
        }
        const prev = merged.at(-1);
        if (prev && prev.role === msg.role && !prev._isTail) {
          prev.content = `${prev.content}\n\n${msg.content}`;
        } else {
          merged.push({ role: msg.role, content: msg.content });
        }
      }
      return merged;
    }

    function buildForumPrompts({
      host,
      localWin,
      mode,
      targetBoard,
      actionType,
      userPostData,
      replyTargetData,
      customDirection,
      context,
      settings = {},
      continueMeta = null,
    }) {
      const isDark = mode === "dark";
      const forumTitle = isDark ? "阿斯塔利亚里版论坛" : "阿斯塔利亚论坛（表版）";
      const rootClass = isDark ? "ast-dark" : "ast-net";
      const modeSpecificRules = isDark ? DARK_FORUM_RULES : SURFACE_FORUM_RULES;
      const scanRes = context.loreScanResult || {};

      const allowUserPosts = Boolean(settings.allowUserPosts);
      const taskInstruction = buildTaskInstructionText({
        mode,
        targetBoard,
        actionType,
        userPostData,
        replyTargetData,
        customDirection,
        allowUserPosts,
        enableImageGenMode: Boolean(settings.enableImageGenMode),
        continueMeta,
      });

      const isUserInteractiveAction = actionType === "new_post" || actionType === "reply_post";
      const forumUserPostRule =
        allowUserPosts || isUserInteractiveAction
          ? `- 论坛发帖与互动（已开启【{{user}}互动/发帖特权】模式）: 本次任务**允许并要求包含主角「{{user}}」本人发布的帖子或多次盖楼回复**（系统核心已为{{user}}开放无视层级限制的论坛发帖与回帖特权），其他坛友与知名角色需针对「{{user}}」的发言展开真实、鲜活的互动回应`
          : `- 论坛发帖人: **除非本次任务明确为{{user}}主动发帖或回帖，否则任何帖子的发帖人及回复层主绝不能是{{user}}本人！** 必须采用阿斯塔利亚世界内其他第三层级以上人物的第三人视角。无论是知名角色还是普通高阶施法者/骑士都拥有各自的性格、口吻\n  - 除「同城交流」外绝对不能出现关于{{user}}的帖子（除非{{user}}主动发帖或定向指令要求）；「同城交流」中最多 1 篇帖子与{{user}}及其身边人直接/间接相关`;

      const configuredSlotsForCheck =
        Array.isArray(settings.promptSlots) && settings.promptSlots.length
          ? settings.promptSlots
          : defaultPromptSlotsConfig;
      const armorSlotEnabled = configuredSlotsForCheck.some(
        (s) => s && s.id === "assistant" && s.enabled !== false
      );
      const isToolOnceMode = settings.tailOutputMode === "tool_once";
      const userInputEndInjectRaw = String(
        isToolOnceMode
          ? settings.toolOutputEndInject !== undefined
            ? settings.toolOutputEndInject
            : DEFAULT_TOOL_ONCE_PROMPT
          : settings.userInputEndInject !== undefined
          ? settings.userInputEndInject
          : DEFAULT_ARMOR_PIERCING_PROMPT
      ).trim();
      const userInputEndInjectBlock =
        !armorSlotEnabled && userInputEndInjectRaw
          ? `\n${userInputEndInjectRaw}`
          : "";

      const depthBlocksText =
        Array.isArray(scanRes.wiDepthEntries) && scanRes.wiDepthEntries.length
          ? scanRes.wiDepthEntries.map((d) => d.content).join("\n\n")
          : "";

      const promptMacroEnv = {
        ...(context.macroEnv || {}),
        tasks: {
          当前论坛任务: taskInstruction,
          刷帖任务: taskInstruction,
          default: taskInstruction,
        },
        extractedTags: {
          ...(context.extractedTags || {}),
          tp: context.latestTp || "",
        },
        customMacros: {
          ...(context.macroEnv?.customMacros || {}),
          角色启用列表:
            context.macroEnv?.customMacros?.角色启用列表 ||
            ForumChatu8Bridge.generateCharacterListText(host, localWin),
          通用角色启用列表:
            context.macroEnv?.customMacros?.通用角色启用列表 ||
            ForumChatu8Bridge.generateCommonCharacterListText(host, localWin),
          通用服装启用列表:
            context.macroEnv?.customMacros?.通用服装启用列表 ||
            ForumChatu8Bridge.generateOutfitEnableListText(host, localWin),
          forum_title: forumTitle,
          forum_root_class: rootClass,
          forum_user_post_rule: forumUserPostRule,
          forum_common_rules: FORUM_COMMON_RULES,
          forum_mode_rules: modeSpecificRules,
          forum_worldbook_rules: scanRes.worldbookForumRules || "",
          forum_html_spec: HTML_OUTPUT_SPEC,
          wiBefore: scanRes.wiBefore || "",
          worldInfoBefore: scanRes.wiBefore || "",
          wiAfter: scanRes.wiAfter || "",
          worldInfoAfter: scanRes.wiAfter || "",
          wiAuthorNote: scanRes.wiAuthorNote || "",
          wiDepth: depthBlocksText,
          forum_world_info: context.loreText || "",
          forum_stat_summary: context.statSummary || "",
          forum_world_paper: context.worldPaperSummary || "",
          forum_recent_chat:
            context.recentText ||
            "（暂无前文剧情记录，请根据世界观设定生成开局期的命定论坛内容）",
          forum_task_instruction: taskInstruction,
          user_input_end_inject: userInputEndInjectBlock,
        },
      };

      const configuredSlots =
        Array.isArray(settings.promptSlots) && settings.promptSlots.length
          ? settings.promptSlots
          : defaultPromptSlotsConfig;

      const segmentMessages = promptAutoSegments(configuredSlots, {
        host,
        localWin,
        mode,
        actionType,
        userPostData,
        replyTargetData,
        context,
        enableImageGenMode: Boolean(settings.enableImageGenMode),
        enableHeaderGibberish: Boolean(settings.enableHeaderGibberish),
        includeNsfwGuideInSurface: settings.includeNsfwGuideInSurface !== false,
        customSystemPrompt: settings.customSystemPrompt,
        tailOutputMode: settings.tailOutputMode || "normal",
        userInputEndInject: settings.userInputEndInject,
        toolOutputEndInject: settings.toolOutputEndInject,
        finalInjectTemplate: settings.finalInjectTemplate || DEFAULT_FINAL_INJECT_TEMPLATE,
        promptMacroEnv,
        overrides: settings.promptAutoSegmentInsertedOverrides || {},
      });

      const orderedPrompts = mergeAdjacentRoleMessages(segmentMessages);

      const firstNonSystemIdx = orderedPrompts.findIndex((m) => m.role !== "system");
      const leadingSystemParts =
        firstNonSystemIdx === -1
          ? orderedPrompts.map((m) => m.content)
          : orderedPrompts.slice(0, firstNonSystemIdx).map((m) => m.content);
      const restParts =
        firstNonSystemIdx === -1
          ? []
          : orderedPrompts.slice(firstNonSystemIdx).map((m) => m.content);

      const systemPrompt = leadingSystemParts.join("\n\n").trim();
      const userPrompt = restParts.join("\n\n").trim();

      return {
        systemPrompt,
        userPrompt,
        orderedPrompts,
        segmentMessages,
      };
    }

    return {
      promptAutoSlots,
      promptAutoSegments,
      resolveSlotContent,
      buildForumPrompts,
    };
  })();

  /* ============================================================================
   * 8.5 命定工具一次调用打包与解包引擎 (ForumToolOutputPacker)
   *     严格复刻《命定之诗 Prime-1.18》「消息后处理 + 🔌 Gemini工具一次调用」：
   *     1. 将除头部与尾部外的全部上下文合并为单条 user 消息 (body)，完整保留 <role_core> 破限身份与 VOID/Recorder 对话结构（防止丢失破限导致模型道歉拒答）
   *     2. 将闭合的 <Participant_input>...</Participant_input> 块从正文中提取并塞入伪造工具 submit_recorder_output 的 description 中
   *     3. 通过 submit_recorder_output(content) 单次函数调用输出完整 XML，并在前端支持流式/非流式实时解包
   * ============================================================================ */
  const ForumToolOutputPacker = (() => {
    const TOOL_NAME = "submit_recorder_output";
    const CONTENT_PARAM_DESC =
      "The complete Recorder document, beginning with <recorder_output> and <recorder_thinking> and closing with </recorder_output>.";

    function stripToolMarkers(text) {
      return String(text || "")
        .replace(/<\|命定_工具输出\|>\s*/g, "")
        .trim();
    }

    function isToolOutputActive(settings, rawMessagesList = []) {
      if (settings?.tailOutputMode === "tool_once") return true;
      return (Array.isArray(rawMessagesList) ? rawMessagesList : []).some((m) =>
        String(m?.content || "").includes(TOOL_OUTPUT_MARKER)
      );
    }

    function packContextIntoFakeTool({
      rawMessagesList = [],
      systemPrompt = "",
      userPrompt = "",
      settings = {},
    }) {
      const baseList =
        Array.isArray(rawMessagesList) && rawMessagesList.length >= 2
          ? rawMessagesList
          : [
              { role: "system", content: systemPrompt },
              { role: "user", content: userPrompt },
            ];

      let seenNonSys = false;
      const normalized = baseList
        .map((m) => {
          const rawRole = m?.role || "user";
          if (rawRole !== "system") seenNonSys = true;
          return {
            ...m,
            role: seenNonSys && rawRole === "system" ? "user" : rawRole,
            content: String(m?.content || ""),
          };
        })
        .filter((m) => m.content.trim().length > 0);

      const firstNonSysIdx = normalized.findIndex((m) => m.role !== "system");
      const headMessages =
        firstNonSysIdx > 0
          ? normalized.slice(0, firstNonSysIdx).map((m) => ({
              role: "system",
              content: stripToolMarkers(m.content),
            }))
          : systemPrompt
          ? [{ role: "system", content: stripToolMarkers(systemPrompt) }]
          : [];

      const nonSysMessages =
        firstNonSysIdx >= 0 ? normalized.slice(firstNonSysIdx) : normalized;

      let bodyMessages = [];
      let tailContent = "";

      if (nonSysMessages.length >= 2) {
        bodyMessages = nonSysMessages.slice(0, -1);
        tailContent = stripToolMarkers(nonSysMessages.at(-1).content);
      } else if (nonSysMessages.length === 1) {
        const onlyContent = nonSysMessages[0].content;
        const markerIdx = onlyContent.lastIndexOf(TOOL_OUTPUT_MARKER);
        if (markerIdx >= 0) {
          bodyMessages = [{ role: "user", content: onlyContent.slice(0, markerIdx).trim() }];
          tailContent = stripToolMarkers(onlyContent.slice(markerIdx));
        } else {
          bodyMessages = [{ role: "user", content: stripToolMarkers(onlyContent) }];
          tailContent = stripToolMarkers(settings?.toolOutputEndInject || DEFAULT_TOOL_ONCE_PROMPT);
        }
      } else {
        tailContent = stripToolMarkers(settings?.toolOutputEndInject || DEFAULT_TOOL_ONCE_PROMPT);
      }

      if (!tailContent) {
        tailContent = stripToolMarkers(DEFAULT_TOOL_ONCE_PROMPT);
      }

      const fullBodyText = bodyMessages
        .map((m) => stripToolMarkers(m.content))
        .filter(Boolean)
        .join("\n\n");

      const participantRegex =
        /(?:Participant\s*:\s*)?(<Participant_input\b[^>]*>[\s\S]*?<\/Participant_input>)/i;
      const match = fullBodyText.match(participantRegex);
      const closedParticipantBlock = match
        ? match[1].trim()
        : `<Participant_input>\n${fullBodyText.slice(-1500)}\n</Participant_input>`;

      const bodyWithoutParticipant = match
        ? fullBodyText
            .replace(participantRegex, "")
            .replace(/\n{3,}/g, "\n\n")
            .trim()
        : fullBodyText;

      const toolDescription = `Deliver the complete Recorder document for this turn. The closed <Participant_input> block below holds this turn's input; read it as the Participant input of Step 1 and render it from Step 1's entry point.\n\n${closedParticipantBlock}`;

      const packedMessages = [
        ...headMessages,
        ...(bodyWithoutParticipant ? [{ role: "user", content: bodyWithoutParticipant }] : []),
        { role: "user", content: tailContent },
      ];

      const openAiTools = [
        {
          type: "function",
          function: {
            name: TOOL_NAME,
            description: toolDescription,
            parameters: {
              type: "object",
              properties: {
                content: {
                  type: "string",
                  description: CONTENT_PARAM_DESC,
                },
              },
              required: ["content"],
            },
          },
        },
      ];
      const openAiToolChoice = {
        type: "function",
        function: { name: TOOL_NAME },
      };

      const geminiTools = [
        {
          functionDeclarations: [
            {
              name: TOOL_NAME,
              description: toolDescription,
              parameters: {
                type: "OBJECT",
                properties: {
                  content: {
                    type: "STRING",
                    description: CONTENT_PARAM_DESC,
                  },
                },
                required: ["content"],
              },
            },
          ],
        },
      ];
      const geminiToolConfig = {
        functionCallingConfig: {
          mode: "ANY",
          allowedFunctionNames: [TOOL_NAME],
        },
      };

      const claudeTools = [
        {
          name: TOOL_NAME,
          description: toolDescription,
          input_schema: {
            type: "object",
            properties: {
              content: {
                type: "string",
                description: CONTENT_PARAM_DESC,
              },
            },
            required: ["content"],
          },
        },
      ];
      const claudeToolChoice = {
        type: "tool",
        name: TOOL_NAME,
      };

      return {
        toolName: TOOL_NAME,
        toolDescription,
        packedMessages,
        openAiTools,
        openAiToolChoice,
        geminiTools,
        geminiToolConfig,
        claudeTools,
        claudeToolChoice,
      };
    }

    function extractContentFromToolArgs(rawArgs) {
      if (!rawArgs) return "";
      if (typeof rawArgs === "object") {
        const direct = rawArgs.content ?? rawArgs.text ?? rawArgs.output ?? rawArgs.recorder_output ?? rawArgs.document;
        if (typeof direct === "string") return direct;
        if (rawArgs.args && typeof rawArgs.args === "object") {
          return extractContentFromToolArgs(rawArgs.args);
        }
        if (rawArgs.arguments) {
          return extractContentFromToolArgs(rawArgs.arguments);
        }
        const firstStrVal = Object.values(rawArgs).find(
          (v) => typeof v === "string" && /<(?:recorder_output|recorder_thinking|recorder_body|gametxt|div|article)\b/i.test(v)
        );
        if (firstStrVal) return firstStrVal;
        return "";
      }
      const str = String(rawArgs).trim();
      if (!str || str === "[object Object]") return "";

      try {
        const parsed = JSON.parse(str);
        if (parsed && typeof parsed === "object") {
          const val = parsed.content ?? parsed.text ?? parsed.output ?? parsed.recorder_output ?? parsed.document;
          if (typeof val === "string") return val;
          const anyXmlVal = Object.values(parsed).find(
            (v) => typeof v === "string" && /<(?:recorder_output|recorder_thinking|recorder_body|gametxt|div|article)\b/i.test(v)
          );
          if (anyXmlVal) return anyXmlVal;
        }
        if (typeof parsed === "string") return parsed;
      } catch {}

      const keyMatch =
        str.match(/"(?:content|text|output|recorder_output|document|xml|html|body|response)"\s*:\s*"/) ||
        str.match(/^\s*\{\s*"[^"]+"\s*:\s*"/);
      if (!keyMatch) {
        if (
          str.startsWith("<recorder_output") ||
          str.startsWith("<recorder_thinking") ||
          str.includes("<div class=\"ast-") ||
          str.includes("<article class=\"ast-post\"")
        ) {
          return str;
        }
        return "";
      }

      let out = "";
      let i = keyMatch.index + keyMatch[0].length;
      const len = str.length;

      while (i < len) {
        const ch = str[i];
        if (ch === '"') break;
        if (ch === "\\") {
          if (i + 1 >= len) break;
          const next = str[i + 1];
          switch (next) {
            case "n": out += "\n"; i += 2; break;
            case "r": out += "\r"; i += 2; break;
            case "t": out += "\t"; i += 2; break;
            case '"': out += '"'; i += 2; break;
            case "\\": out += "\\"; i += 2; break;
            case "/": out += "/"; i += 2; break;
            case "b": out += "\b"; i += 2; break;
            case "f": out += "\f"; i += 2; break;
            case "u": {
              if (i + 6 <= len) {
                const hex = str.slice(i + 2, i + 6);
                if (/^[0-9a-fA-F]{4}$/.test(hex)) {
                  out += String.fromCharCode(parseInt(hex, 16));
                  i += 6;
                  break;
                }
              } else {
                return out;
              }
              out += next;
              i += 2;
              break;
            }
            default:
              out += next;
              i += 2;
              break;
          }
        } else {
          out += ch;
          i += 1;
        }
      }
      return out;
    }

    function extractNonStreamToolResponse(data, source = "openai") {
      if (!data || typeof data !== "object") return "";

      if (source === "gemini" || Array.isArray(data.candidates)) {
        const parts = data?.candidates?.[0]?.content?.parts || [];
        let funcText = "";
        let normalText = "";
        for (const p of parts) {
          if (p?.functionCall) {
            const extracted = extractContentFromToolArgs(p.functionCall.args);
            if (extracted) funcText += extracted;
          } else if (!p?.thought && p?.text) {
            normalText += p.text;
          }
        }
        return funcText || normalText;
      }

      if (source === "claude" || Array.isArray(data.content)) {
        const blocks = Array.isArray(data.content) ? data.content : [];
        let funcText = "";
        let normalText = "";
        for (const b of blocks) {
          if (b?.type === "tool_use") {
            const extracted = extractContentFromToolArgs(b.input);
            if (extracted) funcText += extracted;
          } else if (b?.type !== "thinking" && b?.text) {
            normalText += b.text;
          }
        }
        return funcText || normalText;
      }

      const msg = data?.choices?.[0]?.message;
      if (!msg) return "";
      const toolCalls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
      for (const tc of toolCalls) {
        const args = tc?.function?.arguments ?? tc?.arguments;
        const extracted = extractContentFromToolArgs(args);
        if (extracted) return extracted;
      }
      if (msg.function_call?.arguments) {
        const extracted = extractContentFromToolArgs(msg.function_call.arguments);
        if (extracted) return extracted;
      }
      return String(msg.content || "");
    }

    return {
      TOOL_NAME,
      stripToolMarkers,
      isToolOutputActive,
      packContextIntoFakeTool,
      extractContentFromToolArgs,
      extractNonStreamToolResponse,
    };
  })();

  /* ============================================================================
   * 9. 独立 API 与酒馆主接口客户端（支持 OpenAI / Gemini / Claude / TavernHelper）
   * ============================================================================ */
  const ForumApiClient = (() => {
    let currentAbortController = null;

    // 针对常见 API / 反代报错给出具体可读诊断信息
    function diagnoseApiError(rawInput, httpStatus = 0) {
      const rawStr = String(rawInput?.message ?? rawInput ?? "").trim();
      if (!rawStr) return "未知网络或接口错误，请重试";

      // 1. 精准匹配 131072 上下文超限（反代随机路由/降级到了 128k 节点）
      if (
        /The input token count exceeds the maximum number of tokens allowed\s*131072/i.test(rawStr) ||
        (/GeminiApiErrorDetails/i.test(rawStr) && /131072/.test(rawStr))
      ) {
        return '被路由请重试（当前请求被反代路由至 131072/128k 限制节点：[,[3,"The input token count exceeds the maximum number of tokens allowed 131072.",[["type.googleapis.com/google.internal.alkali.applications.makersuite.v1.GeminiApiErrorDetails"]]]]）';
      }

      // 2. 其他最大 Token 限制报错
      const tokenLimitMatch = rawStr.match(
        /The input token count exceeds the maximum number of tokens allowed\s*(\d+)/i
      );
      if (tokenLimitMatch) {
        return `被路由请重试（当前请求被路由至上限为 ${tokenLimitMatch[1]} Token 的节点，请直接重试或缩减上下文）`;
      }

      // 3. 429 速率限制 / 配额耗尽
      if (
        httpStatus === 429 ||
        /\b429\b|RESOURCE_EXHAUSTED|Quota exceeded|rate[\s_-]*limit|Too Many Requests/i.test(rawStr)
      ) {
        return `请求被限流或渠道配额繁忙 (429)，请稍候几秒再试｜详情: ${rawStr.slice(0, 160)}`;
      }

      // 4. 502 / 503 / 504 反代网关超时或上游断开
      if (
        [502, 503, 504, 524].includes(httpStatus) ||
        /\b(?:502|503|504|524)\b|Bad Gateway|Gateway Timeout|Service Unavailable|Cloudflare/i.test(rawStr)
      ) {
        return `反代网关超时或上游节点无响应 (${httpStatus || "502/504"})，请直接重试`;
      }

      // 5. 401 / 403 鉴权失败
      if (
        [401, 403].includes(httpStatus) ||
        /\b(?:401|403)\b|Unauthorized|Forbidden|invalid_api_key|API_KEY_INVALID/i.test(rawStr)
      ) {
        return `API 密钥无效或当前渠道无权访问该模型 (${httpStatus || "401/403"})，请检查 API Key 与模型名`;
      }

      // 6. 网络断连 / CORS 跨域
      if (/Failed to fetch|NetworkError|Load failed/i.test(rawStr)) {
        return "网络连接中断或浏览器跨域拦截 (Failed to fetch)，请检查反代地址或重试";
      }

      return rawStr.slice(0, 320);
    }

    function normalizeOpenAiUrl(rawUrl, endpoint = "/chat/completions") {
      let url = String(rawUrl || "").trim();
      if (!url) return "";
      if (url.endsWith("#")) return url.slice(0, -1);
      url = url.replace(/\/+$/, "");
      if (endpoint === "/chat/completions") {
        if (/\/chat\/completions$/i.test(url)) return url;
        if (/\/v\d+[a-z0-9]*$/i.test(url)) return url + "/chat/completions";
        return url + "/v1/chat/completions";
      }
      if (endpoint === "/models") {
        url = url.replace(/\/chat\/completions$/i, "");
        if (/\/models$/i.test(url)) return url;
        if (/\/v\d+[a-z0-9]*$/i.test(url)) return url + "/models";
        return url + "/v1/models";
      }
      return url;
    }

    function resolveTavernHelperMethod(name, hostWin = window.parent || window, localWin = window) {
      const scopes = [
        localWin,
        hostWin,
        localWin?.TavernHelper,
        hostWin?.TavernHelper,
      ].filter(Boolean);
      for (const s of scopes) {
        if (typeof s[name] === "function") return s[name].bind(s);
      }
      return null;
    }

    async function fetchModelList(apiCfg) {
      const source = apiCfg.source || "openai";
      const baseUrl = String(apiCfg.url || "").trim();
      const apiKey = String(apiCfg.apiKey || "").trim();
      if (!baseUrl && source !== "gemini") {
        throw new Error("请先填写 API 地址 (Base URL)");
      }

      // 1. 优先调用酒馆助手 getModelList（走酒馆 Node.js 后端转发，绕过浏览器 CORS 跨域与 HTTP 混合内容限制）
      if (source === "openai" || source === "custom") {
        const thGetModelList = resolveTavernHelperMethod("getModelList");
        if (thGetModelList) {
          try {
            const normalizedApiUrl = baseUrl.replace(/\/+$/, "").replace(/\/chat\/completions$/i, "").replace(/\/models$/i, "");
            const models = await thGetModelList({
              apiurl: normalizedApiUrl,
              key: apiKey || undefined,
            });
            if (Array.isArray(models) && models.length > 0) {
              return models.map((m) => (typeof m === "string" ? m : m?.id || m?.name)).filter(Boolean);
            }
          } catch (thErr) {
            console.warn("[命定论坛] TavernHelper.getModelList 后端拉取未命中，尝试备用通道:", thErr);
          }
        }

        // 2. 备用通道：调用 SillyTavern 原生后端 /api/backends/chat-completions/status 代理接口
        try {
          const hostWin = window.parent || window;
          const stCtx = hostWin?.SillyTavern?.getContext?.() || window?.SillyTavern?.getContext?.();
          const reqHeaders = typeof stCtx?.getRequestHeaders === "function"
            ? stCtx.getRequestHeaders()
            : { "Content-Type": "application/json" };
          const normalizedApiUrl = baseUrl.replace(/\/+$/, "").replace(/\/chat\/completions$/i, "").replace(/\/models$/i, "");
          const statusRes = await fetch("/api/backends/chat-completions/status", {
            method: "POST",
            headers: { ...reqHeaders, "Content-Type": "application/json" },
            body: JSON.stringify({
              chat_completion_source: "custom",
              custom_url: normalizedApiUrl,
              reverse_proxy: normalizedApiUrl,
              proxy_password: apiKey,
            }),
          });
          if (statusRes.ok) {
            const statusData = await statusRes.json();
            const rawModels = Array.isArray(statusData?.data)
              ? statusData.data
              : Array.isArray(statusData?.models)
              ? statusData.models
              : Array.isArray(statusData)
              ? statusData
              : [];
            const parsedModels = rawModels
              .map((item) => (typeof item === "string" ? item : item?.id || item?.name))
              .filter(Boolean);
            if (parsedModels.length > 0) return parsedModels;
          }
        } catch (stErr) {
          console.warn("[命定论坛] 酒馆后端 status 接口拉取未命中，尝试浏览器前端直连:", stErr);
        }
      }

      // 3. 浏览器前端 fetch 直连通道
      if (source === "gemini") {
        const hostUrl = baseUrl
          ? baseUrl.replace(/\/+$/, "").replace(/\/v1beta.*$/i, "")
          : "https://generativelanguage.googleapis.com";
        const res = await fetch(
          `${hostUrl}/v1beta/models?key=${encodeURIComponent(apiKey)}`
        );
        if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
        const data = await res.json();
        return (data.models || [])
          .map((m) => String(m.name || "").replace(/^models\//, ""))
          .filter(Boolean);
      }

      const modelsUrl = normalizeOpenAiUrl(baseUrl, "/models");
      if (!modelsUrl) throw new Error("请先填写 API 地址 (Base URL)");
      const headers = { Accept: "application/json" };
      if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;
      const res = await fetch(modelsUrl, { method: "GET", headers });
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
      const data = await res.json();
      const list = Array.isArray(data?.data)
        ? data.data
        : Array.isArray(data?.models)
        ? data.models
        : Array.isArray(data)
        ? data
        : [];
      return list.map((item) => (typeof item === "string" ? item : item?.id || item?.name)).filter(Boolean);
    }

    let currentTavernGenId = null;

    function cancelActiveRequest() {
      if (currentAbortController) {
        try {
          currentAbortController.abort();
        } catch {}
        currentAbortController = null;
      }
      if (currentTavernGenId) {
        try {
          const stopById =
            typeof stopGenerationById === "function"
              ? stopGenerationById
              : window?.TavernHelper?.stopGenerationById || parent?.TavernHelper?.stopGenerationById;
          stopById?.(currentTavernGenId);
        } catch {}
        currentTavernGenId = null;
      }
    }

    // 绑定酒馆流式事件（同时监听 iframe_events 与 tavern_events，确保任何版本酒馆下均能实时触发流式回调）
    function bindTavernStreamEvents(host, localWin, genId, onStreamChunk) {
      const cleanups = [];
      const scopes = [...new Set([localWin, host, window.parent, window.top, window].filter(Boolean))];
      let evOn = typeof eventOn === "function" ? eventOn : null;
      let evRem = typeof eventRemoveListener === "function" ? eventRemoveListener : null;
      let iframeEvs = typeof iframe_events !== "undefined" ? iframe_events : null;
      let tavernEvs = typeof tavern_events !== "undefined" ? tavern_events : null;

      for (const s of scopes) {
        try {
          if (!evOn) evOn = s.eventOn || s.TavernHelper?.eventOn;
          if (!evRem) evRem = s.eventRemoveListener || s.TavernHelper?.eventRemoveListener;
          if (!iframeEvs) iframeEvs = s.iframe_events || s.TavernHelper?.iframe_events;
          if (!tavernEvs) tavernEvs = s.tavern_events || s.TavernHelper?.tavern_events;
        } catch {}
      }

      if (typeof evOn !== "function") return () => {};

      const eventNames = new Set([
        iframeEvs?.STREAM_TOKEN_RECEIVED_FULLY || "js_stream_token_received_fully",
        tavernEvs?.STREAM_TOKEN_RECEIVED || "stream_token_received",
      ]);

      for (const evName of eventNames) {
        if (!evName) continue;
        const handler = (fullText, targetId) => {
          if (typeof fullText !== "string" || !fullText) return;
          if (!targetId || targetId === genId) {
            onStreamChunk?.(fullText, false);
          }
        };
        try {
          const sub = evOn(evName, handler);
          cleanups.push(() => {
            try { sub?.stop?.(); } catch {}
            try { evRem?.(evName, handler); } catch {}
          });
        } catch {}
      }

      return () => {
        for (const fn of cleanups) fn();
      };
    }

    async function generate({
      host,
      localWin,
      settings,
      systemPrompt,
      userPrompt,
      orderedPrompts,
      onStreamChunk,
    }) {
      cancelActiveRequest();
      const controller = new AbortController();
      currentAbortController = controller;

      const rawMessagesList =
        Array.isArray(orderedPrompts) && orderedPrompts.length >= 2
          ? orderedPrompts
          : [
              { role: "system", content: systemPrompt },
              { role: "user", content: userPrompt },
            ];

      const useToolOnce = ForumToolOutputPacker.isToolOutputActive(settings, rawMessagesList);
      const toolPack = useToolOnce
        ? ForumToolOutputPacker.packContextIntoFakeTool({
            rawMessagesList,
            systemPrompt,
            userPrompt,
            settings,
          })
        : null;

      let seenNonSystem = false;
      const messagesList = (toolPack ? toolPack.packedMessages : rawMessagesList).map((m) => {
        const rawRole = m?.role || "user";
        if (rawRole !== "system") seenNonSystem = true;
        return {
          ...m,
          role: seenNonSystem && rawRole === "system" ? "user" : rawRole,
          content: ForumToolOutputPacker.stripToolMarkers(m?.content || ""),
        };
      });

      // 若开启了「🎲 头部乱码（6000字符破缓存）」且首条消息尚未包含 <system_entropy_padding>，自动在第一条非空消息头部前置注入
      if (settings?.enableHeaderGibberish && messagesList.length > 0) {
        const firstTarget = messagesList.find((m) => String(m?.content || "").trim().length > 0) || messagesList[0];
        if (firstTarget && !String(firstTarget.content || "").startsWith("<system_entropy_padding>")) {
          firstTarget.content = `${buildWrappedEntropyHeader()}\n\n${firstTarget.content}`;
        }
      }

      // 当通过酒馆 generateRaw 发送且开启了工具一次调用时，挂载临时请求/响应拦截器注入伪造工具并解包 tool_calls
      const runWithTavernToolInterceptor = async (fn) => {
        if (!toolPack) return await fn();
        const targetWin = host || window;
        const origFetch = typeof targetWin.fetch === "function" ? targetWin.fetch.bind(targetWin) : null;
        let capturedToolText = "";
        let pendingStreamPromise = null;

        const scopes = [...new Set([localWin, host, window.parent, window].filter(Boolean))];
        let evOn = typeof eventOn === "function" ? eventOn : null;
        let evRem = typeof eventRemoveListener === "function" ? eventRemoveListener : null;
        let tavernEvs = typeof tavern_events !== "undefined" ? tavern_events : null;
        for (const s of scopes) {
          try {
            if (!evOn) evOn = s.eventOn || s.TavernHelper?.eventOn;
            if (!evRem) evRem = s.eventRemoveListener || s.TavernHelper?.eventRemoveListener;
            if (!tavernEvs) tavernEvs = s.tavern_events || s.TavernHelper?.tavern_events;
          } catch {}
        }

        const onSettingsReady = (genData) => {
          if (!genData || typeof genData !== "object") return;
          genData.tools = toolPack.openAiTools;
          genData.tool_choice = toolPack.openAiToolChoice;
        };

        let subReady = null;
        if (typeof evOn === "function" && tavernEvs?.CHAT_COMPLETION_SETTINGS_READY) {
          try {
            subReady = evOn(tavernEvs.CHAT_COMPLETION_SETTINGS_READY, onSettingsReady);
          } catch {}
        }

        if (origFetch) {
          targetWin.fetch = async (input, init) => {
            const urlStr = typeof input === "string" ? input : input?.url || "";
            if (
              init &&
              typeof init.body === "string" &&
              /\/api\/backends\/chat-completions\/generate/i.test(urlStr)
            ) {
              try {
                const bodyObj = JSON.parse(init.body);
                bodyObj.tools = toolPack.openAiTools;
                bodyObj.tool_choice = toolPack.openAiToolChoice;
                init = { ...init, body: JSON.stringify(bodyObj) };
              } catch {}

              const response = await origFetch(input, init);
              if (!response.ok) return response;

              const contentType = response.headers?.get?.("content-type") || "";
              if (contentType.includes("application/json")) {
                try {
                  const cloneData = await response.clone().json();
                  const unpacked =
                    ForumToolOutputPacker.extractNonStreamToolResponse(cloneData, "openai") ||
                    ForumToolOutputPacker.extractNonStreamToolResponse(cloneData, "gemini") ||
                    ForumToolOutputPacker.extractNonStreamToolResponse(cloneData, "claude");
                  if (unpacked) {
                    capturedToolText = unpacked;
                    if (cloneData?.choices?.[0]?.message) {
                      cloneData.choices[0].message.content = unpacked;
                      delete cloneData.choices[0].message.tool_calls;
                      delete cloneData.choices[0].message.function_call;
                    }
                    return new Response(JSON.stringify(cloneData), {
                      status: response.status,
                      statusText: response.statusText,
                      headers: response.headers,
                    });
                  }
                } catch {}
                return response;
              }

              if (response.body && typeof response.body.tee === "function") {
                try {
                  const [branchForTavern, branchForForum] = response.body.tee();
                  pendingStreamPromise = readSseStream(
                    branchForForum,
                    (json) => extractUniversalOpenAiOrGeminiDelta(json),
                    (snapshot, isDone, meta) => {
                      if (snapshot) {
                        capturedToolText = snapshot;
                      }
                      onStreamChunk?.(snapshot, isDone, meta);
                    }
                  ).catch(() => {});
                  return new Response(branchForTavern, {
                    status: response.status,
                    statusText: response.statusText,
                    headers: response.headers,
                  });
                } catch {}
              }
              return response;
            }
            return origFetch(input, init);
          };
        }

        try {
          const rawRes = await fn();
          if (pendingStreamPromise) {
            try { await pendingStreamPromise; } catch {}
          }
          const directText =
            typeof rawRes === "string" ? rawRes : String(rawRes?.text ?? rawRes?.content ?? "");
          return directText.trim() || capturedToolText;
        } finally {
          if (origFetch) targetWin.fetch = origFetch;
          try { subReady?.stop?.(); } catch {}
          if (typeof evRem === "function" && tavernEvs?.CHAT_COMPLETION_SETTINGS_READY) {
            try { evRem(tavernEvs.CHAT_COMPLETION_SETTINGS_READY, onSettingsReady); } catch {}
          }
        }
      };

      try {
        if (settings.apiMode === "tavern") {
          const genRaw =
            typeof generateRaw === "function"
              ? generateRaw
              : localWin?.TavernHelper?.generateRaw || host?.TavernHelper?.generateRaw;
          if (!genRaw) {
            throw new Error(
              "未检测到酒馆助手的 generateRaw 接口，请切换为「独立API直连」模式并配置 API。"
            );
          }

          const useStream = settings.stream !== false;
          const genId = "dlc-forum-" + Date.now();
          currentTavernGenId = genId;
          const stopStreamListener = useStream
            ? bindTavernStreamEvents(host, localWin, genId, onStreamChunk)
            : null;

          let text = "";
          try {
            text = await runWithTavernToolInterceptor(async () => {
              return await genRaw({
                generation_id: genId,
                should_stream: useStream,
                ordered_prompts: messagesList,
              });
            });
          } finally {
            try { stopStreamListener?.(); } catch {}
            if (currentTavernGenId === genId) currentTavernGenId = null;
          }

          onStreamChunk?.(text, true);
          return text;
        }

        const source = settings.apiSource || "openai";
        const apiKey = String(settings.apiKey || "").trim();
        const model = String(settings.apiModel || "").trim();
        const temperature = Number.isFinite(Number(settings.temperature))
          ? Number(settings.temperature)
          : 0.95;
        const maxTokens = Math.min(
          60000,
          Number.isFinite(Number(settings.maxTokens))
            ? Math.max(256, Number(settings.maxTokens))
            : 20000
        );
        const useStream = settings.stream !== false;

        if (!model) throw new Error("请先在「API设置」中填写或选择模型名称 (Model)");

        const firstNonSysIdx = messagesList.findIndex((m) => m.role !== "system");
        let leadingSysText =
          firstNonSysIdx > 0
            ? messagesList
                .slice(0, firstNonSysIdx)
                .map((m) => m.content)
                .join("\n\n")
                .trim()
            : ForumToolOutputPacker.stripToolMarkers(systemPrompt);
        if (settings?.enableHeaderGibberish && leadingSysText && !leadingSysText.startsWith("<system_entropy_padding>")) {
          leadingSysText = `${buildWrappedEntropyHeader()}\n\n${leadingSysText}`;
        }
        const conversationSlice = (
          firstNonSysIdx >= 0 ? messagesList.slice(firstNonSysIdx) : messagesList
        ).map((m) => ({
          ...m,
          role: m.role === "system" ? "user" : m.role,
        }));

        if (source === "gemini") {
          const base = String(settings.apiUrl || "https://generativelanguage.googleapis.com")
            .trim()
            .replace(/\/+$/, "")
            .replace(/\/v1beta.*$/i, "");
          const action = useStream ? "streamGenerateContent?alt=sse&" : "generateContent?";
          const url = `${base}/v1beta/models/${encodeURIComponent(model)}:${action}key=${encodeURIComponent(apiKey)}`;
          const geminiContents = conversationSlice.map((m) => ({
            role: m.role === "assistant" ? "model" : "user",
            parts: [{ text: m.content }],
          }));
          const body = {
            systemInstruction: { parts: [{ text: leadingSysText }] },
            contents: geminiContents.length
              ? geminiContents
              : [{ role: "user", parts: [{ text: ForumToolOutputPacker.stripToolMarkers(userPrompt) }] }],
            safetySettings: [
              { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
              { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
              { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
              { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
              { category: "HARM_CATEGORY_CIVIC_INTEGRITY", threshold: "BLOCK_NONE" },
            ],
            generationConfig: {
              temperature,
              maxOutputTokens: maxTokens,
              ...(toolPack ? {} : { stopSequences: ["Participant:"] }),
            },
            ...(toolPack
              ? {
                  tools: toolPack.geminiTools,
                  toolConfig: toolPack.geminiToolConfig,
                }
              : {}),
          };
          const res = await fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
            signal: controller.signal,
          });
          if (!res.ok) { const errTxt = await res.text(); throw new Error(diagnoseApiError(errTxt, res.status)); }
          if (!useStream || !res.body) {
            const data = await res.json();
            const text = ForumToolOutputPacker.extractNonStreamToolResponse(data, "gemini");
            onStreamChunk?.(text, true);
            return text;
          }
          return await readSseStream(
            res.body,
            (json) => {
              const parts = json?.candidates?.[0]?.content?.parts || [];
              let contentDelta = "";
              let reasoningDelta = "";
              let toolFullContent = "";
              for (const p of parts) {
                if (p?.functionCall) {
                  toolFullContent += ForumToolOutputPacker.extractContentFromToolArgs(
                    p.functionCall.args
                  );
                } else if (p?.thought) {
                  reasoningDelta += p.text || "";
                } else {
                  contentDelta += p?.text || "";
                }
              }
              return { contentDelta, reasoningDelta, toolFullContent };
            },
            onStreamChunk
          );
        }

        if (source === "claude") {
          let url = String(settings.apiUrl || "https://api.anthropic.com").trim().replace(/\/+$/, "");
          if (!/\/messages$/i.test(url)) {
            url = /\/v1$/i.test(url) ? url + "/messages" : url + "/v1/messages";
          }
          const claudeMsgs = conversationSlice.map((m) => ({
            role: m.role === "assistant" ? "assistant" : "user",
            content: m.content,
          }));
          const res = await fetch(url, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-api-key": apiKey,
              "anthropic-version": "2023-06-01",
              "anthropic-dangerous-direct-browser-access": "true",
            },
            body: JSON.stringify({
              model,
              max_tokens: maxTokens,
              temperature,
              system: leadingSysText,
              messages: claudeMsgs.length
                ? claudeMsgs
                : [{ role: "user", content: ForumToolOutputPacker.stripToolMarkers(userPrompt) }],
              stream: useStream,
              ...(toolPack
                ? {
                    tools: toolPack.claudeTools,
                    tool_choice: toolPack.claudeToolChoice,
                  }
                : {}),
            }),
            signal: controller.signal,
          });
          if (!res.ok) { const errTxt = await res.text(); throw new Error(diagnoseApiError(errTxt, res.status)); }
          if (!useStream || !res.body) {
            const data = await res.json();
            const text = ForumToolOutputPacker.extractNonStreamToolResponse(data, "claude");
            onStreamChunk?.(text, true);
            return text;
          }
          return await readSseStream(
            res.body,
            (json) => {
              if (json?.type === "content_block_delta") {
                return {
                  contentDelta: json?.delta?.text || "",
                  reasoningDelta: json?.delta?.thinking || "",
                  toolArgsDelta: json?.delta?.partial_json || "",
                };
              }
              return "";
            },
            onStreamChunk
          );
        }

        const rawApiUrl = String(settings.apiUrl || "").trim();
        const url = normalizeOpenAiUrl(rawApiUrl, "/chat/completions");
        if (!url) throw new Error("请先在「API设置」中填写独立 API 地址 (Base URL)");

        const cleanBaseUrl = rawApiUrl.replace(/\/+$/, "").replace(/\/chat\/completions$/i, "");

        const generateViaTavernCustomApi = async () => {
          const genRaw = resolveTavernHelperMethod("generateRaw", host, localWin);
          if (!genRaw) return null;
          const genId = "dlc-forum-custom-" + Date.now();
          currentTavernGenId = genId;
          const stopStreamListener = useStream
            ? bindTavernStreamEvents(host, localWin, genId, onStreamChunk)
            : null;

          try {
            const text = await runWithTavernToolInterceptor(async () => {
              return await genRaw({
                generation_id: genId,
                should_stream: useStream,
                should_silence: true,
                custom_api: {
                  apiurl: cleanBaseUrl,
                  key: apiKey,
                  model,
                  source: "openai",
                  temperature,
                  max_tokens: maxTokens,
                },
                ordered_prompts: messagesList,
              });
            });
            onStreamChunk?.(text, true);
            return text;
          } finally {
            try { stopStreamListener?.(); } catch {}
            if (currentTavernGenId === genId) currentTavernGenId = null;
          }
        };

        const isMixedContentRisk =
          (host?.location?.protocol === "https:" || window?.location?.protocol === "https:") &&
          /^http:\/\//i.test(url);

        if (isMixedContentRisk) {
          const viaBackend = await generateViaTavernCustomApi();
          if (viaBackend !== null) return viaBackend;
        }

        const headers = { "Content-Type": "application/json" };
        if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;

        // 针对 4argon 等反代的「假流式」模型 + Pro 慢速模型的工具调用适配：
        // 1. 支持根据设置选择 tool_choice 策略（默认 auto/required 兼容或强制函数名），对于带有“假流式”且为 Pro 的模型，限制过高的思考预算导致反代非流式上游超时
        const isFakeStreamModel = /假流式|fake[_\s-]*stream/i.test(model);
        const isProModel = /\bpro\b|gemini-2\.5-pro|gemini-3/i.test(model) && !/flash/i.test(model);
        const effectiveToolChoice = toolPack
          ? settings.toolChoiceMode === "auto"
            ? "auto"
            : settings.toolChoiceMode === "required"
            ? "required"
            : toolPack.openAiToolChoice
          : undefined;

        const payload = {
          model,
          messages: messagesList,
          temperature,
          max_tokens: maxTokens,
          stream: useStream,
          ...(toolPack
            ? {
                tools: toolPack.openAiTools,
                tool_choice: effectiveToolChoice,
                ...(isFakeStreamModel && isProModel ? { reasoning_effort: "low" } : {}),
              }
            : {}),
        };

        const fetchStartTime = Date.now();
        try {
          const res = await fetch(url, {
            method: "POST",
            headers,
            body: JSON.stringify(payload),
            signal: controller.signal,
          });
          if (!res.ok) {
            const errText = await res.text();
            const httpErr = new Error(diagnoseApiError(errText, res.status));
            httpErr.isHttpError = true;
            httpErr.status = res.status;
            throw httpErr;
          }
          if (!useStream || !res.body) {
            const data = await res.json();
            const text =
              ForumToolOutputPacker.extractNonStreamToolResponse(data, "openai") ||
              ForumToolOutputPacker.extractNonStreamToolResponse(data, "gemini") ||
              ForumToolOutputPacker.extractNonStreamToolResponse(data, "claude");
            onStreamChunk?.(text, true);
            return text;
          }
          return await readSseStream(
            res.body,
            (json) => extractUniversalOpenAiOrGeminiDelta(json),
            onStreamChunk
          );
        } catch (fetchErr) {
          if (fetchErr?.name === "AbortError") throw fetchErr;
          // 关键修复：仅当请求在 8 秒内因浏览器 CORS 跨域或纯前端网络拦截 (TypeError / Failed to fetch) 失败时，
          // 才自动切换酒馆后端 custom_api 代理重试；绝不在反代等待几分钟超时 (502/504/连接断开) 后静默发起第二次 5 分钟死等！
          const elapsedMs = Date.now() - fetchStartTime;
          const isImmediateCorsError =
            !fetchErr?.isHttpError &&
            elapsedMs < 8000 &&
            (fetchErr instanceof TypeError ||
              /Failed to fetch|NetworkError|Load failed/i.test(String(fetchErr?.message || "")));
          if (!isImmediateCorsError) {
            throw fetchErr;
          }
          console.warn("[命定论坛] 前端直连生成受阻（检测到首包 CORS 跨域或 HTTP 混合内容限制），自动切换酒馆后端 custom_api 代理重试:", fetchErr);
          const fallbackText = await generateViaTavernCustomApi();
          if (fallbackText !== null) return fallbackText;
          throw fetchErr;
        }
      } finally {
        if (currentAbortController === controller) {
          currentAbortController = null;
        }
      }
    }

    // 统一兼容 OpenAI 真流式、4argon 假流式、完整 message 包、对象型 arguments 以及原生 Gemini candidates 包的增量提取器
    function extractUniversalOpenAiOrGeminiDelta(json) {
      if (!json || typeof json !== "object") return "";
      const choice = json?.choices?.[0];
      const delta = choice?.delta;
      const msg = choice?.message;

      let contentDelta = "";
      let reasoningDelta = "";
      let toolArgsDelta = "";
      let toolFullContent = "";

      if (delta) {
        if (typeof delta.content === "string") {
          contentDelta += delta.content;
        }
        if (typeof delta.reasoning_content === "string") {
          reasoningDelta += delta.reasoning_content;
        } else if (typeof delta.reasoning === "string") {
          reasoningDelta += delta.reasoning;
        }

        const toolCalls = delta.tool_calls;
        if (Array.isArray(toolCalls)) {
          for (const tc of toolCalls) {
            const rawArg = tc?.function?.arguments ?? tc?.arguments;
            if (typeof rawArg === "string") {
              toolArgsDelta += rawArg;
            } else if (rawArg && typeof rawArg === "object") {
              const unpackedObj = ForumToolOutputPacker.extractContentFromToolArgs(rawArg);
              if (unpackedObj) toolFullContent += unpackedObj;
            }
          }
        } else if (delta.function_call?.arguments) {
          const rawFcArg = delta.function_call.arguments;
          if (typeof rawFcArg === "string") {
            toolArgsDelta += rawFcArg;
          } else if (typeof rawFcArg === "object") {
            const unpackedObj = ForumToolOutputPacker.extractContentFromToolArgs(rawFcArg);
            if (unpackedObj) toolFullContent += unpackedObj;
          }
        }
      }

      // 兼容假流式一次性在 choices[0].message 中返回完整 tool_calls 或 content 的情况
      if (msg) {
        const msgToolCalls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
        for (const tc of msgToolCalls) {
          const rawArg = tc?.function?.arguments ?? tc?.arguments;
          const extracted = ForumToolOutputPacker.extractContentFromToolArgs(rawArg);
          if (extracted) toolFullContent += extracted;
        }
        if (!toolFullContent && msg.function_call?.arguments) {
          const extracted = ForumToolOutputPacker.extractContentFromToolArgs(msg.function_call.arguments);
          if (extracted) toolFullContent += extracted;
        }
        if (!contentDelta && !toolFullContent && typeof msg.content === "string" && msg.content) {
          contentDelta += msg.content;
        }
        if (!reasoningDelta && typeof (msg.reasoning_content || msg.reasoning) === "string") {
          reasoningDelta += msg.reasoning_content || msg.reasoning;
        }
      }

      // 兼容部分反代在假流式 SSE 中直接透传 Gemini candidates 结构
      const geminiParts = json?.candidates?.[0]?.content?.parts;
      if (Array.isArray(geminiParts)) {
        for (const p of geminiParts) {
          if (p?.functionCall) {
            const extracted = ForumToolOutputPacker.extractContentFromToolArgs(p.functionCall.args ?? p.functionCall);
            if (extracted) toolFullContent += extracted;
          } else if (p?.thought) {
            reasoningDelta += p.text || "";
          } else if (typeof p?.text === "string") {
            contentDelta += p.text;
          }
        }
      }

      return {
        contentDelta,
        reasoningDelta,
        toolArgsDelta,
        toolFullContent,
      };
    }

    async function readSseStream(readableStream, extractDelta, onStreamChunk) {
      const reader = readableStream.getReader();
      const decoder = new TextDecoder("utf-8");
      let buffer = "";
      let contentAccumulated = "";
      let reasoningAccumulated = "";
      let toolArgsAccumulated = "";
      let toolExtractedContent = "";
      let heartbeatCount = 0;
      const streamStartTime = Date.now();

      const buildStreamSnapshot = () => {
        let effectiveContent = toolExtractedContent || contentAccumulated;
        // 若假流式反代将工具调用 JSON 字符串直接塞进了常规 content 通道，自动解包提取
        if (
          !toolExtractedContent &&
          contentAccumulated &&
          contentAccumulated.trim().startsWith("{") &&
          contentAccumulated.includes("<recorder_")
        ) {
          const unpackedFromContent = ForumToolOutputPacker.extractContentFromToolArgs(contentAccumulated);
          if (unpackedFromContent) {
            effectiveContent = unpackedFromContent;
          }
        }
        if (reasoningAccumulated) {
          return effectiveContent
            ? `<think>\n${reasoningAccumulated}\n</think>\n${effectiveContent}`
            : `<think>\n${reasoningAccumulated}`;
        }
        return effectiveContent;
      };

      const processSseLine = (line) => {
        const trimmed = line.trim();
        if (!trimmed) return;
        // 识别 4argon 等假流式反代发送的 ": keep-alive" 注释心跳包，实时更新状态栏避免假死感
        if (trimmed.startsWith(":")) {
          heartbeatCount++;
          if (!contentAccumulated && !toolExtractedContent && !reasoningAccumulated) {
            onStreamChunk?.("", false, {
              isHeartbeat: true,
              heartbeatCount,
              elapsedSec: Math.round((Date.now() - streamStartTime) / 1000),
            });
          }
          return;
        }
        if (!trimmed.startsWith("data:")) return;
        const payload = trimmed.slice(5).trim();
        if (!payload || payload === "[DONE]") return;
        try {
          const parsed = JSON.parse(payload);
          const delta = extractDelta(parsed);
          if (delta && typeof delta === "object") {
            let changed = false;
            if (delta.reasoningDelta) {
              reasoningAccumulated += delta.reasoningDelta;
              changed = true;
            }
            if (delta.contentDelta) {
              contentAccumulated += delta.contentDelta;
              changed = true;
            }
            if (delta.toolArgsDelta) {
              toolArgsAccumulated += delta.toolArgsDelta;
              const unpacked = ForumToolOutputPacker.extractContentFromToolArgs(
                toolArgsAccumulated
              );
              if (unpacked !== toolExtractedContent) {
                toolExtractedContent = unpacked;
                changed = true;
              }
            }
            if (delta.toolFullContent) {
              toolExtractedContent = delta.toolFullContent;
              changed = true;
            }
            if (changed) {
              onStreamChunk?.(buildStreamSnapshot(), false);
            } else if (!contentAccumulated && !toolExtractedContent && !reasoningAccumulated) {
              heartbeatCount++;
              onStreamChunk?.("", false, {
                isHeartbeat: true,
                heartbeatCount,
                elapsedSec: Math.round((Date.now() - streamStartTime) / 1000),
              });
            }
          } else if (typeof delta === "string" && delta) {
            contentAccumulated += delta;
            onStreamChunk?.(buildStreamSnapshot(), false);
          }
        } catch {}
      };

      while (true) {
        const { value, done } = await reader.read();
        if (done) {
          buffer += decoder.decode();
          break;
        }
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || "";
        for (const line of lines) {
          processSseLine(line);
        }
      }

      // 关键修复：处理假流式在流关闭 (done=true) 前最后一个未带换行符的超大尾包！
      if (buffer.trim()) {
        for (const remLine of buffer.split(/\r?\n/)) {
          processSseLine(remLine);
        }
        buffer = "";
      }

      if (toolArgsAccumulated && !toolExtractedContent) {
        toolExtractedContent = ForumToolOutputPacker.extractContentFromToolArgs(toolArgsAccumulated);
      }
      const finalOut = toolExtractedContent || buildStreamSnapshot() || contentAccumulated;
      onStreamChunk?.(finalOut, true);
      return finalOut;
    }

    return {
      fetchModelList,
      generate,
      cancelActiveRequest,
      diagnoseApiError,
    };
  })();

  /* ============================================================================
   * 10. 主输入框联动与脚本独立扩展变量树管理器 (forum_data)
   * ============================================================================ */
  function fillOrSendToTavern(host, text, directSend = false) {
    const content = String(text || "").trim();
    if (!content) return { ok: false, msg: "内容为空" };
    const doc = host.document;
    const textarea = doc.querySelector("#send_textarea");
    if (!textarea) return { ok: false, msg: "未找到酒馆主聊天输入框 (#send_textarea)" };

    const existing = textarea.value.trim();
    const combined = existing ? `${existing}\n\n${content}` : content;
    const owner = textarea.ownerDocument.defaultView || host;
    const setter = Object.getOwnPropertyDescriptor(
      owner.HTMLTextAreaElement.prototype,
      "value"
    )?.set;
    if (setter) setter.call(textarea, combined);
    else textarea.value = combined;

    textarea.dispatchEvent(new owner.Event("input", { bubbles: true }));
    textarea.dispatchEvent(new owner.Event("change", { bubbles: true }));

    if (directSend) {
      const sendBtn = doc.querySelector("#send_but");
      if (sendBtn && !sendBtn.disabled) {
        sendBtn.click();
        return { ok: true, msg: "已作为本轮行动发送至主聊天！" };
      }
      return { ok: true, msg: "已填入主聊天输入框，请点击酒馆发送按钮提交。" };
    }
    try {
      textarea.focus({ preventScroll: true });
    } catch {}
    return { ok: true, msg: "已填入主聊天输入框！可继续补充后发送。" };
  }

  // 命定论坛行动线索世界书管理器：维护 `forum_data` 行动线索树并同步至角色主世界书🔵蓝灯常驻条目
  const ForumVariableTreeManager = (() => {
    const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
    const deepClone = (v) => {
      if (v == null || typeof v !== "object") return v;
      try {
        return JSON.parse(JSON.stringify(v));
      } catch {
        return Array.isArray(v) ? [...v] : { ...v };
      }
    };

    function getScopes(host, localWin) {
      return [
        ...new Set(
          [localWin, host, localWin?.TavernHelper, host?.TavernHelper, window.parent, window].filter(
            Boolean
          )
        ),
      ];
    }

    function findMethod(scopes, name) {
      for (const s of scopes) {
        if (typeof s[name] === "function") return s[name].bind(s);
      }
      return null;
    }

    function createDefaultForumDataTree() {
      return {
        _meta: {
          name: "命定论坛行动线索数据树 (forum_data)",
          desc: "玩家从命定论坛（阿斯塔利亚表版/里版）注入的行动线索与帖子实录，属于已确认的世界内客观信息",
          updatedAt: "",
        },
        当前行动线索: null,
        已注入帖子列表: [],
      };
    }

    function sanitizeClueEntry(rawItem) {
      if (!isObj(rawItem)) return null;
      const copy = { ...rawItem };
      delete copy.完整帖子原文;
      delete copy.玩家行动意向;
      return copy;
    }

    function formatCluePreviewText(item) {
      if (!isObj(item)) return "";
      const parts = [];
      if (item.正文内容) parts.push(`【正文内容】\n${item.正文内容}`);
      if (item.魔导留影石画面 && item.魔导留影石画面 !== "无") {
        parts.push(`【魔导留影石画面】\n${item.魔导留影石画面}`);
      }
      if (Array.isArray(item.盖楼回复) && item.盖楼回复.length > 0) {
        parts.push(`【盖楼回复 (${item.盖楼回复.length}层)】\n${item.盖楼回复.join("\n")}`);
      }
      return parts.join("\n\n");
    }

    function normalizeForumDataTree(rawTree) {
      const base = createDefaultForumDataTree();
      if (!isObj(rawTree)) return base;
      const rawList = Array.isArray(rawTree.已注入帖子列表)
        ? rawTree.已注入帖子列表
        : Array.isArray(rawTree.已关注帖子列表)
        ? rawTree.已关注帖子列表
        : [];
      const list = rawList.map(sanitizeClueEntry).filter(Boolean);
      const active = isObj(rawTree.当前行动线索)
        ? sanitizeClueEntry(rawTree.当前行动线索)
        : list.length > 0
        ? list[0]
        : null;
      return {
        ...rawTree,
        _meta: {
          ...base._meta,
          ...(isObj(rawTree._meta) ? rawTree._meta : {}),
        },
        当前行动线索: active,
        已注入帖子列表: list,
      };
    }

    // 从单帖 DOM 提取结构化帖子与盖楼详情
    function extractPostStructuredData(postEl, boardName, postId, forumMode = "surface") {
      const isDark = forumMode === "dark";
      const forumLabel = isDark ? "阿斯塔利亚里版论坛" : "阿斯塔利亚论坛（表版）";

      const titleEl = postEl?.querySelector(".ast-post-title, h3, h2");
      const title = titleEl ? titleEl.textContent.trim() : "未命名论坛帖";

      const authorEl = postEl?.querySelector(".ast-post-meta .ast-author, .ast-author");
      const author = authorEl
        ? authorEl.textContent.replace(/^👤\s*/, "").trim()
        : "匿名坛友";

      const adminEl = postEl?.querySelector(".ast-post-meta .ast-admin, .ast-admin");
      const adminIdentity = adminEl
        ? adminEl.textContent.replace(/^👁️\s*(?:真实身份[:：]\s*)?/, "").trim()
        : "未知身份";

      const timeEl = postEl?.querySelector(".ast-post-meta .ast-time, .ast-time");
      const postTime = timeEl ? timeEl.textContent.replace(/^🕒\s*/, "").trim() : "刚刚";

      const bodyEl = postEl?.querySelector(".ast-post-body");
      let bodyText = "";
      if (bodyEl) {
        const cloneBody = bodyEl.cloneNode(true);
        for (const h of cloneBody.querySelectorAll(".ast-hidden-image-tag, image, imgthink, .ast-chatu8-widget")) {
          h.remove();
        }
        const pList = [...cloneBody.querySelectorAll("p")];
        if (pList.length > 0) {
          bodyText = pList.map((p) => p.textContent.trim()).filter(Boolean).join("\n");
        } else {
          bodyText = cloneBody.textContent.trim();
        }
        bodyText = bodyText
          .replace(/<imgthink\b[^>]*>[\s\S]*?<\/imgthink>/gi, "")
          .replace(/<image\b[^>]*>[\s\S]*?<\/image>/gi, "")
          .replace(/image###[\s\S]*?###/gi, "")
          .trim();
      }

      const imgDescEl = postEl?.querySelector(".ast-img .ast-img-desc");
      let imgDesc = "";
      if (imgDescEl) {
        const cloneDesc = imgDescEl.cloneNode(true);
        for (const h of cloneDesc.querySelectorAll(".ast-hidden-image-tag, image, imgthink")) {
          h.remove();
        }
        imgDesc = cloneDesc.textContent
          .replace(/image###[\s\S]*?###/gi, "")
          .replace(/\s+/g, " ")
          .trim();
      }

      const statsEl = postEl?.querySelector(".ast-stats");
      const statsText = statsEl
        ? [...statsEl.querySelectorAll("span")]
            .map((s) => s.textContent.trim())
            .filter(Boolean)
            .join(" ｜ ")
        : "";

      const replyEls = [...(postEl?.querySelectorAll(".ast-replies .ast-reply, .ast-reply") || [])];
      const replies = [];
      for (const rEl of replyEls) {
        if (rEl.classList?.contains("ast-reply-streaming-status")) continue;
        const floor = rEl.querySelector(".ast-floor")?.textContent?.trim() || `${replies.length + 1}L`;
        const rAuthor =
          rEl.querySelector(".ast-author")?.textContent?.replace(/^👤\s*/, "")?.trim() || "匿名层主";
        const rAdmin =
          rEl
            .querySelector(".ast-admin")
            ?.textContent?.replace(/^👁️\s*(?:真实身份[:：]\s*)?/, "")
            ?.trim() || "";
        const rText = extractReplyPureText(rEl);
        if (!rText) continue;
        replies.push({
          楼层: floor,
          昵称: rAuthor,
          真实身份: rAdmin || "未知",
          内容: rText,
          格式化: `${floor} [${rAuthor}${rAdmin ? `｜真实身份：${rAdmin}` : ""}]：${rText}`,
        });
      }

      const formattedTextBlock = [
        `【${forumLabel} · ${boardName}板块】《${title}》`,
        `- 发帖人：${author}（真实身份：${adminIdentity}）`,
        postTime ? `- 发帖时间：${postTime}` : "",
        statsText ? `- 帖子热度：${statsText}` : "",
        `- 帖子正文：\n${bodyText || "（无正文）"}`,
        imgDesc ? `- 魔导留影石实景画面：${imgDesc}` : "",
        replies.length > 0
          ? `- 评论区盖楼回复（共 ${replies.length} 层）：\n${replies.map((r) => "  " + r.格式化).join("\n")}`
          : "",
      ]
        .filter(Boolean)
        .join("\n");

      return {
        postId: postId || "post-1",
        forumMode,
        forumLabel,
        board: boardName || "综合",
        title,
        author,
        adminIdentity,
        postTime,
        bodyText,
        imgDesc,
        statsText,
        replies,
        formattedTextBlock,
      };
    }

    function buildClueEntryObject(postData, editedBodyText = "") {
      return {
        线索ID: `clue-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        帖子ID: postData.postId,
        来源论坛: postData.forumLabel,
        所属板块: postData.board,
        标题: postData.title,
        发帖人昵称: postData.author,
        发帖人真实身份: postData.adminIdentity,
        发帖时间: postData.postTime || "近期",
        热度数据: postData.statsText || "",
        正文内容: editedBodyText?.trim() || postData.bodyText || "",
        魔导留影石画面: postData.imgDesc || "无",
        盖楼回复: (postData.replies || []).map((r) => (typeof r === "string" ? r : r.格式化)),
        注入时间: new Date().toLocaleString("zh-CN", { hour12: false }),
      };
    }

    const LOCAL_FORUM_CLUES_KEY = "dlc_destined_forum_clues_tree_v1";
    const WORLDBOOK_ENTRY_NAME = "📌【命定论坛】已注入行动线索";
    let lastSyncedWorldbookStatus = { ok: false, bookName: "", action: "未执行", error: "" };

    // 将论坛行动线索组装为写入线索世界书蓝灯条目的结构化提示词文本（默认仅写入当前行动线索）
    function buildWorldbookClueContent(forumData, { scope = "active_only" } = {}) {
      const normalized = normalizeForumDataTree(forumData);
      const active = normalized.当前行动线索;
      const list = Array.isArray(normalized.已注入帖子列表) ? normalized.已注入帖子列表 : [];
      if (!active && list.length === 0) return "";

      const payload =
        scope === "full"
          ? {
              当前行动线索: active,
              已注入帖子列表: list,
            }
          : {
              当前行动线索: active || list[0] || null,
            };

      return `<forum_data_variables name="命定论坛行动线索">
【命定论坛（阿斯塔利亚星网）已注入行动线索】
以下为 <user> 在命定论坛中浏览并注入的真实帖子情报（含发帖人匿名昵称、后台管理员透视真实身份、正文、魔导留影石画面及各楼层回复）。当 <user> 在行动中提及、调查、前往或回应相关帖子与人物时，请严格依据此情报中的客观事实、人物身份、层级与地点进行推演：
${JSON.stringify(payload, null, 2)}
</forum_data_variables>`;
    }

    // 探测当前角色/聊天绑定的目标世界书名称（严格使用酒馆助手官方 getCharWorldbookNames('current') 等 API）
    async function resolveTargetWorldbookName(host, localWin) {
      const scopes = getScopes(host, localWin);
      const stCtx = ForumMacroEngine.getStContext(host, localWin);
      const candidates = [];
      const addBook = (b) => {
        const s = typeof b === "string" ? b.trim() : "";
        if (s && !candidates.includes(s)) candidates.push(s);
      };

      // 1. 酒馆助手现代官方 API: getCharWorldbookNames('current') & getChatWorldbookName('current')
      const getCharWbNames = findMethod(scopes, "getCharWorldbookNames");
      if (getCharWbNames) {
        try {
          const res = await getCharWbNames("current");
          if (isObj(res)) {
            addBook(res.primary);
            if (Array.isArray(res.additional)) res.additional.forEach(addBook);
          }
        } catch {}
      }

      const getChatWbName = findMethod(scopes, "getChatWorldbookName");
      if (getChatWbName) {
        try {
          addBook(await getChatWbName("current"));
        } catch {}
      }

      // 2. 兼容旧版 API: getCurrentCharPrimaryLorebook() & getCharLorebooks({name:'current'})
      const getPrimaryLb = findMethod(scopes, "getCurrentCharPrimaryLorebook");
      if (getPrimaryLb) {
        try {
          addBook(await getPrimaryLb());
        } catch {}
      }

      const getCharLbs = findMethod(scopes, "getCharLorebooks");
      if (getCharLbs) {
        try {
          const res = await getCharLbs({ name: "current" });
          if (isObj(res)) {
            addBook(res.primary);
            if (Array.isArray(res.additional)) res.additional.forEach(addBook);
          }
        } catch {}
      }

      // 3. SillyTavern 原生上下文回退
      if (stCtx) {
        try {
          const charObj = stCtx.characters?.[stCtx.characterId];
          addBook(charObj?.data?.extensions?.world || charObj?.world);
          addBook(stCtx.chatMetadata?.world_info);
        } catch {}
      }

      // 4. 全局开启的世界书回退
      const getGlobalWbNames =
        findMethod(scopes, "getGlobalWorldbookNames") || findMethod(scopes, "getGlobalLorebooks");
      if (getGlobalWbNames) {
        try {
          const globals = await getGlobalWbNames();
          if (Array.isArray(globals)) globals.forEach(addBook);
        } catch {}
      }

      // 5. 若均未绑定，自动调用 getOrCreateChatWorldbook('current') 获取或新建当前聊天世界书
      if (candidates.length === 0) {
        const getOrCreateChatWb =
          findMethod(scopes, "getOrCreateChatWorldbook") ||
          findMethod(scopes, "getOrCreateChatLorebook");
        if (getOrCreateChatWb) {
          try {
            addBook(await getOrCreateChatWb("current", "命定论坛动态世界书"));
          } catch {}
        }
      }

      return candidates[0] || "";
    }

    // 严格按照酒馆助手官方文档 (getWorldbook / createWorldbookEntries / updateWorldbookWith)
    // 在当前角色主世界书中创建或更新🔵蓝灯常驻条目
    async function syncForumCluesToBlueLightWorldbook(
      host,
      localWin,
      forumData,
      { enabled = true, scope = "active_only", depth = 1, role = "user" } = {}
    ) {
      const scopes = getScopes(host, localWin);
      const getWorldbookFn = findMethod(scopes, "getWorldbook");
      const updateWorldbookWithFn = findMethod(scopes, "updateWorldbookWith");
      const createWorldbookEntriesFn = findMethod(scopes, "createWorldbookEntries");

      const getLorebookEntriesFn = findMethod(scopes, "getLorebookEntries");
      const updateLorebookEntriesWithFn = findMethod(scopes, "updateLorebookEntriesWith");
      const createLorebookEntriesFn = findMethod(scopes, "createLorebookEntries");

      const targetBook = await resolveTargetWorldbookName(host, localWin);
      if (!targetBook) {
        lastSyncedWorldbookStatus = {
          ok: false,
          bookName: "",
          action: "未检测到当前角色或聊天绑定的世界书",
          error: "未找到绑定的世界书",
        };
        return lastSyncedWorldbookStatus;
      }

      const promptText = enabled ? buildWorldbookClueContent(forumData, { scope }) : "";
      const shouldEnable = Boolean(enabled && promptText);
      const numDepth = Number.isFinite(Number(depth)) ? Math.max(0, Math.round(Number(depth))) : 1;
      const normRole = ["system", "user", "assistant"].includes(String(role).toLowerCase())
        ? String(role).toLowerCase()
        : "user";

      const isOurEntry = (e) =>
        Boolean(
          e &&
            (e.name === WORLDBOOK_ENTRY_NAME ||
              e.comment === WORLDBOOK_ENTRY_NAME ||
              String(e.name || "").includes("【命定论坛】已注入行动线索") ||
              String(e.comment || "").includes("【命定论坛】已注入行动线索") ||
              String(e.content || "").includes("<forum_data_variables"))
        );

      // ─── 1. 优先使用酒馆助手现代官方 Worldbook API (getWorldbook / updateWorldbookWith / createWorldbookEntries) ───
      if (getWorldbookFn && (updateWorldbookWithFn || createWorldbookEntriesFn)) {
        try {
          const entries = await getWorldbookFn(targetBook);
          const hasExisting = Array.isArray(entries) && entries.some(isOurEntry);

          const modernEntryProps = {
            name: WORLDBOOK_ENTRY_NAME,
            enabled: shouldEnable,
            strategy: {
              type: "constant",
              keys: ["命定论坛行动线索"],
              keys_secondary: { logic: "and_any", keys: [] },
              scan_depth: "same_as_global",
            },
            position: {
              type: "at_depth",
              role: normRole,
              depth: numDepth,
              order: 95,
            },
            content: promptText || "",
            probability: 100,
            recursion: {
              prevent_incoming: true,
              prevent_outgoing: true,
              delay_until: null,
            },
            effect: {
              sticky: null,
              cooldown: null,
              delay: null,
            },
          };

          if (hasExisting && updateWorldbookWithFn) {
            await updateWorldbookWithFn(
              targetBook,
              (wbList) =>
                wbList.map((entry) =>
                  isOurEntry(entry)
                    ? {
                        ...entry,
                        ...modernEntryProps,
                      }
                    : entry
                ),
              { render: "immediate" }
            );
            lastSyncedWorldbookStatus = {
              ok: true,
              bookName: targetBook,
              action: shouldEnable ? "已更新蓝灯世界书条目" : "已清空并关闭蓝灯世界书条目",
              error: "",
            };
            return lastSyncedWorldbookStatus;
          } else if (shouldEnable && createWorldbookEntriesFn) {
            await createWorldbookEntriesFn(targetBook, [modernEntryProps], {
              render: "immediate",
            });
            lastSyncedWorldbookStatus = {
              ok: true,
              bookName: targetBook,
              action: "已在世界书中新建🔵蓝灯常驻条目",
              error: "",
            };
            return lastSyncedWorldbookStatus;
          } else if (!shouldEnable && !hasExisting) {
            lastSyncedWorldbookStatus = {
              ok: true,
              bookName: targetBook,
              action: "世界书无残留条目",
              error: "",
            };
            return lastSyncedWorldbookStatus;
          }
        } catch (modernErr) {
          console.warn("[命定论坛] 现代 Worldbook API 调用异常，尝试旧版兼容接口:", modernErr);
        }
      }

      // ─── 2. 备选旧版 Lorebook 兼容 API ───
      if (getLorebookEntriesFn) {
        try {
          const rawList = await getLorebookEntriesFn(targetBook);
          const entries = Array.isArray(rawList)
            ? rawList
            : isObj(rawList?.entries)
            ? Object.values(rawList.entries)
            : [];
          const existing = entries.find(isOurEntry);
          const legacyPos =
            normRole === "system"
              ? "at_depth_as_system"
              : normRole === "assistant"
              ? "at_depth_as_assistant"
              : "at_depth_as_user";

          const legacyEntryProps = {
            comment: WORLDBOOK_ENTRY_NAME,
            enabled: shouldEnable,
            type: "constant",
            keys: ["命定论坛行动线索"],
            position: legacyPos,
            depth: numDepth,
            order: 95,
            content: promptText || "",
            probability: 100,
            prevent_recursion: true,
            exclude_recursion: true,
          };

          if (existing && updateLorebookEntriesWithFn) {
            await updateLorebookEntriesWithFn(targetBook, (list) =>
              list.map((e) => (isOurEntry(e) ? { ...e, ...legacyEntryProps } : e))
            );
            lastSyncedWorldbookStatus = {
              ok: true,
              bookName: targetBook,
              action: shouldEnable ? "已更新蓝灯世界书条目" : "已关闭蓝灯世界书条目",
              error: "",
            };
            return lastSyncedWorldbookStatus;
          } else if (!existing && shouldEnable && createLorebookEntriesFn) {
            await createLorebookEntriesFn(targetBook, [legacyEntryProps]);
            lastSyncedWorldbookStatus = {
              ok: true,
              bookName: targetBook,
              action: "已新建🔵蓝灯世界书条目",
              error: "",
            };
            return lastSyncedWorldbookStatus;
          }
        } catch (legacyErr) {
          lastSyncedWorldbookStatus = {
            ok: false,
            bookName: targetBook,
            action: "写入世界书失败",
            error: String(legacyErr?.message || legacyErr),
          };
          return lastSyncedWorldbookStatus;
        }
      }

      lastSyncedWorldbookStatus = {
        ok: false,
        bookName: targetBook,
        action: "未检测到世界书写入 API",
        error: "请确认酒馆助手版本支持 createWorldbookEntries",
      };
      return lastSyncedWorldbookStatus;
    }

    // 读取当前已保存的论坛行动线索列表（优先从当前聊天 chatMetadata 或本地存储读取，不再读取/依赖无用的 stat_data 变量）
    async function readForumVariableTree(host, localWin) {
      const stCtx = ForumMacroEngine.getStContext(host, localWin);
      let forumData = null;

      // 1. 优先从当前聊天的 chatMetadata.variables.forum_data 读取（随不同聊天存档独立保存）
      if (isObj(stCtx?.chatMetadata?.variables?.forum_data)) {
        forumData = deepClone(stCtx.chatMetadata.variables.forum_data);
      }

      // 2. 回退从 localStorage 读取
      if (!forumData) {
        try {
          const raw = host?.localStorage?.getItem(LOCAL_FORUM_CLUES_KEY);
          if (raw) {
            forumData = JSON.parse(raw);
          }
        } catch {}
      }

      // 3. 若依然为空，尝试从当前绑定世界书中的「📌【命定论坛】已注入行动线索」条目反向恢复
      if (!forumData) {
        try {
          const scopes = getScopes(host, localWin);
          const getWorldbookFn = findMethod(scopes, "getWorldbook");
          const targetBook = await resolveTargetWorldbookName(host, localWin);
          if (getWorldbookFn && targetBook) {
            const entries = await getWorldbookFn(targetBook);
            const found = Array.isArray(entries)
              ? entries.find((e) => String(e?.content || "").includes("<forum_data_variables"))
              : null;
            if (found?.content) {
              const jsonMatch = found.content.match(/\{[\s\S]*\}/);
              if (jsonMatch) {
                forumData = JSON.parse(jsonMatch[0]);
              }
            }
          }
        } catch {}
      }

      return {
        forumData: normalizeForumDataTree(forumData),
      };
    }

    // 保存论坛线索并直接同步至当前角色主世界书的🔵蓝灯常驻条目（完全不再写入 stat_data / Mvu 消息变量层）
    async function saveForumVariableTree(host, localWin, nextTree) {
      const stCtx = ForumMacroEngine.getStContext(host, localWin);
      const normalizedTree = normalizeForumDataTree(nextTree);
      normalizedTree._meta.updatedAt = new Date().toLocaleString("zh-CN", { hour12: false });

      // 1. 存入 localStorage 与 chatMetadata（仅用于面板自身持久化展示，不碰主聊天楼层变量）
      try {
        host?.localStorage?.setItem(LOCAL_FORUM_CLUES_KEY, JSON.stringify(normalizedTree));
      } catch {}
      if (stCtx?.chatMetadata) {
        try {
          stCtx.chatMetadata.variables = stCtx.chatMetadata.variables || {};
          stCtx.chatMetadata.variables.forum_data = deepClone(normalizedTree);
          stCtx.saveMetadata?.();
        } catch {}
      }

      // 2. 直接同步至角色主世界书的🔵蓝灯常驻条目
      const wbRes = await syncForumCluesToBlueLightWorldbook(host, localWin, normalizedTree, {
        enabled: typeof settings !== "undefined" ? settings.forumVarInjectToMainPrompt !== false : true,
        scope: typeof settings !== "undefined" ? settings.forumVarPromptScope || "active_only" : "active_only",
        depth: typeof settings !== "undefined" ? settings.forumVarPromptDepth ?? 1 : 1,
        role: typeof settings !== "undefined" ? settings.forumVarPromptRole || "user" : "user",
      });

      return {
        ok: Boolean(wbRes.ok),
        syncedBookName: wbRes.bookName || "",
        wbAction: wbRes.action || "",
        wbError: wbRes.error || "",
        forumData: normalizedTree,
      };
    }

    // 将单条帖子写入🔵蓝灯世界书条目
    async function injectPostToForumTree(
      host,
      localWin,
      {
        postData,
        editedFullText = "",
        mode = "append",
      }
    ) {
      const { forumData } = await readForumVariableTree(host, localWin);
      const clueEntry = buildClueEntryObject(postData, editedFullText);

      const prevList = Array.isArray(forumData.已注入帖子列表)
        ? forumData.已注入帖子列表.filter(
            (item) =>
              isObj(item) &&
              item.标题 !== clueEntry.标题 &&
              item.帖子ID !== clueEntry.帖子ID
          )
        : [];

      const nextList =
        mode === "overwrite" ? [clueEntry] : [clueEntry, ...prevList].slice(0, 15);

      const nextTree = {
        ...forumData,
        当前行动线索: clueEntry,
        已注入帖子列表: nextList,
      };

      const res = await saveForumVariableTree(host, localWin, nextTree);

      return {
        ...res,
        clueEntry,
        msg: res.ok
          ? `✅ 已将《${postData.title}》设为当前行动线索并写入线索世界书「${res.syncedBookName}」`
          : `⚠️ 线索世界书写入未成功：${res.wbAction || res.wbError || "请检查当前角色是否绑定了世界书"}`,
      };
    }

    return {
      createDefaultForumDataTree,
      normalizeForumDataTree,
      formatCluePreviewText,
      extractPostStructuredData,
      buildClueEntryObject,
      buildWorldbookClueContent,
      readForumVariableTree,
      saveForumVariableTree,
      injectPostToForumTree,
      syncForumCluesToBlueLightWorldbook,
      getLastWorldbookSyncStatus: () => lastSyncedWorldbookStatus,
    };
  })();

