  /* ============================================================================
   * 12. 主应用挂载与交互逻辑
   * ============================================================================ */
  const host = window.parent || window;
  const doc = host.document;
  const instanceKey = "__DLC_DESTINED_FORUM_V1__";
  const rootId = "dlc-destined-forum";

  disposePreviousForumUi(host, doc, instanceKey, rootId);

  const STORAGE_KEY_SETTINGS = "dlc_destined_forum_settings_v1";
  const STORAGE_KEY_ARCHIVES = "dlc_destined_forum_archives_v1";
  const STORAGE_KEY_FAVORITES = "dlc_destined_forum_favorites_v1";
  const MAX_OUTPUT_TOKENS_LIMIT = 60000;

  const DEFAULT_SETTINGS = {
    forumMode: "surface",
    targetBoard: "all",
    allowUserPosts: false,
    showAdminIdentity: true,
    userAliases: ["匿名星轨旅人", "雾晶港摸鱼学徒", "深渊观测者"],
    activeUserAlias: "匿名星轨旅人",
    forumVarInjectMode: "append",
    forumVarInjectToMainPrompt: true,
    forumVarPromptScope: "active_only",
    forumVarPromptDepth: 1,
    forumVarPromptRole: "user",
    enableImageGenMode: true,
    hideImgThinkRegex: true,
    includeNsfwGuideInSurface: true,
    imageGenDefaultGender: "女性",
    apiMode: "custom",
    apiSource: "openai",
    apiUrl: "https://api.openai.com/v1",
    apiKey: "",
    apiModel: "",
    modelList: [],
    temperature: 0.95,
    maxTokens: 20000,
    stream: true,
    contextTurns: 2,
    includeLorebook: true,
    affectedBooks: [],
    lorebookScanDepth: 2,
    lorebookRecursionSteps: 0,
    lorebookMaxChars: 2000000,
    taskContextConfig: JSON.parse(JSON.stringify(defaultTaskContextConfig)),
    promptSlots: JSON.parse(JSON.stringify(defaultPromptSlotsConfig)),
    promptAutoSegmentInsertedOverrides: {},
    enableHeaderGibberish: false,
    tailOutputMode: "normal",
    finalInjectTemplate: DEFAULT_FINAL_INJECT_TEMPLATE,
    userInputEndInject: DEFAULT_ARMOR_PIERCING_PROMPT,
    toolOutputEndInject: DEFAULT_TOOL_ONCE_PROMPT,
    mobileTopOffset: 54,
    autoGenerateEveryN: 0,
    customSystemPrompt: "",
    apiPresets: [],
    _scanDefaultsV2: true,
    _armorPromptV162_v4: true,
    _armorPromptV166_fullPresetArchitecture: true,
    _maxTokensV168: true,
    _contextTurnsV169: true,
    _imageCleanV170: true,
    _clueDefaultsV180: true,
  };

  function loadSettings() {
    try {
      const raw = host.localStorage.getItem(STORAGE_KEY_SETTINGS);
      if (raw) {
        const parsed = JSON.parse(raw);
        const migrated = !parsed._scanDefaultsV2;
        const migratedArmor = !parsed._armorPromptV166_fullPresetArchitecture;
        const migratedMaxTokens = !parsed._maxTokensV168;
        const rawMaxTokens = migratedMaxTokens
          ? !parsed.maxTokens || Number(parsed.maxTokens) === 16000
            ? 20000
            : Number(parsed.maxTokens)
          : Number(parsed.maxTokens) || 20000;
        const resolvedMaxTokens = Math.min(MAX_OUTPUT_TOKENS_LIMIT, Math.max(256, rawMaxTokens));
        const migratedContextTurns = !parsed._contextTurnsV169;
        const resolvedContextTurns = migratedContextTurns
          ? !parsed.contextTurns || Number(parsed.contextTurns) === 6
            ? 2
            : Number(parsed.contextTurns)
          : Math.max(1, Number(parsed.contextTurns) || 2);
        const resolvedUserAliases =
          Array.isArray(parsed.userAliases) && parsed.userAliases.length > 0
            ? parsed.userAliases
            : [...DEFAULT_SETTINGS.userAliases];
        const resolvedScanDepth = migrated
          ? !parsed.lorebookScanDepth || Number(parsed.lorebookScanDepth) === 8
            ? 2
            : Number(parsed.lorebookScanDepth)
          : Number.isFinite(Number(parsed.lorebookScanDepth))
          ? Math.max(1, Number(parsed.lorebookScanDepth))
          : 2;
        const resolvedRecursionSteps = migrated
          ? parsed.lorebookRecursionSteps === undefined || Number(parsed.lorebookRecursionSteps) === 3
            ? 0
            : Number(parsed.lorebookRecursionSteps)
          : Number.isFinite(Number(parsed.lorebookRecursionSteps))
          ? Math.max(0, Number(parsed.lorebookRecursionSteps))
          : 0;
        const resolvedStream = migrated || migratedArmor
          ? true
          : parsed.stream !== undefined
          ? Boolean(parsed.stream)
          : true;

        let resolvedPromptSlots =
          Array.isArray(parsed.promptSlots) && parsed.promptSlots.length
            ? parsed.promptSlots
            : JSON.parse(JSON.stringify(defaultPromptSlotsConfig));

        if (migratedArmor) {
          resolvedPromptSlots = JSON.parse(JSON.stringify(defaultPromptSlotsConfig));
        }

        const resolvedUserInputEndInject = migratedArmor
          ? DEFAULT_ARMOR_PIERCING_PROMPT
          : parsed.userInputEndInject || DEFAULT_ARMOR_PIERCING_PROMPT;

        const resolvedFinalInjectTemplate = migratedArmor
          ? DEFAULT_FINAL_INJECT_TEMPLATE
          : parsed.finalInjectTemplate || DEFAULT_FINAL_INJECT_TEMPLATE;

        const resolvedOverrides = migratedArmor
          ? {}
          : parsed.promptAutoSegmentInsertedOverrides || {};

        const migratedClueDefaults = !parsed._clueDefaultsV180;
        const resolvedPromptScope = migratedClueDefaults
          ? "active_only"
          : parsed.forumVarPromptScope || "active_only";
        const resolvedPromptRole = migratedClueDefaults
          ? "user"
          : parsed.forumVarPromptRole || "user";

        const finalSettings = {
          ...DEFAULT_SETTINGS,
          ...parsed,
          forumVarPromptScope: resolvedPromptScope,
          forumVarPromptRole: resolvedPromptRole,
          stream: resolvedStream,
          lorebookScanDepth: resolvedScanDepth,
          lorebookRecursionSteps: resolvedRecursionSteps,
          taskContextConfig:
            migratedArmor || !parsed._imageCleanV170
              ? JSON.parse(JSON.stringify(defaultTaskContextConfig))
              : parsed.taskContextConfig || JSON.parse(JSON.stringify(defaultTaskContextConfig)),
          promptSlots: resolvedPromptSlots,
          promptAutoSegmentInsertedOverrides: resolvedOverrides,
          enableHeaderGibberish: Boolean(parsed.enableHeaderGibberish),
          tailOutputMode: parsed.tailOutputMode === "tool_once" ? "tool_once" : "normal",
          userInputEndInject: resolvedUserInputEndInject,
          toolOutputEndInject:
            !parsed._toolPromptV181 || !parsed.toolOutputEndInject
              ? DEFAULT_TOOL_ONCE_PROMPT
              : parsed.toolOutputEndInject,
          _toolPromptV181: true,
          finalInjectTemplate: resolvedFinalInjectTemplate,
          lorebookMaxChars:
            !parsed.lorebookMaxChars || Number(parsed.lorebookMaxChars) === 28000
              ? 2000000
              : Number(parsed.lorebookMaxChars),
          maxTokens: resolvedMaxTokens,
          contextTurns: resolvedContextTurns,
          userAliases: resolvedUserAliases,
          activeUserAlias: parsed.activeUserAlias || resolvedUserAliases[0] || "匿名星轨旅人",
          mobileTopOffset:
            parsed.mobileTopOffset !== undefined ? Number(parsed.mobileTopOffset) : 54,
          _scanDefaultsV2: true,
          _armorPromptV162_v4: true,
          _armorPromptV166_fullPresetArchitecture: true,
          _maxTokensV168: true,
          _contextTurnsV169: true,
          _imageCleanV170: true,
          _clueDefaultsV180: true,
        };
        if (migrated || migratedArmor || migratedMaxTokens || migratedContextTurns || !parsed._imageCleanV170 || migratedClueDefaults) {
          try {
            host.localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(finalSettings));
          } catch {}
        }
        return finalSettings;
      }
    } catch {}
    return { ...DEFAULT_SETTINGS };
  }

  function saveSettings() {
    try {
      host.localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(settings));
    } catch {}
  }

  function loadArchives() {
    try {
      const raw = host.localStorage.getItem(STORAGE_KEY_ARCHIVES);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {}
    return [];
  }

  function saveArchives() {
    if (archives.length > 25) archives = archives.slice(0, 25);
    while (archives.length > 0) {
      try {
        host.localStorage.setItem(STORAGE_KEY_ARCHIVES, JSON.stringify(archives));
        return;
      } catch (e) {
        if (archives.length <= 1) break;
        archives.pop();
      }
    }
  }

  function loadFavorites() {
    try {
      const raw = host.localStorage.getItem(STORAGE_KEY_FAVORITES);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {}
    return [];
  }

  function saveFavorites() {
    try {
      host.localStorage.setItem(STORAGE_KEY_FAVORITES, JSON.stringify(favorites));
    } catch (e) {
      console.warn("[命定论坛] 保存单帖收藏夹异常:", e);
    }
  }

  let settings = loadSettings();
  let archives = loadArchives();
  let favorites = loadFavorites();
  let activeFavBoardFilter = "ALL";
  let favSearchQuery = "";

  function findFavoriteEntryIndex(postId, titleText) {
    const normTitle = normalizeTitleForMatch(titleText || "");
    return favorites.findIndex((item) => {
      if (!item) return false;
      const itemNormTitle = normalizeTitleForMatch(item.title || "");
      if (normTitle && itemNormTitle && normTitle === itemNormTitle) return true;
      return Boolean(postId && item.postId === postId && (!normTitle || !itemNormTitle));
    });
  }

  // 构建玩家自定义马甲快速切换与保存栏
  function createAliasSelectorBar(targetInputEl) {
    const bar = make("div", "alias-bar");
    const paintBar = () => {
      bar.replaceChildren();
      const labelSpan = make("span", "wf-param-hint", "🎭 常用马甲：");
      bar.append(labelSpan);

      const list = Array.isArray(settings.userAliases) ? settings.userAliases : [];
      if (targetInputEl && !targetInputEl.value.trim() && settings.activeUserAlias) {
        targetInputEl.value = settings.activeUserAlias;
      }

      list.forEach((aliasName, idx) => {
        const isCurrent = targetInputEl && targetInputEl.value.trim() === aliasName;
        const chip = make("span", "alias-chip" + (isCurrent ? " active" : ""));
        const txt = make("span", "", aliasName);
        chip.append(txt);

        chip.addEventListener("click", () => {
          if (targetInputEl) {
            targetInputEl.value = aliasName;
          }
          settings.activeUserAlias = aliasName;
          saveSettings();
          paintBar();
          setStatus(`🎭 已切换当前发言马甲为「${aliasName}」`);
        });

        if (list.length > 1) {
          const delBtn = make("button", "alias-chip-del", "×");
          delBtn.type = "button";
          delBtn.title = `删除马甲「${aliasName}」`;
          delBtn.addEventListener("click", (ev) => {
            ev.stopPropagation();
            settings.userAliases.splice(idx, 1);
            if (settings.activeUserAlias === aliasName) {
              settings.activeUserAlias = settings.userAliases[0] || "匿名星轨旅人";
            }
            saveSettings();
            paintBar();
            setStatus(`🗑️ 已删除马甲「${aliasName}」`);
          });
          chip.append(delBtn);
        }
