  function clampPosition() {
    if (disposed) return;
    if (mobileEntry) {
      mobileEntry.layout();
    }
    if (launcher.hidden || mobileEntry?.isMobile()) return;
    const box = launcher.getBoundingClientRect();
    if (!box.width && !box.height) return;
    const r = root.getBoundingClientRect();
    const isNarrowScreen = (host.innerWidth || 375) <= 820;
    const minTop = isNarrowScreen ? Math.max(48, Number(settings.mobileTopOffset) || 54) : 8;
    const dx =
      box.left < 8
        ? 8 - box.left
        : box.right > host.innerWidth - 8
        ? host.innerWidth - 8 - box.right
        : 0;
    const dy =
      box.top < minTop
        ? minTop - box.top
        : box.bottom > host.innerHeight - 8
        ? host.innerHeight - 8 - box.bottom
        : 0;
    if (dx || dy) {
      root.style.left = r.left + dx + "px";
      root.style.top = r.top + dy + "px";
      root.style.right = "auto";
      root.style.bottom = "auto";
    }
  }

  function startDrag(event) {
    if (mobileEntry?.isMobile() || event.button !== 0) return;
    stopDrag?.();
    const target = event.currentTarget;
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startY = event.clientY;
    const box = root.getBoundingClientRect();
    let moved = false;
    try {
      target.setPointerCapture(pointerId);
    } catch {}

    const onMove = (e) => {
      if (e.pointerId !== pointerId) return;
      if (!moved && Math.hypot(e.clientX - startX, e.clientY - startY) < 6) return;
      moved = true;
      ignoreClickUntil = Date.now() + 250;
      root.style.left = box.left + e.clientX - startX + "px";
      root.style.top = box.top + e.clientY - startY + "px";
      root.style.right = "auto";
      root.style.bottom = "auto";
      clampPosition();
    };

    const onEnd = (e) => {
      if (e && e.pointerId !== pointerId) return;
      host.removeEventListener("pointermove", onMove);
      host.removeEventListener("pointerup", onEnd);
      host.removeEventListener("pointercancel", onEnd);
      try {
        if (target.hasPointerCapture(pointerId)) target.releasePointerCapture(pointerId);
      } catch {}
      stopDrag = null;
    };

    host.addEventListener("pointermove", onMove);
    host.addEventListener("pointerup", onEnd);
    host.addEventListener("pointercancel", onEnd);
    stopDrag = onEnd;
  }

  launcher.addEventListener("pointerdown", startDrag);
  launcher.addEventListener("click", () => {
