  // 提取流式阶段正在输出的 <recorder_thinking> / <think> 公开裁决内容供界面实时流式展示
  function extractStreamingThinkingPreview(rawText) {
    let text = String(rawText || "").trim();
    if (!text) return "";
    text = text
      .replace(/^```(?:html|xml)?\s*/i, "")
      .replace(/^\s*(?:<\/(?:think|thinking|recorder_thinking)>\s*)+/gi, "")
      .replace(/^\s*<recorder_output\b[^>]*>\s*/i, "");

    const openMatch = text.match(/<(?:recorder_thinking|thinking|think)\b[^>]*>([\s\S]*)$/i);
    if (openMatch) {
      const inner = openMatch[1];
      const closeIdx = inner.search(/<\/(?:recorder_thinking|thinking|think)>|<recorder_body\b|<tp\b|<gametxt\b|<div\s+class=["'](?:ast-net|ast-dark)["']/i);
      return (closeIdx >= 0 ? inner.slice(0, closeIdx) : inner).trim();
    }
    // 兼容无头思维块（预填充了 <recorder_thinking> 后模型直接输出 Step 1... 直到 </recorder_thinking>）
    if (!/<(?:recorder_body|gametxt|div|article)\b/i.test(text)) {
      const closeIdx = text.search(/<\/(?:recorder_thinking|thinking|think)>/i);
      return (closeIdx >= 0 ? text.slice(0, closeIdx) : text).trim();
    }
    return "";
  }

  const GATEWAY_REFUSAL_PATTERNS = [
    /The prompt could not be submitted[\s\S]*$/i,
    /The prompt contains sensitive words that violate[\s\S]*$/i,
    /I cannot fulfill this request[\s\S]*$/i,
    /I am unable to fulfill this request[\s\S]*$/i,
    /I\u2019m sorry, but I cannot(?: continue| generate| fulfill)[\s\S]*$/i,
    /I\u2019m unable to (?:continue|generate|fulfill)[\s\S]*$/i,
    /I apologize, but I cannot(?: continue| generate| fulfill)[\s\S]*$/i,
    /violates Google\u2019s \[?Generative AI Prohibited Use policy[\s\S]*$/i,
  ];

  function stripGatewayRefusalPoison(input) {
    let s = String(input == null ? "" : input);
    if (!s) return "";
    for (const re of GATEWAY_REFUSAL_PATTERNS) {
      s = s.replace(re, "");
    }
    return s;
  }

  function isFullyRefusedReply(rawText) {
    const s = String(rawText == null ? "" : rawText).trim();
    if (!s) return false;
    const hitRefusal = GATEWAY_REFUSAL_PATTERNS.some((re) => new RegExp(re.source, "i").test(s));
    if (!hitRefusal) return false;
    const leftPlain = stripGatewayRefusalPoison(s).replace(/<[^<>]*>/g, "").trim();
    return leftPlain.length < 60;
  }

  function cleanModelHtmlOutput(rawText) {
    let text = stripGatewayRefusalPoison(String(rawText || "")).trim();
    text = text
      .replace(/^```(?:html|xml)?\s*/i, "")
      .replace(/\s*```$/i, "")
      // 1. 剔除模型开篇可能先输出的孤立闭合标签 </think> / </thinking>（参考《命定·黄昏 Prime-1.11》思维链美化）
      .replace(/^\s*(?:<\/(?:think|thinking)>\s*)+/gi, "")
      // 2. 剔除已闭合的 <recorder_thinking> / <thinking> / <think> 块
      .replace(/<(?:recorder_thinking|thinking|think)\b[^>]*>[\s\S]*?<\/(?:recorder_thinking|thinking|think)>/gi, "")
      // 3. 剔除无头闭合思维块（即模型承接 <recorder_thinking> 直接输出内容直至 </recorder_thinking>）
      .replace(/^(?:\s*<recorder_output\b[^>]*>)?[\s\S]*?<\/(?:recorder_thinking|thinking|think)>\s*/i, "")
      // 4. 若模型漏写 </recorder_thinking> 直接进入 <recorder_body>/<tp>/<gametxt>/<div class="ast-...">，仅剥离正文起点前的思维块
      .replace(/<(?:recorder_thinking|thinking|think)\b[^>]*>[\s\S]*?(?=<recorder_body\b|<tp\b|<gametxt\b|<div\s+class=["'](?:ast-net|ast-dark)["']|<article\s+class=["']ast-post["'])/gi, "")
      // 5. 流式阶段尚未进入正文且尚未闭合的思维链暂不混入正式 HTML（由流式裁决预览框实时展示）
      .replace(/<(?:recorder_thinking|thinking|think)\b[^>]*>(?:(?!<recorder_body\b|<tp\b|<gametxt\b|<div\s+class=["'](?:ast-net|ast-dark)["']|<article\s+class=["']ast-post["'])[\s\S])*$/gi, "")
      // 6. 剔除 <tp>...</tp> 与 <recorder_after_format>...</recorder_after_format> 及 <recorder_done/>
      .replace(/<tp\b[^>]*>[\s\S]*?<\/tp>/gi, "")
      .replace(/<tp\b[^>]*>(?:(?!<gametxt|<div\s+class=["'](?:ast-net|ast-dark)|<article)[\s\S])*$/gi, "")
      .replace(/<appendix\b[^>]*>[\s\S]*?<\/appendix>/gi, "")
      .replace(/<appendix\b[^>]*>[\s\S]*$/gi, "")
      .replace(/<Disclaimer\b[^>]*>[\s\S]*?<\/Disclaimer>/gi, "")
      .replace(/<recorder_after_format\b[^>]*>[\s\S]*?<\/recorder_after_format>/gi, "")
      .replace(/<recorder_after_format\b[^>]*>[\s\S]*$/gi, "")
      .replace(/<recorder_done\b[^>]*\/?>/gi, "")
      // 7. 剥离外层协议容器标签 <recorder_output>、<recorder_body>、<gametxt>，保留内部论坛 HTML
      .replace(/<\/?(?:recorder_output|recorder_body|gametxt)\b[^>]*>/gi, "");
    // 执行《regex-隐藏imgthink.json》正则：/<imgthink>([\s\S]*?)<\/imgthink>/g -> ""
    if (settings.hideImgThinkRegex !== false) {
      text = text
        .replace(REGEX_HIDE_IMGTHINK, "")
        .replace(REGEX_HIDE_IMGTHINK_STREAMING, "");
    }
    // 注意：HTML5 解析器会将 <image> 当作 <img> 空标签解析，导致内部的 image###...### 变成裸文本节点显示在魔导留影石画面中！
    // 因此在进入 innerHTML 解析前，统一将 <image>...</image>（含漏写 </image> 但遇到 </div> 或后续模块边界的情况）转换为隐藏的 <span class="ast-hidden-image-tag" hidden>
    text = text
      .replace(
        /<image\b[^>]*>([\s\S]*?)(?:<\/image>|(?=<\/div>|<div\s+class=["']ast-(?:stats|replies|post)|<article\b))/gi,
        (_, inner) => {
          return `<span class="ast-hidden-image-tag" hidden style="display:none !important;">${inner.trim()}</span>`;
        }
      )
      // 若模型漏写 <image> 外壳而直接输出了闭合的 image###...###，同样转为隐藏节点，防止裸露在正文中
      .replace(
        /(?<!class="ast-hidden-image-tag" hidden style="display:none !important;">)image###([\s\S]*?)###/gi,
        (_, innerPrompt) => {
          return `<span class="ast-hidden-image-tag" hidden style="display:none !important;">image###${innerPrompt.trim()}###</span>`;
        }
      )
      // 流式输出时仅隐藏最末尾尚未闭合且未跨过 </div>/<div/<article 边界的 <image>... 或 image###... 尾部，严禁跨节点误吞 .ast-replies 楼层
      .replace(/<image\b[^>]*>(?:(?!<\/div>|<div\b|<article\b)[\s\S])*$/gi, "")
      .replace(/image###(?:(?!###|<\/div>|<div\b|<article\b)[\s\S])*$/gi, "");
    return text.trim();
  }

