  }

  function extractReplyPureText(replyEl) {
    if (!replyEl) return "";
    const textNode = replyEl.querySelector(".ast-reply-text");
    if (textNode) {
      return textNode.textContent
        .replace(/\s+/g, " ")
        .replace(/^[「『"']+|[」』"']+$/g, "")
        .trim();
    }
    const clone = replyEl.cloneNode(true);
    for (const meta of clone.querySelectorAll(".ast-reply-meta, .ast-floor, .ast-author, .ast-admin")) {
      meta.remove();
    }
    return clone.textContent
      .replace(/\s+/g, " ")
      .replace(/^[「『"']+|[」』"']+$/g, "")
      .trim();
  }

