  function assignDeterministicPostAttributes(posts) {
    const seenIds = new Set();
    posts.forEach((postEl, idx) => {
      const badgeEl = postEl.querySelector(".ast-board-badge");
      const boardName = normalizeBoardLabel(
        postEl.getAttribute("data-board") || (badgeEl ? badgeEl.textContent : "")
      );
      let postId = (postEl.getAttribute("data-post-id") || "").trim();
      if (!postId || seenIds.has(postId)) {
        postId = `post-${idx + 1}`;
      }
      seenIds.add(postId);
      postEl.classList.add("ast-post");
      postEl.setAttribute("data-board", boardName);
      postEl.setAttribute("data-post-id", postId);
    });
