  function findTargetPostInList(posts, replyTargetData) {
    if (!Array.isArray(posts) || !posts.length) return null;
    const targetPostId = String(replyTargetData?.postId || "").trim();
    const targetTitleNorm = normalizeTitleForMatch(replyTargetData?.title || "");
    const idx = typeof replyTargetData?.postIndex === "number" ? replyTargetData.postIndex : -1;

    // 1. 优先检查点击时对应的 postIndex（若 ID 或标题吻合则 100% 命中，彻底避免多帖同名 ID 误匹配到第 1 帖）
    if (idx >= 0 && idx < posts.length) {
      const candidate = posts[idx];
      const candId = candidate.getAttribute("data-post-id") || "";
      const candTitleNorm = normalizeTitleForMatch(
        candidate.querySelector(".ast-post-title, h3, h2")?.textContent || ""
      );
      if (
        (targetPostId && candId === targetPostId) ||
        (targetTitleNorm && candTitleNorm && candTitleNorm === targetTitleNorm)
      ) {
        return candidate;
      }
    }
    // 2. 按唯一 data-post-id 匹配
    if (targetPostId) {
      const byId = posts.find((p) => p.getAttribute("data-post-id") === targetPostId);
      if (byId) return byId;
    }
    // 3. 按规范化标题匹配（兼容模型微调括号或空格）
    if (targetTitleNorm) {
      const byTitle = posts.find((p) => {
        const t = normalizeTitleForMatch(
          p.querySelector(".ast-post-title, h3, h2")?.textContent || ""
        );
        return t && (t === targetTitleNorm || t.includes(targetTitleNorm) || targetTitleNorm.includes(t));
      });
      if (byTitle) return byTitle;
    }
    // 4. 兜底按 postIndex 返回
    if (idx >= 0 && idx < posts.length) {
      return posts[idx];
    }
    return posts.length === 1 ? posts[0] : null;
  }

  function mergeReplyEvolutionHtml(
    baseForumHtml,
    rawModelHtml,
    replyTargetData,
    forumMode = "surface",
    isStreaming = false
  ) {
    const cleanedModel = cleanModelHtmlOutput(rawModelHtml);
    const thinkingPreview = isStreaming ? extractStreamingThinkingPreview(rawModelHtml) : "";
    const rootClass = forumMode === "dark" ? "ast-dark" : "ast-net";
    const targetBoard = normalizeBoardLabel(replyTargetData?.board || "综合");
    const targetPostId = replyTargetData?.postId || "post-1";
    const userReplyClean = String(replyTargetData?.userReply || "")
      .replace(/\s+/g, " ")
      .replace(/^[「『"']+|[」』"']+$/g, "")
      .trim();

    let baseWrap = null;
    let basePosts = [];
    let targetInBase = null;
    if (baseForumHtml) {
      baseWrap = doc.createElement("div");
      baseWrap.innerHTML = baseForumHtml;
      stripInjectedPostControls(baseWrap);
      basePosts = queryTopLevelPosts(baseWrap);
      assignDeterministicPostAttributes(basePosts);
      targetInBase = findTargetPostInList(basePosts, replyTargetData);
    }

    let origPostEl = null;
    if (targetInBase) {
      origPostEl = targetInBase.cloneNode(true);
    } else if (replyTargetData?.htmlContent) {
      const origWrap = doc.createElement("div");
      origWrap.innerHTML = replyTargetData.htmlContent;
      stripInjectedPostControls(origWrap);
      origPostEl = queryTopLevelPosts(origWrap)[0] || origWrap.firstElementChild;
    }

    if (!origPostEl) {
      return cleanedModel || baseForumHtml || "";
    }

    // 始终以原帖克隆作为基准，100% 保留原帖标题、正文、魔导留影石描述与生图 Tag，绝不因模型简写而丢失
    const mergedPostEl = origPostEl.cloneNode(true);
    stripInjectedPostControls(mergedPostEl);
    mergedPostEl.classList.add("ast-post");
    mergedPostEl.setAttribute("data-board", targetBoard);
    mergedPostEl.setAttribute("data-post-id", targetPostId);

    // 恢复原帖可能携带的 st-chatu8 画图提示词与隐藏标签
    const savedPrompt =
      replyTargetData?.chatu8Prompt ||
      targetInBase?.querySelector(".ast-img")?.getAttribute("data-chatu8-prompt") ||
      origPostEl?.querySelector(".ast-img")?.getAttribute("data-chatu8-prompt") ||
      "";
    const mergedImgBox = mergedPostEl.querySelector(".ast-img");
    if (mergedImgBox && savedPrompt) {
      mergedImgBox.setAttribute("data-chatu8-prompt", savedPrompt);
      if (!mergedImgBox.querySelector(".ast-hidden-image-tag")) {
        const hiddenSpan = doc.createElement("span");
        hiddenSpan.className = "ast-hidden-image-tag";
        hiddenSpan.hidden = true;
        hiddenSpan.style.cssText = "display:none !important;";
        hiddenSpan.textContent = `image###${savedPrompt}###`;
        mergedImgBox.append(hiddenSpan);
      }
    }

    const origReplies = [...mergedPostEl.querySelectorAll(".ast-replies .ast-reply, .ast-reply")].map(
      (r) => r.cloneNode(true)
    );
    let repliesBox = mergedPostEl.querySelector(".ast-replies");
    if (!repliesBox) {
      repliesBox = doc.createElement("div");
      repliesBox.className = "ast-replies";
      mergedPostEl.append(repliesBox);
    }
    repliesBox.replaceChildren();

    const origFingerprints = new Set();
    let maxFloorNum = 0;
    for (const origR of origReplies) {
      const fp = extractReplyPureText(origR);
      if (fp) {
        origFingerprints.add(fp);
        origFingerprints.add(fp.slice(0, 32));
      }
      const fNum = parseFloorNumber(origR);
      if (Number.isFinite(fNum) && fNum > maxFloorNum) {
        maxFloorNum = fNum;
      }
      repliesBox.append(origR);
    }
    if (maxFloorNum < origReplies.length) {
      maxFloorNum = origReplies.length;
    }

    // 解析模型输出的演化楼层
    const modelNewReplies = [];
    let modelUpdatedStats = null;
    if (cleanedModel) {
      const tempRoot = doc.createElement("div");
      tempRoot.innerHTML = cleanedModel;
      stripInjectedPostControls(tempRoot);

      const modelPosts = queryTopLevelPosts(tempRoot);
      const matchedModelPost =
        findTargetPostInList(modelPosts, replyTargetData) || modelPosts[0] || null;
      const searchScope = matchedModelPost || tempRoot;

      if (matchedModelPost) {
        modelUpdatedStats = matchedModelPost.querySelector(".ast-stats");
      }

      const rawReplies = [...searchScope.querySelectorAll(".ast-reply")];
      const seenNewFp = new Set();
      for (const r of rawReplies) {
        const pure = extractReplyPureText(r);
        if (!pure) continue;
        const shortFp = pure.slice(0, 32);
        // 过滤掉与原帖既有楼层重复的回复
        if (origFingerprints.has(pure) || (shortFp.length >= 10 && origFingerprints.has(shortFp))) {
          continue;
        }
        if (seenNewFp.has(pure)) continue;
        seenNewFp.add(pure);
        modelNewReplies.push(r.cloneNode(true));
      }
    }

    if (modelUpdatedStats && mergedPostEl.querySelector(".ast-stats")) {
      mergedPostEl.querySelector(".ast-stats").replaceWith(modelUpdatedStats.cloneNode(true));
    }

    // 检查模型的增量回复中是否已包含玩家本次的回复；若未包含（或流式尚未生成到），自动在原楼层之后置入玩家回复楼层
    const hasUserReplyInModel =
      userReplyClean &&
      modelNewReplies.some((r) => {
        const t = extractReplyPureText(r);
        return t && (t.includes(userReplyClean) || userReplyClean.includes(t));
      });

    let currentFloorCursor = maxFloorNum;
    if (userReplyClean && !hasUserReplyInModel) {
      currentFloorCursor += 1;
      repliesBox.append(buildSynthesizedUserReplyEl(replyTargetData, currentFloorCursor));
    }

    for (const newR of modelNewReplies) {
      let fNum = parseFloorNumber(newR);
      if (!Number.isFinite(fNum) || fNum <= currentFloorCursor) {
        currentFloorCursor += 1;
        fNum = currentFloorCursor;
        let floorSpan = newR.querySelector(".ast-floor");
        if (floorSpan) {
          floorSpan.textContent = `${fNum}L`;
        } else {
          let metaDiv = newR.querySelector(".ast-reply-meta");
          if (!metaDiv) {
            metaDiv = doc.createElement("div");
            metaDiv.className = "ast-reply-meta";
            newR.prepend(metaDiv);
          }
          floorSpan = doc.createElement("span");
          floorSpan.className = "ast-floor";
          floorSpan.textContent = `${fNum}L`;
          metaDiv.prepend(floorSpan);
        }
      } else {
        currentFloorCursor = fNum;
      }
      repliesBox.append(newR);
    }

    // 流式推演期间，在目标帖回复区底部挂载实时推演进度条，让用户直观看到盖楼正在演化
    if (isStreaming) {
      const streamStatusEl = doc.createElement("div");
      streamStatusEl.className = "ast-reply ast-reply-streaming-status";
      streamStatusEl.style.cssText =
        "border-left:2px solid var(--accent-gold);background:rgba(212,175,55,0.1);padding:8px 10px;";
      const headEl = doc.createElement("div");
      headEl.style.cssText = "font-weight:700;color:var(--accent-gold);font-size:12px;";
      headEl.textContent =
        modelNewReplies.length > 0
          ? `⏳ 正在流式生成坛友盖楼回应（已演化 ${modelNewReplies.length} 层）…`
          : "⏳ 正在推演楼主与坛友的盖楼回应（闭合思维链裁决中）…";
      streamStatusEl.append(headEl);
      if (thinkingPreview && modelNewReplies.length === 0) {
        const snippetEl = doc.createElement("div");
        snippetEl.style.cssText =
          "margin-top:4px;font-size:11.5px;color:var(--text-secondary);max-height:72px;overflow:hidden;white-space:pre-wrap;";
        snippetEl.textContent = thinkingPreview.slice(-220);
        streamStatusEl.append(snippetEl);
      }
      repliesBox.append(streamStatusEl);
    }

    if (baseWrap && targetInBase) {
      targetInBase.replaceWith(mergedPostEl);
      return baseWrap.innerHTML;
    }

    return `<div class="${rootClass}">\n${mergedPostEl.outerHTML}\n</div>`;
  }

  let lastRepliedPostId = "";

  // 断点状态解析：抽取完整帖与残帖元数据（不回传旧敏感正文，兼容表版 ast-net 与里版 ast-dark）
  function extractContinueState(rawHtml, forumMode = settings.forumMode) {
    const empty = { cleanBaseHtml: "", doneTitles: [], resumePost: null, remainCount: 7 };
    let text = "";
    try {
      text = stripGatewayRefusalPoison(String(rawHtml || ""));
    } catch {
      text = String(rawHtml || "");
    }
    if (!text || !/<article\b/i.test(text)) return empty;

    const rootClass = forumMode === "dark" ? "ast-dark" : "ast-net";
    const completeArticles = [];
    const doneTitles = [];
    let bannerHtml = "";
    let resumePost = null;

    try {
      const box = doc.createElement("div");
      box.innerHTML = text;
      stripInjectedPostControls(box);
      const bannerEl = box.querySelector(".ast-banner");
      if (bannerEl) bannerHtml = bannerEl.outerHTML;
      const articles = Array.from(box.querySelectorAll("article.ast-post, article"));
      for (const art of articles) {
        const titleEl = art.querySelector(".ast-post-title, h3, h2");
        const title = String(titleEl?.textContent || "").trim();
        const hasImg = Boolean(art.querySelector(".ast-img"));
        const hasReplies = Boolean(art.querySelector(".ast-replies"));
        const authorEl = art.querySelector(".ast-author, .ast-post-author");
        const author = String(authorEl?.textContent || "").trim();
        const board = String(art.getAttribute("data-board") || "").trim();
        if (hasImg && hasReplies) {
          completeArticles.push(art.outerHTML);
          if (title) doneTitles.push(title);
        } else {
          resumePost = { board, title, author };
        }
      }
    } catch {}

    // 兜底：DOM 解析失败时退化为正则抽取
    if (!completeArticles.length && /<article\b/i.test(text)) {
      const m = text.match(/<article\b[\s\S]*?<\/article>/gi) || [];
      for (const chunk of m) {
        if (/ast-img/i.test(chunk) && /ast-replies/i.test(chunk)) {
          completeArticles.push(chunk);
          const t = chunk.match(/<[^>]*ast-post-title[^>]*>([\s\S]*?)<\//i);
          if (t) doneTitles.push(String(t[1] || "").replace(/<[^>]*>/g, "").trim());
        }
      }
      const lastOpen = text.lastIndexOf("<article");
      const lastClose = text.lastIndexOf("</article>");
      if (lastOpen > lastClose) {
        const tailChunk = text.slice(lastOpen);
        const titleHit = tailChunk.match(/<[^>]*ast-post-title[^>]*>([\s\S]*?)<\//i);
        const boardHit = tailChunk.match(/data-board=["']([^"']*)["']/i);
        const authorHit = tailChunk.match(/<[^>]*ast-(?:post-)?author[^>]*>([\s\S]*?)<\//i);
        const title = titleHit ? String(titleHit[1] || "").replace(/<[^>]*>/g, "").trim() : "";
        if (title) {
          resumePost = {
            board: boardHit ? String(boardHit[1] || "").trim() : "",
            title,
            author: authorHit ? String(authorHit[1] || "").replace(/<[^>]*>/g, "").trim() : "",
          };
        }
      }
    }

    const cleanBaseHtml = completeArticles.length
      ? `<div class="${rootClass}">\n${bannerHtml ? bannerHtml + "\n" : ""}${completeArticles.join("\n")}`
      : "";

    return {
      cleanBaseHtml,
      doneTitles,
      resumePost,
      remainCount: Math.max(2, 7 - doneTitles.length),
    };
  }

  function detectForumTruncation(htmlString) {
    const text = String(htmlString || "");
    if (!text || !/<(?:div|article)\b/i.test(text)) {
      return { truncated: false, postCount: 0, reason: "" };
    }
    const openCount = (text.match(/<article\b/gi) || []).length;
    const closeCount = (text.match(/<\/article>/gi) || []).length;
    if (openCount > closeCount) {
      return { truncated: true, postCount: openCount, reason: "最后一篇帖子未写完即被截断" };
    }
    if (openCount > 0) {
      const lastIdx = text.lastIndexOf("<article");
      const tail = lastIdx >= 0 ? text.slice(lastIdx) : text;
      if (!/ast-replies/i.test(tail) || !/ast-img/i.test(tail)) {
        return { truncated: true, postCount: openCount, reason: "最后一篇帖子缺少留影石或评论区盖楼" };
      }
    }
    if ((!settings.targetBoard || settings.targetBoard === "all") && openCount > 0 && openCount < 6) {
      return { truncated: true, postCount: openCount, reason: "当前仅生成 " + openCount + " 篇（未达完整期刊篇数）" };
    }
    return { truncated: false, postCount: openCount, reason: "已完整生成" };
  }

  function mergeContinueHtml(baseHtml, contRaw) {
    const base = String(baseHtml || "").trim();
    let cont = cleanModelHtmlOutput(String(contRaw || ""));
    if (!cont) return base;
    if (!base) return cont;

    // 剥掉续写段开头的根容器与重复 banner，只保留其中的 <article> 结构
    cont = cont
      .replace(/^\s*<div[^>]*class=["'][^"']*ast-(?:dark|net)[^"']*["'][^>]*>/i, "")
      .replace(/^\s*<div[^>]*class=["'][^"']*ast-banner[^"']*["'][^>]*>[\s\S]*?<\/div>\s*<\/div>/i, "");
    const maxOverlap = Math.min(80, base.length, cont.length);
    for (let n = maxOverlap; n >= 8; n -= 1) {
      if (base.slice(-n) === cont.slice(0, n)) {
        cont = cont.slice(n);
        break;
      }
    }
    cont = cont.trim();
    if (!cont) return base;

    const merged = `${base}\n${cont}`;
    const openDiv = (merged.match(/<div\b(?![^>]*\/\s*>)/gi) || []).length;
    const closeDiv = (merged.match(/<\/div>/gi) || []).length;
    if (openDiv > closeDiv) return merged + "\n</div>".repeat(openDiv - closeDiv);
    return merged;
  }

  function unwrapSwallowedPosts(wrapper, streaming = false) {
    if (!wrapper) return;
    try {
      const outerList = Array.from(wrapper.querySelectorAll("article.ast-post"));
      for (const outer of outerList) {
        const inners = Array.from(outer.querySelectorAll("article.ast-post"));
        for (const node of inners) {
          if (outer.parentElement) outer.parentElement.insertBefore(node, outer.nextSibling);
        }
      }
      if (streaming) {
        const arts = Array.from(wrapper.querySelectorAll("article.ast-post"));
        const last = arts[arts.length - 1];
        if (last) {
          const openCount = (last.innerHTML.match(/<article\b/gi) || []).length;
          const closeCount = (last.innerHTML.match(/<\/article>/gi) || []).length;
          if (openCount > closeCount && !last.querySelector(".ast-stream-tail")) {
            const tail = doc.createElement("div");
            tail.className = "ast-stream-tail";
            tail.textContent = "…（魔导影像仍在拓印中）";
            tail.style.cssText = "margin-top:8px;color:var(--text-secondary);font-size:12px;letter-spacing:0.05em;";
            last.append(tail);
          }
        }
      }
    } catch (err) {
      console.warn("[命定论坛] unwrapSwallowedPosts 异常", err);
    }
  }

  async function triggerForumGeneration({
    actionType = "browse",
    userPostData = null,
    replyTargetData = null,
    silent = false,
  } = {}) {
    if (isGenerating) {
      if (!silent) setStatus("正在生成中，请稍候或点击右侧停止…");
      return;
    }
    if (actionType === "continue") {
      const looksLikeForum = (s) => Boolean(s && /<(?:div|article)\b/i.test(s));
      if (!looksLikeForum(currentHtml)) {
        const archivedHtml = archives.find((a) => looksLikeForum(a && a.html))?.html || "";
        if (looksLikeForum(archivedHtml)) {
          currentHtml = archivedHtml;
          if (!silent) setStatus("⏳ 已从最近一期存档恢复断点内容，准备续写…");
        }
      }
      if (!looksLikeForum(currentHtml)) {
        if (!silent) setStatus("⚠️ 未找到可续写的内容，已自动改为重新刷新论坛…");
        actionType = "browse";
      }
    }
    const baseForumHtmlBeforeGen = currentHtml;
    const continueState =
      actionType === "continue"
        ? extractContinueState(baseForumHtmlBeforeGen, settings.forumMode)
        : null;
    const continueBaseHtml = continueState ? continueState.cleanBaseHtml : "";

    isGenerating = true;
    lastRepliedPostId = replyTargetData?.postId || "";
    stopGenBtn.hidden = false;
    if (!silent) {
      activeTab = "forum";
      if (actionType === "reply_post" && replyTargetData) {
        currentHtml = mergeReplyEvolutionHtml(
          baseForumHtmlBeforeGen,
          "",
          replyTargetData,
          settings.forumMode,
          true
        );
        setStatus(`⏳ 已提交对《${replyTargetData.title}》的追问，正在扫描世界书并推演坛友盖楼…`);
      } else if (actionType === "continue") {
        setStatus("⏳ 正在解析断点进度并扫描世界书，准备无缝续写剩余论坛热帖…");
      } else {
        setStatus("⏳ 正在执行 checkAndScanWorldbooks 与 promptAutoSegments 拼装提示词…");
      }
      render();
    }

    try {
      const ctx = await ForumContextReader.collectFullContext(host, window, settings, {
        actionType,
        userPostData,
        replyTargetData,
        customDirection: customDirectionText,
      });

      if (replyTargetData && ctx.userName) {
        replyTargetData.userName = ctx.userName;
      }

      lastLoreScanStats = ctx.loreScanResult?.scanStats || null;
      const scanBrief = lastLoreScanStats
        ? `扫描 ${lastLoreScanStats.books.length} 本世界书，激活 ${lastLoreScanStats.activatedCount} 条设定（蓝灯${lastLoreScanStats.constantCount}/绿灯${lastLoreScanStats.selectiveCount}/递归${lastLoreScanStats.recursiveCount}）`
        : "世界书扫描完成";

      if (!silent) {
        setStatus(
          actionType === "reply_post"
            ? `⏳ ${scanBrief} · 正在流式推演《${replyTargetData?.title || "此帖"}》的后续盖楼…`
            : actionType === "continue"
            ? `⏳ ${scanBrief} · 正在从断点处流式续写剩余论坛热帖…`
            : `⏳ ${scanBrief} · 正在流式推演论坛热帖…`
        );
      }

      const { systemPrompt, userPrompt, orderedPrompts } =
        ForumPromptAssembler.buildForumPrompts({
          host,
          localWin: window,
          mode: settings.forumMode,
          targetBoard: settings.targetBoard,
          actionType,
          userPostData,
          replyTargetData,
          customDirection: customDirectionText,
          context: ctx,
          settings,
          continueMeta: continueState,
        });

      let lastRenderTime = 0;
      let latestRawStreamText = "";
      const rawResult = await ForumApiClient.generate({
        host,
        localWin: window,
        settings,
        systemPrompt,
        userPrompt,
        orderedPrompts,
        onStreamChunk: (partial, done, meta) => {
          if (meta?.isHeartbeat && !partial && !done) {
            if (!silent) {
              setStatus(
                `⏳ 假流式保活连接中：已收到 ${meta.heartbeatCount} 次心跳包（已等待 ${meta.elapsedSec}s，假流式需等上游完整生成后一次性返回，Pro模型耗时会明显长于Flash）…`
              );
              const existingPre = contentArea.querySelector(".ast-streaming-audit-pre");
              if (existingPre && !latestRawStreamText) {
                existingPre.textContent = `正在等待假流式上游模型完成整期生成…\n• 已收到反代保活心跳：${meta.heartbeatCount} 次（已耗时 ${meta.elapsedSec} 秒）\n• 提示：假流式会等模型写完全部内容后一次性传回；若使用 Pro 模型配合「🛠️ 工具一次调用」，因需在思维链与 JSON 字符串内转义上万 Token，耗时显著长于 Flash 模型。`;
              }
            }
            return;
          }
          latestRawStreamText = String(partial || "");
          const now = Date.now();
          if (done || now - lastRenderTime > 90) {
            lastRenderTime = now;
            const rawPartialCleaned = cleanModelHtmlOutput(partial);
            const cleanedPartial =
              actionType === "reply_post"
                ? mergeReplyEvolutionHtml(
                    baseForumHtmlBeforeGen,
                    partial,
                    replyTargetData,
                    settings.forumMode,
                    !done
                  )
                : actionType === "continue"
                ? (() => {
                    if (isFullyRefusedReply(String(partial || ""))) return baseForumHtmlBeforeGen;
                    const mergedTry = mergeContinueHtml(continueBaseHtml, partial);
                    if (!/<article\b/i.test(mergedTry)) return baseForumHtmlBeforeGen || mergedTry;
                    return mergedTry;
                  })()
                : rawPartialCleaned;
            currentHtml = cleanedPartial;
            if (!done && !silent) {
              const thinkingPreview = extractStreamingThinkingPreview(latestRawStreamText);
              if (rawPartialCleaned && /<(?:div|article)\b/i.test(rawPartialCleaned)) {
                setStatus(
                  actionType === "reply_post"
                    ? `⏳ 正在流式渲染新增盖楼回复… 已生成 ${rawPartialCleaned.length} 字符`
                    : actionType === "continue"
                    ? `⏳ 正在流式续写论坛热帖… 本轮已追加 ${rawPartialCleaned.length} 字符`
                    : `⏳ 正在流式渲染论坛热帖… 已生成 ${rawPartialCleaned.length} 字符`
                );
              } else if (thinkingPreview) {
                setStatus(`⏳ 正在流式执行「命定之诗」闭合思维链公开裁决… 已输出 ${thinkingPreview.length} 字符`);
              } else if (latestRawStreamText.length > 0) {
                setStatus(`⏳ 正在接收流式响应… 已接收 ${latestRawStreamText.length} 字符`);
              }
            }
            if (open && activeTab === "forum") {
              renderForumHtmlContent(currentHtml, !done, latestRawStreamText);
            }
          }
        },
      });

      const rawCleaned = cleanModelHtmlOutput(rawResult);
      const refusedNow = isFullyRefusedReply(String(rawResult || ""));
      if (refusedNow) {
        if (actionType === "continue" || actionType === "reply_post") {
          currentHtml = baseForumHtmlBeforeGen;
          if (!silent) renderForumHtmlContent(currentHtml, false, "");
          setStatus("⚠️ 续写/回帖请求被上游安全策略拦截，已保护原帖未受污染。可稍后重试。");
          return;
        }
        throw new Error("本次回复被上游安全策略整段拦截，请稍后重试。");
      }
      if (!rawCleaned && actionType !== "reply_post") {
        throw new Error("模型返回内容为空，请检查独立 API 配置或模型状态。");
      }

      const cleaned =
        actionType === "reply_post"
          ? mergeReplyEvolutionHtml(
              baseForumHtmlBeforeGen,
              rawResult,
              replyTargetData,
              settings.forumMode,
              false
            )
          : actionType === "continue"
          ? (() => {
              const contSafe = stripGatewayRefusalPoison(String(rawResult || ""));
              const mergedFinal = mergeContinueHtml(continueBaseHtml, contSafe);
              return /<article\b/i.test(mergedFinal) ? mergedFinal : rawCleaned;
            })()
          : rawCleaned;

      currentHtml = cleaned;
      const archiveItem = {
        id: "arch-" + Date.now(),
        time: new Date().toLocaleString("zh-CN", { hour12: false }),
        worldTime: ctx.latestTp || "当前时间",
        mode: settings.forumMode,
        board:
          actionType === "new_post"
            ? `发帖：${userPostData?.board}`
            : actionType === "reply_post"
            ? `回帖：${replyTargetData?.board}`
            : settings.targetBoard === "all"
            ? "全板块"
            : settings.targetBoard,
        html: cleaned,
      };
      if (actionType === "continue" && archives.length > 0) {
        archives[0].html = cleaned;
        archives[0].time = new Date().toLocaleString("zh-CN", { hour12: false });
        archives[0].worldTime = ctx.latestTp || archives[0].worldTime || "当前时间";
        saveArchives();
      } else {
        archives.unshift(archiveItem);
        saveArchives();
      }

      // 若本次为单帖盖楼追问，且该帖已存在于「⭐ 单帖收藏夹」中，自动将演化后的最新楼层同步更新至收藏夹
      if (actionType === "reply_post" && replyTargetData) {
        const favIdx = findFavoriteEntryIndex(replyTargetData.postId, replyTargetData.title);
        if (favIdx >= 0) {
          try {
            const tempWrap = doc.createElement("div");
            tempWrap.innerHTML = cleaned;
            const postsInCleaned = queryTopLevelPosts(tempWrap);
            const updatedPostEl = findTargetPostInList(postsInCleaned, replyTargetData);
            if (updatedPostEl) {
              favorites[favIdx].htmlContent = extractCleanPostHtml(
                updatedPostEl,
                favorites[favIdx].board || replyTargetData.board,
                favorites[favIdx].postId || replyTargetData.postId,
                false
              );
              favorites[favIdx].savedAt = new Date().toLocaleString("zh-CN", { hour12: false });
              saveFavorites();
            }
          } catch {}
        }
      }

      if (!open) {
        unread = true;
        updateLauncherFace();
      }
      setStatus(
        `✅ 命定论坛${
          actionType === "reply_post" ? "盖楼演化" : actionType === "continue" ? "断点续写" : "刷新"
        }完成（${
          settings.apiMode === "tavern" ? "酒馆主API" : settings.apiModel
        } · ${scanBrief} · 共 ${cleaned.length} 字符）`
      );
    } catch (err) {
      if ((actionType === "reply_post" || actionType === "continue") && baseForumHtmlBeforeGen) {
        currentHtml = baseForumHtmlBeforeGen;
      }
      if (err?.name === "AbortError") {
        setStatus("⏹ 已手动停止命定论坛生成。");
      } else {
        console.error("[命定论坛] 生成失败:", err);
        setStatus(`❌ 生成失败：${ForumApiClient.diagnoseApiError(err)}`);
      }
    } finally {
      isGenerating = false;
      stopGenBtn.hidden = true;
      if (open) render();
    }
  }

  // 弹出【设为行动线索（写入线索世界书并填入行动引导语）确认窗口】
  function openForumClueInjectionModal({ postEl, postData, onInjected = null }) {
    const existing = shell.querySelector(".ast-mvu-modal-backdrop");
    if (existing) existing.remove();

    // 极简聊天框行动引导语：帖子完整详情由后台线索世界书🔵蓝灯条目提供，聊天框只填一句行动引导语
    const defaultActionPrompt = `（在${postData.forumLabel}「${postData.board}」板块看到帖子《${postData.title}》，决定：）`;

    const modalBackdrop = make("div", "ast-mvu-modal-backdrop");
    const modal = make("div", "ast-mvu-modal");
    modal.addEventListener("click", (e) => e.stopPropagation());

    const head = make("div", "ast-mvu-modal-head");
    const titleWrap = make(
      "div",
      "ast-mvu-modal-title",
      "📘 设为行动线索（写入线索世界书并填入聊天框）"
    );
    const closeModalBtn = make("button", "icon", "×");
    closeModalBtn.type = "button";
    closeModalBtn.addEventListener("click", () => modalBackdrop.remove());
    head.append(titleWrap, closeModalBtn);

    const body = make("div", "ast-mvu-modal-body");

    const curDepth = settings.forumVarPromptDepth ?? 1;
    const curRole = (settings.forumVarPromptRole || "user").toUpperCase();
    const notice = make("div", "ast-mvu-notice");
    notice.innerHTML = `💡 确认后将把本帖完整情报（标题、发帖人真实身份、正文、留影石画面与 ${postData.replies.length} 条盖楼回复）设为<b>当前行动线索</b>，自动同步至当前角色主世界书的🔵蓝灯常驻条目 <b><code>📌【命定论坛】已注入行动线索</code></b>（@D=${curDepth}｜Role=${curRole}，直接发给酒馆主聊天 AI），并在主聊天输入框中填入下方行动引导语。`;

    const modeField = make("div", "field");
    modeField.append(make("label", "", "📘 线索世界书列表保存方式"));
    const modeSelect = make("select");
    for (const [v, l] of [
      ["append", "📌 设为当前行动线索，并在列表中保留早先注入的其他线索"],
      ["overwrite", "🔄 设为唯一行动线索（清空列表中早先注入的其他线索）"],
    ]) {
      const opt = make("option", "", l);
      opt.value = v;
      modeSelect.append(opt);
    }
    modeSelect.value = settings.forumVarInjectMode || "append";
    modeField.append(modeSelect);

    const postContentField = make("div", "field");
    postContentField.append(
      make(
        "label",
        "",
        "📄 即将写入线索世界书的帖子正文内容（可微调，盖楼回复与留影石将一并写入）："
      )
    );
    const postContentArea = make("textarea");
    postContentArea.style.minHeight = "110px";
    postContentArea.style.fontFamily = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
    postContentArea.style.fontSize = "12px";
    postContentArea.value = postData.bodyText || "";
    postContentField.append(postContentArea);

    const actionPromptField = make("div", "field");
    actionPromptField.append(
      make("label", "", "📥 即将填入酒馆主聊天框 (#send_textarea) 的行动引导语（可留空不填）：")
    );
    const actionPromptArea = make("textarea");
    actionPromptArea.style.minHeight = "54px";
    actionPromptArea.value = defaultActionPrompt;
    actionPromptField.append(actionPromptArea);

    body.append(notice, modeField, postContentField, actionPromptField);

    const foot = make("div", "ast-mvu-modal-foot");

    const cancelBtn = make("button", "pill-btn", "取消");
    cancelBtn.type = "button";
    cancelBtn.addEventListener("click", () => modalBackdrop.remove());

    const confirmBtn = make("button", "pill-btn primary", "✅ 确认写入线索世界书并填入聊天框");
    confirmBtn.type = "button";
    confirmBtn.style.padding = "6px 14px";
    confirmBtn.addEventListener("click", async () => {
      confirmBtn.disabled = true;
      try {
        settings.forumVarInjectMode = modeSelect.value;
        saveSettings();

        const varRes = await ForumVariableTreeManager.injectPostToForumTree(host, window, {
          postData,
          editedFullText: postContentArea.value.trim(),
          mode: settings.forumVarInjectMode,
        });

        const shortText = actionPromptArea.value.trim();
        const chatRes = shortText
          ? fillOrSendToTavern(host, shortText, false)
          : { ok: true, msg: "未填入聊天框" };
        setStatus(`${varRes.msg} ｜ ${chatRes.msg}`);
        if (varRes.ok) onInjected?.();
        modalBackdrop.remove();
      } finally {
        confirmBtn.disabled = false;
      }
    });

    foot.append(cancelBtn, confirmBtn);
    modal.append(head, body, foot);
    modalBackdrop.append(modal);
    modalBackdrop.addEventListener("click", () => modalBackdrop.remove());
    shell.append(modalBackdrop);
  }

  // 导航栏独立页面：「📘 线索世界书」（管理写入角色主世界书🔵蓝灯常驻条目的全部论坛帖子线索）
  async function renderVariablesTab() {
    boardFilterBar.hidden = true;
    controlStrip.hidden = true;
    contentArea.replaceChildren();

    const loadingCard = make("div", "form-card", "⏳ 正在读取线索世界书与已注入行动线索状态…");
    contentArea.append(loadingCard);

    const { forumData } = await ForumVariableTreeManager.readForumVariableTree(host, window);

    contentArea.replaceChildren();
    const dashboard = make("div", "wf-dashboard");

    const list = Array.isArray(forumData.已注入帖子列表) ? forumData.已注入帖子列表 : [];
    const activeClue = forumData.当前行动线索 || null;
    const wbStatus = ForumVariableTreeManager.getLastWorldbookSyncStatus();

    // 1. 顶部概览与蓝灯世界书同步控制栏
    const hero = make("div", "wf-hero");
    const heroTop = make("div", "wf-hero-top");
    const titleWrap = make("div", "");
    titleWrap.append(
      make("div", "wf-hero-title", "📘 命定论坛 · 线索世界书管理"),
      make(
        "div",
        "wf-hero-sub",
        `已注入 ${list.length} 条论坛行动线索 · 自动同步至当前角色主世界书🔵蓝灯常驻条目「📌【命定论坛】已注入行动线索」`
      )
    );

    const btnRow = make("div", "row-inline");
    const syncNowBtn = make("button", "pill-btn primary", "⚡ 立即同步至线索世界书");
    syncNowBtn.type = "button";
    syncNowBtn.addEventListener("click", async () => {
      syncNowBtn.disabled = true;
      const res = await ForumVariableTreeManager.saveForumVariableTree(host, window, forumData);
      setStatus(
        res.ok
          ? `✅ ${res.wbAction}（目标世界书：${res.syncedBookName || "已绑定"}）`
          : `⚠️ 同步失败：${res.wbAction || res.wbError}`
      );
      renderVariablesTab();
    });

    const clearAllBtn = make("button", "pill-btn", "🗑️ 清空全部线索并关闭蓝灯条目");
    clearAllBtn.type = "button";
    clearAllBtn.disabled = !activeClue && list.length === 0;
    clearAllBtn.addEventListener("click", async () => {
      clearAllBtn.disabled = true;
      const emptyTree = ForumVariableTreeManager.createDefaultForumDataTree();
      const res = await ForumVariableTreeManager.saveForumVariableTree(host, window, emptyTree);
      setStatus(
        res.ok
          ? `🗑️ 已清空全部论坛行动线索，并已关闭世界书「${res.syncedBookName}」中的蓝灯条目！`
          : "⚠️ 清空完成（未检测到绑定世界书）"
      );
      renderVariablesTab();
    });

    btnRow.append(syncNowBtn, clearAllBtn);
    heroTop.append(titleWrap, btnRow);

    // 线索世界书蓝灯条目参数设置行（写入范围、插入深度 @D、消息角色 Role）
    const paramGrid = make("div", "wf-param-grid");

    const scopeBox = make("div", "wf-param-box");
    scopeBox.append(make("label", "", "📦 线索世界书写入范围"));
    const scopeSel = make("select");
    scopeSel.style.cssText =
      "background:var(--bg-main);border:1px solid var(--border-soft);border-radius:6px;padding:6px 9px;color:var(--accent-gold);font-weight:700;font-size:13px;width:100%;";
    for (const [v, l] of [
      ["active_only", "仅写入「当前行动线索」（默认 · 最省 Token）"],
      ["full", "完整线索（当前行动线索 + 已注入帖子列表）"],
    ]) {
      const o = make("option", "", l);
      o.value = v;
      scopeSel.append(o);
    }
    scopeSel.value = settings.forumVarPromptScope || "active_only";
    scopeBox.append(scopeSel);

    const depthBox = make("div", "wf-param-box");
    depthBox.append(make("label", "", "📍 蓝灯条目插入深度 (@D Depth)"));
    const depthInput = make("input");
    depthInput.type = "number";
    depthInput.min = "0";
    depthInput.max = "50";
    depthInput.value = settings.forumVarPromptDepth ?? 1;
    depthBox.append(depthInput);

    const roleBox = make("div", "wf-param-box");
    roleBox.append(make("label", "", "🎭 蓝灯条目消息角色 (Role)"));
    const roleSel = make("select");
    roleSel.style.cssText =
      "background:var(--bg-main);border:1px solid var(--border-soft);border-radius:6px;padding:6px 9px;color:var(--accent-gold);font-weight:700;font-size:13px;width:100%;";
    for (const [v, l] of [
      ["user", "USER (用户输入层 · 默认推荐)"],
      ["system", "SYSTEM (系统设定层)"],
      ["assistant", "ASSISTANT (模型上下文层)"],
    ]) {
      const o = make("option", "", l);
      o.value = v;
      roleSel.append(o);
    }
    roleSel.value = settings.forumVarPromptRole || "user";
    roleBox.append(roleSel);

    paramGrid.append(scopeBox, depthBox, roleBox);

    const applyWbConfigChange = async () => {
      settings.forumVarPromptScope = scopeSel.value;
      const dVal = Number(depthInput.value);
      settings.forumVarPromptDepth = Number.isFinite(dVal) ? Math.max(0, Math.min(50, Math.round(dVal))) : 1;
      settings.forumVarPromptRole = roleSel.value;
      saveSettings();
      const res = await ForumVariableTreeManager.saveForumVariableTree(host, window, forumData);
      setStatus(
        res.ok
          ? `✅ 已更新线索世界书配置（世界书：${res.syncedBookName || "已绑定"}｜范围：${settings.forumVarPromptScope === "full" ? "完整线索" : "仅当前行动线索"}｜@D=${settings.forumVarPromptDepth}｜Role=${settings.forumVarPromptRole.toUpperCase()}）`
          : `⚠️ 线索世界书同步未成功：${res.wbAction || res.wbError}`
      );
      renderVariablesTab();
    };

    scopeSel.addEventListener("change", applyWbConfigChange);
    depthInput.addEventListener("change", applyWbConfigChange);
    roleSel.addEventListener("change", applyWbConfigChange);

    const statusLine = make("div", "wf-param-hint");
    statusLine.innerHTML = wbStatus.bookName
      ? `📘 当前绑定世界书：<b style="color:var(--accent-gold);">${wbStatus.bookName}</b> ｜ 状态：<b>${wbStatus.action}</b>`
      : `📘 提示：当你将任意论坛帖子设为行动线索时，会自动在当前角色主世界书中创建🔵蓝灯常驻条目 <code>📌【命定论坛】已注入行动线索</code>。`;

    hero.append(heroTop, paramGrid, statusLine);
    dashboard.append(hero);

    // 2. 已注入行动线索卡片列表
    const listCard = make("div", "wf-section-card");
    const listHead = make("div", "wf-section-head");
    listHead.append(
      make("h3", "wf-section-title", `📌 已注入的论坛行动线索列表 (${list.length})`),
      make(
        "span",
        "wf-badge",
        activeClue ? `当前行动线索：《${activeClue.标题 || "未命名"}》` : "当前无行动线索"
      )
    );
    listCard.append(listHead);

    if (list.length === 0 && !activeClue) {
      const emptyBox = make(
        "div",
        "empty-state",
        "当前暂无已注入的论坛行动线索。可在「📰 首页」或「⭐ 收藏」任意帖子底部点击「📥 设为行动线索（填入聊天框）」，即可将该帖写入线索世界书🔵蓝灯条目。"
      );
      listCard.append(emptyBox);
    } else {
      const effectiveList = list.length > 0 ? list : activeClue ? [activeClue] : [];

      effectiveList.forEach((item, idx) => {
        const isCurrentActive =
          activeClue &&
          ((item.线索ID && activeClue.线索ID === item.线索ID) ||
            (item.标题 && activeClue.标题 === item.标题 && item.帖子ID === activeClue.帖子ID));

        const clueCard = make(
          "div",
          "var-clue-card" + (isCurrentActive ? " is-active-clue" : "")
        );

        const cHead = make("div", "var-clue-head");
        const cTitleWrap = make("div", "row-inline");
        if (isCurrentActive) {
          cTitleWrap.append(make("span", "post-injected-badge", "⭐ 当前行动线索"));
        }
        cTitleWrap.append(
          make("span", "wf-badge", `${item.来源论坛 || "命定论坛"} · ${item.所属板块 || "综合"}`),
          make("span", "var-clue-title", `《${item.标题 || `线索 #${idx + 1}`}》`)
        );

        const cBtns = make("div", "row-inline");

        if (!isCurrentActive) {
          const setActiveBtn = make("button", "pill-btn", "📌 设为当前行动线索");
          setActiveBtn.type = "button";
          setActiveBtn.addEventListener("click", async () => {
            forumData.当前行动线索 = item;
            await ForumVariableTreeManager.saveForumVariableTree(host, window, forumData);
            setStatus(`✅ 已将《${item.标题}》设为当前行动线索并同步至线索世界书！`);
            renderVariablesTab();
          });
          cBtns.append(setActiveBtn);
        }

        const fillBtn = make("button", "pill-btn primary", "📥 填入行动引导语到聊天框");
        fillBtn.type = "button";
        fillBtn.addEventListener("click", () => {
          const shortPrompt = `（在${item.来源论坛 || "命定论坛"}「${item.所属板块 || "综合"}」板块看到帖子《${item.标题}》，决定：）`;
          const res = fillOrSendToTavern(host, shortPrompt, false);
          setStatus(res.msg);
        });

        const editToggleBtn = make("button", "pill-btn", "✏️ 编辑内容");
        editToggleBtn.type = "button";

        const delBtn = make("button", "pill-btn", "🗑️ 删除");
        delBtn.type = "button";
        delBtn.addEventListener("click", async () => {
          const nextList = effectiveList.filter((_, i) => i !== idx);
          forumData.已注入帖子列表 = nextList;
          if (isCurrentActive) {
            forumData.当前行动线索 = nextList[0] || null;
          }
          await ForumVariableTreeManager.saveForumVariableTree(host, window, forumData);
          setStatus(`🗑️ 已移除《${item.标题}》并同步更新线索世界书蓝灯条目`);
          renderVariablesTab();
        });

        cBtns.append(fillBtn, editToggleBtn, delBtn);
        cHead.append(cTitleWrap, cBtns);

        const cMeta = make("div", "var-clue-meta");
        cMeta.innerHTML = `<span>👤 发帖人：<b>${item.发帖人昵称 || "匿名"}</b></span><span>👁️ 真实身份：<b style="color:var(--admin-text);">${item.发帖人真实身份 || "未知"}</b></span><span>🕒 注入时间：${item.注入时间 || "未知"}</span>`;

        const previewBox = make("div", "");
        previewBox.style.cssText =
          "font-size:12.5px;color:var(--text-primary);white-space:pre-wrap;background:rgba(0,0,0,0.22);padding:8px 10px;border-radius:7px;border:1px solid rgba(255,255,255,0.06);max-height:140px;overflow-y:auto;";
        previewBox.textContent = ForumVariableTreeManager.formatCluePreviewText(item);

        // 展开编辑抽屉
        const editDrawer = make("div", "post-reply-drawer");
        editDrawer.hidden = true;
        const editLabel = make("label", "wf-param-hint", "编辑该条行动线索的正文内容（保存后立即同步至线索世界书）：");
        const editArea = make("textarea");
        editArea.style.minHeight = "96px";
        editArea.style.fontFamily = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
        editArea.style.fontSize = "12px";
        editArea.value = item.正文内容 || "";

        const editRepliesLabel = make("label", "wf-param-hint", "编辑盖楼回复列表（每行一条回复）：");
        const editRepliesArea = make("textarea");
        editRepliesArea.style.minHeight = "84px";
        editRepliesArea.style.fontFamily = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
        editRepliesArea.style.fontSize = "12px";
        editRepliesArea.value = Array.isArray(item.盖楼回复) ? item.盖楼回复.join("\n") : "";

        const saveEditBtn = make("button", "pill-btn primary", "💾 保存修改至线索世界书");
        saveEditBtn.type = "button";
        saveEditBtn.style.alignSelf = "flex-start";
        saveEditBtn.addEventListener("click", async () => {
          item.正文内容 = editArea.value.trim();
          item.盖楼回复 = editRepliesArea.value
            .split(/\r?\n/)
            .map((s) => s.trim())
            .filter(Boolean);
          if (isCurrentActive && forumData.当前行动线索) {
            forumData.当前行动线索.正文内容 = item.正文内容;
            forumData.当前行动线索.盖楼回复 = [...item.盖楼回复];
          }
          await ForumVariableTreeManager.saveForumVariableTree(host, window, forumData);
          previewBox.textContent = ForumVariableTreeManager.formatCluePreviewText(item);
          editDrawer.hidden = true;
          setStatus(`✅ 已更新《${item.标题}》并同步至线索世界书蓝灯条目！`);
        });

        editDrawer.append(editLabel, editArea, editRepliesLabel, editRepliesArea, saveEditBtn);
        editToggleBtn.addEventListener("click", () => {
          editDrawer.hidden = !editDrawer.hidden;
        });

        clueCard.append(cHead, cMeta, previewBox, editDrawer);
        listCard.append(clueCard);
      });
    }

    dashboard.append(listCard);

    // 3. 蓝灯世界书条目实际内容预览
    const rawCard = make("div", "wf-section-card");
    const rawHead = make("div", "wf-section-head");
    rawHead.append(
      make("h3", "wf-section-title", "👁️ 蓝灯世界书条目内容预览 (📌【命定论坛】已注入行动线索)"),
      make("span", "wf-badge", `Constant 🔵 @D=${settings.forumVarPromptDepth ?? 1} · Role=${(settings.forumVarPromptRole || "user").toUpperCase()}`)
    );
    const rawArea = make("textarea");
    rawArea.readOnly = true;
    rawArea.style.cssText =
      "width:100%;min-height:200px;background:#070b14;border:1px solid var(--border-soft);border-radius:8px;padding:10px;color:#cbd5e1;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;line-height:1.55;resize:vertical;";
    rawArea.value =
      ForumVariableTreeManager.buildWorldbookClueContent(forumData, {
        scope: settings.forumVarPromptScope || "active_only",
      }) || "（当前无已注入的论坛行动线索，蓝灯世界书条目处于关闭/空置状态）";

    contentArea.append(dashboard);
    rawCard.append(rawHead, rawArea);
    dashboard.append(rawCard);
  }

  function renderForumHtmlContent(htmlString, streaming = false, rawStreamingText = "") {
    const prevScrollTop = contentArea.scrollTop;
    contentArea.replaceChildren();
    contentArea.classList.toggle("hide-admin-identity", !settings.showAdminIdentity);

    const hasForumHtmlStarted = Boolean(htmlString && /<(?:div|article)\b/i.test(htmlString));

    if (!hasForumHtmlStarted) {
      if (streaming) {
        const thinkingText = extractStreamingThinkingPreview(rawStreamingText || htmlString);
        const existingPre = contentArea.querySelector(".ast-streaming-audit-pre");
        if (existingPre) {
          existingPre.textContent =
            thinkingText || "正在建立阿斯塔利亚星网连接并等待首个流式 Token…";
          return;
        }
        const streamBox = make("div", "form-card");
        streamBox.style.cssText =
          "margin:4px 0;padding:14px 16px;background:linear-gradient(148deg,#0b0f16 0%,#070a0f 58%,#090c12 100%);border:1px solid rgba(185,149,89,0.42);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,0.35);";
        const streamHeader = make(
          "div",
          "",
          "✦ 命定之诗 · 闭合思维链公开裁决流式推演中…"
        );
        streamHeader.style.cssText =
          "color:#d3bb8a;font-weight:700;font-size:14px;letter-spacing:0.08em;padding-bottom:8px;border-bottom:1px solid rgba(185,149,89,0.22);margin-bottom:8px;";
        const streamBody = make(
          "pre",
          "ast-streaming-audit-pre",
          thinkingText || "正在建立阿斯塔利亚星网连接并等待首个流式 Token…"
        );
        streamBody.style.cssText =
          "margin:0;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;color:#ded7c8;font-family:'Noto Serif SC','Source Han Serif SC','Songti SC',serif;font-size:12.5px;line-height:1.75;max-height:320px;overflow-y:auto;";
        streamBox.append(streamHeader, streamBody);
        contentArea.append(streamBox);
        return;
      }

      const empty = make("div", "empty-state");
      empty.innerHTML = `
        <div style="font-size:30px;margin-bottom:8px;">🔮</div>
        <div style="font-size:15px;font-weight:700;color:var(--accent-gold);margin-bottom:6px;">
          命定论坛频段已就绪
        </div>
        <div>点击上方 <b>「⚡ 刷新论坛」</b> 即可通过世界书扫描器与分槽位提示词引擎，实时推演当前时间线的阿斯塔利亚论坛热帖。</div>
      `;
      contentArea.append(empty);
      return;
    }

    const wrapper = make("div", "forum-render-root");
    wrapper.innerHTML = htmlString;

    // 剥离任何由旧存档或模型回显残留的交互按钮/抽屉节点，防止产生无事件监听的死按钮
    stripInjectedPostControls(wrapper);
    unwrapSwallowedPosts(wrapper, streaming);

    let posts = queryTopLevelPosts(wrapper);
    if (!posts.length && !streaming) {
      const rootNet = wrapper.querySelector(".ast-net, .ast-dark") || wrapper;
      if (rootNet.querySelector(".ast-post-head, .ast-post-title, .ast-post-body, .ast-replies")) {
        const fallbackArticle = make("article", "ast-post");
        fallbackArticle.setAttribute("data-board", "综合");
        fallbackArticle.setAttribute("data-post-id", "post-1");
        for (const child of [...rootNet.children]) {
          if (child.classList?.contains("ast-banner")) continue;
          fallbackArticle.append(child);
        }
        rootNet.append(fallbackArticle);
        posts = [fallbackArticle];
      }
    }

    const discoveredBoards = new Set();
    assignDeterministicPostAttributes(posts);
    posts.forEach((postEl) => {
      discoveredBoards.add(postEl.getAttribute("data-board") || "综合");
    });

    // 非流式状态下，将规范化后的唯一 data-post-id 与 data-board 同步回 currentHtml，确保后续盖楼精准定位原帖
    if (!streaming && posts.length > 0) {
      currentHtml = wrapper.innerHTML;
    }

    if (activeBoardFilter !== "ALL" && discoveredBoards.size > 0 && !discoveredBoards.has(activeBoardFilter)) {
      activeBoardFilter = "ALL";
    }

    posts.forEach((postEl, idx) => {
      const boardName = postEl.getAttribute("data-board") || "综合";
      const postId = postEl.getAttribute("data-post-id") || `post-${idx + 1}`;

      if (activeBoardFilter !== "ALL" && boardName !== activeBoardFilter) {
        postEl.hidden = true;
      } else {
        postEl.hidden = false;
      }

      // 挂载魔导留影石 × st-chatu8 生图组件与隐藏 <imgthink>
      enhancePostMagicStoneImage(postEl, idx, streaming);

      if (!streaming) {
        const titleEl = postEl.querySelector(".ast-post-title, h3, h2");
        const titleText = titleEl ? titleEl.textContent.trim() : `帖子 #${idx + 1}`;

        const actionBar = make("div", "post-actions-bar");
        const replyBtn = make("button", "pill-btn", "💬 盖楼/追问此帖");
        replyBtn.type = "button";

        const isFavNow = findFavoriteEntryIndex(postId, titleText) >= 0;
        const favBtn = make(
          "button",
          "pill-btn" + (isFavNow ? " fav-active" : ""),
          isFavNow ? "🌟 已收藏" : "⭐ 收藏此帖"
        );
        favBtn.type = "button";
        favBtn.title = "将此单帖永久加入「⭐ 收藏」个人书签（不受历史期刊滚动清理影响）";
        favBtn.addEventListener("click", () => {
          const existingIdx = findFavoriteEntryIndex(postId, titleText);
          if (existingIdx >= 0) {
            favorites.splice(existingIdx, 1);
            saveFavorites();
            favBtn.classList.remove("fav-active");
            favBtn.textContent = "⭐ 收藏此帖";
            setStatus(`已从个人书签移除《${titleText}》`);
          } else {
            const authorEl = postEl.querySelector(".ast-post-meta .ast-author, .ast-author");
            const authorName = authorEl ? authorEl.textContent.replace(/^👤\s*/, "").trim() : "匿名坛友";
            const adminEl = postEl.querySelector(".ast-post-meta .ast-admin, .ast-admin");
            const adminText = adminEl ? adminEl.textContent.trim() : "";
            const chatu8Prompt =
              postEl.querySelector(".ast-img")?.getAttribute("data-chatu8-prompt") || "";
            const cleanPostHtml = extractCleanPostHtml(postEl, boardName, postId, false);
            favorites.unshift({
              favId: "fav-" + Date.now() + "-" + Math.random().toString(36).slice(2, 6),
              postId,
              title: titleText,
              board: boardName,
              author: authorName,
              adminIdentity: adminText,
              mode: settings.forumMode,
              savedAt: new Date().toLocaleString("zh-CN", { hour12: false }),
              htmlContent: cleanPostHtml,
              chatu8Prompt,
            });
            saveFavorites();
            favBtn.classList.add("fav-active");
            favBtn.textContent = "🌟 已收藏";
            setStatus(`🌟 已将《${titleText}》加入「⭐ 收藏」个人书签！`);
          }
          const favNavBtn = subbar.querySelector('[data-nav-id="favorites"]');
          if (favNavBtn) favNavBtn.textContent = `⭐ 收藏(${favorites.length})`;
        });

        const fillChatBtn = make("button", "pill-btn", "📥 设为行动线索（填入聊天框）");
        fillChatBtn.type = "button";

        const replyDrawer = make("div", "post-reply-drawer");
        replyDrawer.hidden = true;
        const replyNick = make("input");
        replyNick.type = "text";
        replyNick.autocomplete = "off";
        replyNick.value = settings.activeUserAlias || "";
        replyNick.placeholder = "你的匿名回复昵称（留空默认：匿名星轨旅人）";
        const replyAliasBar = createAliasSelectorBar(replyNick);
        const replyInput = make("textarea");
        replyInput.placeholder = `回复《${titleText}》楼主或层主，提交后将调用独立 API 续写坛友们的互动反馈…`;
        const submitReplyBtn = make("button", "pill-btn primary", "✨ 提交回复并演化后续楼层");
        submitReplyBtn.type = "button";

        submitReplyBtn.addEventListener("click", () => {
          const val = replyInput.value.trim();
          if (!val) {
            setStatus("请先输入你的回复内容！");
            return;
          }
          const chosenAuthor = replyNick.value.trim() || settings.activeUserAlias || "匿名星轨旅人";
          settings.activeUserAlias = chosenAuthor;
          saveSettings();
          const chatu8Prompt =
            postEl.querySelector(".ast-img")?.getAttribute("data-chatu8-prompt") || "";
          const cleanPostHtml = extractCleanPostHtml(postEl, boardName, postId, true);
          triggerForumGeneration({
            actionType: "reply_post",
            replyTargetData: {
              postId,
              postIndex: idx,
              board: boardName,
              title: titleText,
              htmlContent: cleanPostHtml,
              chatu8Prompt,
              userReply: val,
              author: chosenAuthor,
            },
          });
        });

        replyDrawer.append(replyNick, replyAliasBar, replyInput, submitReplyBtn);

        replyBtn.addEventListener("click", () => {
          replyDrawer.hidden = !replyDrawer.hidden;
          if (!replyDrawer.hidden) {
            try {
              replyInput.focus({ preventScroll: true });
            } catch {}
          }
        });

        const injectedBadge = make("span", "post-injected-badge", "📘 已入线索世界书");
        injectedBadge.hidden = postEl.getAttribute("data-mvu-injected") !== "true";

        const handleOpenClueModal = () => {
          const postData = ForumVariableTreeManager.extractPostStructuredData(
            postEl,
            boardName,
            postId,
            settings.forumMode
          );
          openForumClueInjectionModal({
            postEl,
            postData,
            onInjected: () => {
              postEl.setAttribute("data-mvu-injected", "true");
              injectedBadge.hidden = false;
              const renderRoot = contentArea.querySelector(".forum-render-root");
              if (renderRoot) {
                const cloneRoot = renderRoot.cloneNode(true);
                stripInjectedPostControls(cloneRoot);
                for (const p of cloneRoot.querySelectorAll(".ast-post")) {
                  p.hidden = false;
                  p.removeAttribute("hidden");
                }
                currentHtml = cloneRoot.innerHTML;
                if (archives.length > 0) {
                  archives[0].html = currentHtml;
                  saveArchives();
                }
              }
            },
          });
        };

        fillChatBtn.addEventListener("click", handleOpenClueModal);

        actionBar.append(replyBtn, favBtn, fillChatBtn, injectedBadge);
        postEl.append(actionBar, replyDrawer);
      }
    });

    boardFilterBar.replaceChildren();
    if (discoveredBoards.size > 0) {
      boardFilterBar.hidden = false;
      const allChip = make(
        "button",
        "board-chip" + (activeBoardFilter === "ALL" ? " active" : ""),
        `全部 (${posts.length})`
      );
      allChip.type = "button";
      allChip.addEventListener("click", () => {
        activeBoardFilter = "ALL";
        renderForumHtmlContent(currentHtml, streaming);
      });
      boardFilterBar.append(allChip);

      for (const bName of discoveredBoards) {
        const count = posts.filter((p) => p.getAttribute("data-board") === bName).length;
        const chip = make(
          "button",
          "board-chip" + (activeBoardFilter === bName ? " active" : ""),
          `${bName} (${count})`
        );
        chip.type = "button";
        chip.addEventListener("click", () => {
          activeBoardFilter = bName;
          renderForumHtmlContent(currentHtml, streaming);
        });
        boardFilterBar.append(chip);
      }
    } else {
      boardFilterBar.hidden = true;
    }

    if (!streaming) {
      const truncInfo = detectForumTruncation(currentHtml);
      const tailBar = make("div", "continue-tail-bar");
      tailBar.style.cssText = truncInfo.truncated
        ? "margin:14px 0 4px;padding:12px 14px;border-radius:10px;border:1px solid rgba(255,179,71,0.55);background:linear-gradient(135deg,rgba(58,20,12,0.92),rgba(38,10,30,0.92));display:flex;flex-direction:column;gap:8px;"
        : "margin:14px 0 4px;padding:10px 12px;border-radius:10px;border:1px dashed var(--border-main);background:rgba(255,255,255,0.03);display:flex;justify-content:center;";
      if (truncInfo.truncated) {
        const tip = make("div", "", `⚠️ 魔导频段在半途截断（${truncInfo.reason}）`);
        tip.style.cssText =
          "color:#ffd08a;font-size:13px;font-weight:700;letter-spacing:0.03em;line-height:1.6;";
        const goBtn = make("button", "pill-btn primary", "▶️ 从断点处无缝继续拓印剩余热帖");
        goBtn.type = "button";
        goBtn.addEventListener("click", () =>
          triggerForumGeneration({ actionType: "continue" })
        );
        tailBar.append(tip, goBtn);
      } else {
        const moreBtn = make("button", "pill-btn", "➕ 意犹未尽？顺着当前上下文继续加更更多论坛热帖 ▶️");
        moreBtn.type = "button";
        moreBtn.addEventListener("click", () =>
          triggerForumGeneration({ actionType: "continue" })
        );
        tailBar.append(moreBtn);
      }
      wrapper.append(tailBar);
    }

    contentArea.append(wrapper);
    if (prevScrollTop > 0) {
      contentArea.scrollTop = prevScrollTop;
    } else if (!streaming && lastRepliedPostId) {
      const repliedEl = wrapper.querySelector(
        `.ast-post[data-post-id="${lastRepliedPostId}"]`
      );
      if (repliedEl) {
        try {
          repliedEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
        } catch {}
      }
      lastRepliedPostId = "";
    }
  }

