    const imgInput = make("input");
    imgInput.type = "text";
    imgInput.autocomplete = "off";
    imgInput.placeholder = "例如：留影石拍下的沉船坟场紫雾消散画面 / 某件稀有炼金造物特写…";
    imgField.append(imgInput);

    const submitBtn = make("button", "pill-btn primary", "🚀 立即发布至命定论坛并生成坛友回复");
    submitBtn.style.alignSelf = "flex-start";
    submitBtn.style.padding = "8px 18px";
    submitBtn.addEventListener("click", () => {
      if (!titleInput.value.trim() || !contentInput.value.trim()) {
        setStatus("请填写帖子标题和正文内容！");
        return;
      }
      const chosenAuthor = authorInput.value.trim() || settings.activeUserAlias || "匿名星轨旅人";
      settings.activeUserAlias = chosenAuthor;
      saveSettings();
