    boardFilterBar.hidden = true;
    controlStrip.hidden = true;
    contentArea.replaceChildren();

    const dashboard = make("div", "wf-dashboard");
    const cfg = settings.taskContextConfig || defaultTaskContextConfig;
    const slotsList = Array.isArray(settings.promptSlots)
      ? settings.promptSlots
      : defaultPromptSlotsConfig;

