      const val = make("div", "wf-kpi-val" + (valCls ? " " + valCls : ""), valText);
      box.append(lbl, val);
      return { box, val };
    };

    const kpiBooks = makeKpi(
      "📚 作用世界书范围",
      Array.isArray(settings.affectedBooks) && settings.affectedBooks.length
        ? `已指定 ${settings.affectedBooks.length} 本`
        : "自动全选绑定世界书",
      "cyan"
    );
    const kpiEntries = makeKpi(
      "✨ 最近激活设定条目",
      lastLoreScanStats
        ? `${lastLoreScanStats.activatedCount} 条 (蓝${lastLoreScanStats.constantCount}/绿${lastLoreScanStats.selectiveCount}/递${lastLoreScanStats.recursiveCount})`
        : "点击上方「扫描检测」查看",
      "gold"
    );
