      "📐 上下文总字符预算",
      `${currentBudget.toLocaleString()} 字符`,
      ""
    );
    const activeExtCount = (cfg.extractRules || []).filter((r) => r.enabled !== false).length;
    const activeExcCount = (cfg.excludeRules || []).filter((r) => r.enabled !== false).length;
    const activeSlotCount = slotsList.filter((s) => s.enabled !== false).length;
    const kpiRules = makeKpi(
