      scanDrawer.innerHTML = `<div><strong style="color:var(--accent-gold);">🎯 最近一次扫描命中的世界书条目 (${lastLoreScanStats.activatedCount}/${lastLoreScanStats.totalEntries})：</strong></div><div>${lastLoreScanStats.activatedNames
        .map((n) => `<span class="wf-pill-code" style="display:inline-block;margin:2px 4px 2px 0;">${n}</span>`)
        .join("")}</div>`;
    } else {
      scanDrawer.hidden = true;
    }

    hero.append(heroTop, kpiGrid, scanDrawer);
    dashboard.append(hero);

    // ─── 1. 世界书扫描器配置卡片 (PlotWorldbookConfig & affectedBooks) ───
    const wbCard = make("div", "wf-section-card");
    const wbHead = make("div", "wf-section-head");
    const wbTitleWrap = make("div", "row-inline");
    wbTitleWrap.append(
      make("h3", "wf-section-title", "📚 世界书动态扫描器"),
      make("span", "wf-badge", "checkAndScanWorldbooks")
    );

    const wbSwitchLabel = make("label", "ui-switch-label");
    const wbSwitch = make("input", "ui-switch");
    wbSwitch.type = "checkbox";
    wbSwitch.checked = settings.includeLorebook !== false;
    wbSwitch.addEventListener("change", () => {
      settings.includeLorebook = wbSwitch.checked;
      saveSettings();
    });
    wbSwitchLabel.append( make("span", "", "启用世界书扫描"), wbSwitch);
    wbHead.append(wbTitleWrap, wbSwitchLabel);
    wbCard.append(wbHead);

    const wbParamGrid = make("div", "wf-param-grid");

    const depthBox = make("div", "wf-param-box");
    depthBox.append(make("label", "", "🔍 默认扫描深度 (scanDepth)"));
    const depthInput = make("input");
    depthInput.type = "number";
    depthInput.min = "1";
    depthInput.max = "50";
    depthInput.value = Number.isFinite(Number(settings.lorebookScanDepth))
      ? Number(settings.lorebookScanDepth)
      : 2;
    depthInput.addEventListener("change", () => {
      const val = Number(depthInput.value);
      settings.lorebookScanDepth = Number.isFinite(val) && val >= 1 ? Math.round(val) : 2;
      saveSettings();
    });
    depthBox.append(
      depthInput,
