      make(
        "label",
        "",
        "📝 最终任务注入模板 (finalInjectTemplate · 支持 {{task:当前论坛任务}} 与 {{user_input_end_inject}})"
      )
    );
    const finalTplInput = make("textarea");
    finalTplInput.value = settings.finalInjectTemplate || DEFAULT_FINAL_INJECT_TEMPLATE;
    finalTplInput.addEventListener("change", () => {
      settings.finalInjectTemplate =
        finalTplInput.value.trim() || DEFAULT_FINAL_INJECT_TEMPLATE;
      saveSettings();
    });
    finalTplField.append(finalTplInput);

    tplGrid.append(endInjectField, finalTplField);
