    // 分槽位组装预览器
    const previewContainer = make("div", "wf-preview-container");
    previewContainer.hidden = true;
    slotCard.append(previewContainer);

    // ─── 4. 下方常见接口错误具体信息与排查对照卡 ───
    const errRefCard = make("div", "wf-section-card");
    const errRefHead = make("div", "wf-section-head");
    errRefHead.append(
      make("h3", "wf-section-title", "⚠️ 接口报错具体信息与诊断对照"),
      make("span", "wf-badge", "Error Diagnostics")
    );
    const errRefBody = make("div", "wf-scan-drawer");
    errRefBody.style.lineHeight = "1.65";
    errRefBody.innerHTML = `
      <div><span class="wf-pill-code">[,[3,"The input token count exceeds the maximum number of tokens allowed 131072.",[["type.googleapis.com/google.internal.alkali.applications.makersuite.v1.GeminiApiErrorDetails"]]]]</span><br/>👉 <b>诊断结论：被路由请重试</b>（反代负载均衡将本次长上下文请求分流到了仅支持 131,072 Token 的 128k 节点，直接重新点击「⚡ 刷新论坛」重试即可切回百万上下文节点）。</div>
      <div style="margin-top:6px;"><span class="wf-pill-code">HTTP 429 / RESOURCE_EXHAUSTED / Quota exceeded</span><br/>👉 <b>诊断结论：渠道并发或配额受限</b>（上游反代池当前请求拥挤，等待 5~10 秒后重试或切换模型前缀）。</div>
      <div style="margin-top:6px;"><span class="wf-pill-code">HTTP 502 / 503 / 504 / Bad Gateway / Gateway Timeout</span><br/>👉 <b>诊断结论：反代网关超时</b>（大模型单次预填充或工具调用耗时超过网关阈值，建议直接重试或使用不带「抗截断-」前缀的模型配合脚本内置断点续写）。</div>
      <div style="margin-top:6px;"><span class="wf-pill-code">模型返回内容为空 / 上游安全策略整段拦截</span><br/>👉 <b>诊断结论：空回或网关敏感词拦截</b>（脚本已内置防污染回滚保护，原有帖子不会丢失，直接点击重试即可）。</div>
    `;
    errRefCard.append(errRefHead, errRefBody);

    dashboard.append(slotCard, errRefCard);
    contentArea.append(dashboard);

    // 绑定顶部动作按钮事件
    scanNowBtn.addEventListener("click", async () => {
      setStatus("⏳ 正在执行 checkAndScanWorldbooks 扫描测试…");
      try {
        const ctx = await ForumContextReader.collectFullContext(host, window, settings);
        const st = ctx.loreScanResult?.scanStats;
        if (st) {
          lastLoreScanStats = st;
          setStatus(
            `✅ 扫描完成！作用世界书 [${st.books.join("、") || "无"}]，共 ${
              st.totalEntries
            } 条，激活 ${st.activatedCount} 条（蓝灯${st.constantCount}/绿灯${
              st.selectiveCount
            }/递归${st.recursiveCount}）`
          );
          renderWorkflowPromptTab();
        }
      } catch (err) {
        setStatus(`❌ 扫描异常：${err.message}`);
      }
    });

    previewTopBtn.addEventListener("click", async () => {
      setStatus("⏳ 正在扫描世界书并生成分槽位 Prompt 预览…");
      try {
        const ctx = await ForumContextReader.collectFullContext(host, window, settings, {
          actionType: "browse",
          customDirection: customDirectionText,
        });
        lastLoreScanStats = ctx.loreScanResult?.scanStats || lastLoreScanStats;
        const built = ForumPromptAssembler.buildForumPrompts({
          host,
          localWin: window,
          mode: settings.forumMode,
          targetBoard: settings.targetBoard,
          actionType: "browse",
          customDirection: customDirectionText,
          context: ctx,
          settings,
        });
        previewContainer.replaceChildren();
        previewContainer.hidden = false;

        if (ForumToolOutputPacker.isToolOutputActive(settings, built.orderedPrompts)) {
          const packed = ForumToolOutputPacker.packContextIntoFakeTool({
            rawMessagesList: built.orderedPrompts,
            systemPrompt: built.systemPrompt,
            userPrompt: built.userPrompt,
            settings,
          });
          const toolSeg = make("div", "wf-preview-segment");
          toolSeg.style.borderColor = "var(--accent-gold)";
          const toolHead = make("div", "wf-preview-seg-head");
          toolHead.append(
            make(
              "span",
              "",
              `🛠️ [伪造工具打包预览] function: ${packed.toolName} (复刻 Prime-1.18 三段式消息 + 工具承载 <Participant_input>)`
            ),
            make(
              "span",
              "wf-pill-code",
              `TOOL DESCRIPTION · ${packed.toolDescription.length.toLocaleString()} 字符 | 发送消息: ${packed.packedMessages.length} 条`
            )
          );
          const toolBody = make(
            "div",
            "wf-preview-seg-body",
            JSON.stringify(
              {
                tool_choice: packed.openAiToolChoice,
                tools: packed.openAiTools,
                messages_sent_count: packed.packedMessages.length,
                messages_roles: packed.packedMessages.map((m, idx) => `#${idx + 1} ${m.role} (${m.content.length} chars)`),
              },
              null,
              2
            )
          );
          toolSeg.append(toolHead, toolBody);
          previewContainer.append(toolSeg);
        }

        built.segmentMessages.forEach((m, i) => {
          const seg = make("div", "wf-preview-segment");
          const head = make("div", "wf-preview-seg-head");
          head.append(
            make("span", "", `槽位 #${i + 1} · [${m.slotId}] ${String(m.slotLabel || m.slotId).replace(/\s*\([^)]*\)\s*$/, "")}`),
            make("span", "wf-pill-code", `ROLE: ${m.role.toUpperCase()} · ${m.content.length.toLocaleString()} 字符`)
          );
          const body = make("div", "wf-preview-seg-body", m.content);
          seg.append(head, body);
          previewContainer.append(seg);
        });

        previewContainer.scrollIntoView({ behavior: "smooth", block: "nearest" });
        setStatus(
          `✅ Prompt 组装预览完成！共激活 ${built.segmentMessages.length} 个槽位，总计 ${(
            built.systemPrompt.length + built.userPrompt.length
          ).toLocaleString()} 字符。`
        );
      } catch (err) {
        setStatus(`❌ 预览组装失败：${err.message}`);
      }
    });

    resetAllBtn.addEventListener("click", () => {
      settings.affectedBooks = [];
      settings.lorebookScanDepth = 2;
      settings.lorebookRecursionSteps = 0;
      settings.lorebookMaxChars = 2000000;
      settings.stream = true;
      settings.taskContextConfig = JSON.parse(JSON.stringify(defaultTaskContextConfig));
      settings.promptSlots = JSON.parse(JSON.stringify(defaultPromptSlotsConfig));
      settings.enableHeaderGibberish = false;
      settings.tailOutputMode = "normal";
      settings.finalInjectTemplate = DEFAULT_FINAL_INJECT_TEMPLATE;
      settings.userInputEndInject = DEFAULT_ARMOR_PIERCING_PROMPT;
      settings.toolOutputEndInject = DEFAULT_TOOL_ONCE_PROMPT;
      saveSettings();
      setStatus("✅ 已恢复默认世界书（扫描深度2/递归0）、2,000,000 字符预算、上下文清洗与槽位配置。");
      renderWorkflowPromptTab();
    });
  }

  function renderApiSettingsTab() {
    boardFilterBar.hidden = true;
    controlStrip.hidden = true;
    contentArea.replaceChildren();

    const apiCard = make("div", "form-card");
    apiCard.append(make("h3", "", "🔌 独立 API 接口配置（与主聊天完全解耦）"));

    const modeGrid = make("div", "form-grid");
    const modeField = make("div", "field");
    modeField.append(make("label", "", "接口调用方式"));
    const modeSelect = make("select");
    for (const [val, label] of [
      ["custom", "🚀 独立自定义 API 直连（推荐，不占主API额度）"],
      ["tavern", "🍺 酒馆当前连接 API (TavernHelper.generateRaw)"],
    ]) {
      const o = make("option", "", label);
      o.value = val;
      modeSelect.append(o);
    }
    modeSelect.value = settings.apiMode;
    modeSelect.addEventListener("change", () => {
      settings.apiMode = modeSelect.value;
      saveSettings();
      renderApiSettingsTab();
    });
    modeField.append(modeSelect);

    const sourceField = make("div", "field");
    sourceField.append(make("label", "", "独立 API 协议类型"));
    const sourceSelect = make("select");
    for (const [val, label] of [
      ["openai", "OpenAI 兼容接口 (反代/DeepSeek/硅基/OneAPI等)"],
      ["gemini", "Google Gemini 原生接口 (/v1beta/models)"],
      ["claude", "Anthropic Claude 原生接口 (/v1/messages)"],
    ]) {
      const o = make("option", "", label);
      o.value = val;
      sourceSelect.append(o);
    }
    sourceSelect.value = settings.apiSource;
    sourceSelect.disabled = settings.apiMode === "tavern";
    sourceSelect.addEventListener("change", () => {
      settings.apiSource = sourceSelect.value;
      if (settings.apiSource === "gemini" && settings.apiUrl === "https://api.openai.com/v1") {
        settings.apiUrl = "https://generativelanguage.googleapis.com";
      }
      saveSettings();
      renderApiSettingsTab();
    });
    sourceField.append(sourceSelect);
    modeGrid.append(modeField, sourceField);
    apiCard.append(modeGrid);

    if (settings.apiMode === "custom") {
      const urlKeyGrid = make("div", "form-grid");
      const urlField = make("div", "field");
      urlField.append(make("label", "", "API 地址 (Base URL)"));
      const urlInput = make("input");
      urlInput.type = "text";
      urlInput.autocomplete = "off";
      urlInput.autocapitalize = "off";
      urlInput.spellcheck = false;
      urlInput.value = settings.apiUrl;
      urlInput.placeholder = "例如 https://api.deepseek.com 或 https://你的反代域名/v1";
      urlInput.addEventListener("change", () => {
        settings.apiUrl = urlInput.value.trim();
        saveSettings();
      });
      urlField.append(urlInput);

      const keyField = make("div", "field");
      keyField.append(make("label", "", "API 密钥 (API Key)"));
      const keyInput = make("input", "masked-key-input");
      keyInput.type = "text";
      keyInput.autocomplete = "off";
      keyInput.autocapitalize = "off";
      keyInput.spellcheck = false;
      keyInput.value = settings.apiKey;
      keyInput.placeholder = "sk-... 或 AIza...";
      keyInput.addEventListener("change", () => {
        settings.apiKey = keyInput.value.trim();
        saveSettings();
      });
      keyField.append(keyInput);
      urlKeyGrid.append(urlField, keyField);
      apiCard.append(urlKeyGrid);

      const modelRow = make("div", "form-grid");
      const modelField = make("div", "field");
      modelField.append(make("label", "", "模型名称 (可手动输入或点击拉取)"));
      const modelInputRow = make("div", "row-inline");
      const modelInput = make("input");
      modelInput.type = "text";
      modelInput.autocomplete = "off";
      modelInput.autocapitalize = "off";
      modelInput.style.flex = "1";
      modelInput.value = settings.apiModel;
      modelInput.placeholder = "例如 deepseek-chat / gemini-2.5-flash";
      modelInput.addEventListener("change", () => {
        settings.apiModel = modelInput.value.trim();
        saveSettings();
      });

      const fetchModelsBtn = make("button", "pill-btn", "🔄 拉取模型");
      fetchModelsBtn.addEventListener("click", async () => {
        settings.apiUrl = urlInput.value.trim();
        settings.apiKey = keyInput.value.trim();
        saveSettings();
        setStatus("正在从独立 API 拉取模型列表…");
        try {
          const models = await ForumApiClient.fetchModelList({
            source: settings.apiSource,
            url: settings.apiUrl,
            apiKey: settings.apiKey,
          });
          settings.modelList = models;
          if (models.length && !settings.apiModel) {
            settings.apiModel = models[0];
          }
          saveSettings();
          setStatus(`✅ 成功拉取 ${models.length} 个模型！`);
          renderApiSettingsTab();
        } catch (err) {
          setStatus(`❌ 拉取模型失败：${err.message}`);
        }
      });

      const testApiBtn = make("button", "pill-btn", "⚡ 测试连接");
      testApiBtn.addEventListener("click", async () => {
        settings.apiUrl = urlInput.value.trim();
        settings.apiKey = keyInput.value.trim();
        settings.apiModel = modelInput.value.trim();
        saveSettings();
        setStatus("正在测试独立 API 连接…");
        try {
          const reply = await ForumApiClient.generate({
            host,
            localWin: window,
            settings: { ...settings, maxTokens: 64, stream: false, tailOutputMode: "normal", enableHeaderGibberish: false },
            systemPrompt: "You are a connectivity tester.",
            userPrompt: "请回复：命定论坛独立API连接正常",
          });
          setStatus(`✅ 连接测试成功！模型响应：${reply.slice(0, 60)}`);
        } catch (err) {
          setStatus(`❌ 连接测试失败：${err.message}`);
        }
      });

      modelInputRow.append(modelInput, fetchModelsBtn, testApiBtn);
      modelField.append(modelInputRow);

      if (Array.isArray(settings.modelList) && settings.modelList.length > 0) {
        const selectModelField = make("div", "field");
        selectModelField.append(
          make("label", "", `从已拉取列表快速选择 (${settings.modelList.length} 个)`)
        );
        const modelSelect = make("select");
        for (const m of settings.modelList) {
          const o = make("option", "", m);
          o.value = m;
          modelSelect.append(o);
        }
        modelSelect.value = settings.apiModel;
        modelSelect.addEventListener("change", () => {
          settings.apiModel = modelSelect.value;
          modelInput.value = modelSelect.value;
          saveSettings();
        });
        selectModelField.append(modelSelect);
        modelRow.append(modelField, selectModelField);
      } else {
        modelRow.append(modelField);
      }
      apiCard.append(modelRow);

      const presetRow = make("div", "row-inline");
      const presetNameInput = make("input");
      presetNameInput.type = "text";
      presetNameInput.autocomplete = "off";
      presetNameInput.placeholder = "输入配置名称保存为预设（如：DeepSeek刷帖）";
      presetNameInput.style.flex = "1";
      const savePresetBtn = make("button", "pill-btn", "💾 保存为API预设");
      savePresetBtn.addEventListener("click", () => {
        const pName = presetNameInput.value.trim() || `${settings.apiSource}-${settings.apiModel || "默认"}`;
        const existingIdx = (settings.apiPresets || []).findIndex((p) => p.name === pName);
        const snap = {
          name: pName,
          apiSource: settings.apiSource,
          apiUrl: settings.apiUrl,
          apiKey: settings.apiKey,
          apiModel: settings.apiModel,
        };
        if (existingIdx >= 0) settings.apiPresets[existingIdx] = snap;
        else settings.apiPresets = [...(settings.apiPresets || []), snap];
        saveSettings();
        setStatus(`已保存 API 预设「${pName}」`);
        renderApiSettingsTab();
      });
      presetRow.append(presetNameInput, savePresetBtn);
      apiCard.append(presetRow);

      if (Array.isArray(settings.apiPresets) && settings.apiPresets.length > 0) {
        const savedBar = make("div", "row-inline");
        savedBar.append(make("span", "", "已存预设："));
        settings.apiPresets.forEach((p, idx) => {
          const loadBtn = make("button", "pill-btn", `📂 ${p.name}`);
          loadBtn.addEventListener("click", () => {
            settings.apiSource = p.apiSource || "openai";
            settings.apiUrl = p.apiUrl || "";
            settings.apiKey = p.apiKey || "";
            settings.apiModel = p.apiModel || "";
            saveSettings();
            setStatus(`已加载预设「${p.name}」`);
            renderApiSettingsTab();
          });
          const delBtn = make("button", "pill-btn", "×");
          delBtn.title = "删除该预设";
          delBtn.addEventListener("click", () => {
            settings.apiPresets.splice(idx, 1);
            saveSettings();
            renderApiSettingsTab();
          });
          savedBar.append(loadBtn, delBtn);
        });
        apiCard.append(savedBar);
      }
    }

    const paramCard = make("div", "form-card");
    paramCard.append(make("h3", "", "⚙️ 生成参数与移动端防遮挡留白设置"));
    const paramGrid = make("div", "form-grid");

    const tempField = make("div", "field");
    tempField.append(make("label", "", "温度 (Temperature)"));
    const tempInput = make("input");
    tempInput.type = "number";
    tempInput.step = "0.05";
    tempInput.min = "0";
    tempInput.max = "2";
    tempInput.value = settings.temperature;
    tempInput.addEventListener("change", () => {
      settings.temperature = Number(tempInput.value) || 0.95;
      saveSettings();
    });
    tempField.append(tempInput);

    const tokenField = make("div", "field");
    tokenField.append(make("label", "", "最大输出 Token (max_tokens · 上限 60000)"));
    const tokenInput = make("input");
    tokenInput.type = "number";
    tokenInput.step = "1000";
    tokenInput.min = "256";
    tokenInput.max = "60000";
    tokenInput.value = Math.min(60000, Number(settings.maxTokens) || 20000);
    tokenInput.addEventListener("change", () => {
      settings.maxTokens = Math.min(60000, Math.max(256, Number(tokenInput.value) || 20000));
      tokenInput.value = settings.maxTokens;
      saveSettings();
    });
    tokenField.append(tokenInput);

    const turnsField = make("div", "field");
    turnsField.append(make("label", "", "读取最近主聊天剧情轮数（默认 2 轮）"));
    const turnsInput = make("input");
    turnsInput.type = "number";
    turnsInput.min = "1";
    turnsInput.max = "30";
    turnsInput.value = settings.contextTurns || 2;
    turnsInput.addEventListener("change", () => {
      settings.contextTurns = Math.max(1, Number(turnsInput.value) || 2);
      saveSettings();
    });
    turnsField.append(turnsInput);

    const autoField = make("div", "field");
    autoField.append(make("label", "", "主聊天回复后自动后台刷帖 (0=仅手动)"));
    const autoInput = make("input");
    autoInput.type = "number";
    autoInput.min = "0";
    autoInput.max = "20";
    autoInput.value = settings.autoGenerateEveryN || 0;
    autoInput.addEventListener("change", () => {
      settings.autoGenerateEveryN = Math.max(0, Number(autoInput.value) || 0);
      saveSettings();
    });
    autoField.append(autoInput);

    const mobileTopField = make("div", "field");
    mobileTopField.append(
      make("label", "", "📱 手机端顶部留白高度 (px，防状态栏/刘海遮挡)")
    );
    const mobileTopInput = make("input");
    mobileTopInput.type = "number";
    mobileTopInput.min = "0";
    mobileTopInput.max = "180";
    mobileTopInput.step = "2";
    mobileTopInput.value = settings.mobileTopOffset ?? 54;
    mobileTopInput.addEventListener("change", () => {
      const val = Number(mobileTopInput.value);
      settings.mobileTopOffset = Number.isFinite(val) ? Math.max(0, Math.min(180, val)) : 54;
      saveSettings();
      clampPosition();
    });
    mobileTopField.append(mobileTopInput);

    paramGrid.append(
      tempField,
      tokenField,
      turnsField,
      autoField,
      mobileTopField
    );

    const togglesRow = make("div", "row-inline");
    const streamLabel = make("label", "row-inline");
    streamLabel.style.cursor = "pointer";
    const streamChk = make("input");
    streamChk.type = "checkbox";
    streamChk.style.cssText = "width:16px;height:16px;margin:0;accent-color:var(--accent-gold);cursor:pointer;";
    streamChk.defaultChecked = true;
    streamChk.checked = settings.stream !== false;
    streamChk.addEventListener("change", () => {
      settings.stream = streamChk.checked;
      saveSettings();
    });
    streamLabel.append(streamChk, make("span", "", "启用流式输出 (实时滚动渲染论坛生成过程)"));

    const userPostSettingLabel = make("label", "row-inline");
    const userPostSettingChk = make("input");
    userPostSettingChk.type = "checkbox";
    userPostSettingChk.checked = Boolean(settings.allowUserPosts);
    userPostSettingChk.addEventListener("change", () => {
      settings.allowUserPosts = userPostSettingChk.checked;
      saveSettings();
    });
    userPostSettingLabel.append(
      userPostSettingChk,
      make("span", "", "刷新论坛时生成主角(user)发布的帖子与相关热帖")
    );
    togglesRow.append(streamLabel, userPostSettingLabel);

    const customSysField = make("div", "field");
    customSysField.append(
      make("label", "", "附加自定义系统指令（可选，支持 {{user}} / {{char}} / {{getvar::}} 等酒馆宏）")
    );
    const customSysInput = make("textarea");
    customSysInput.value = settings.customSystemPrompt || "";
    customSysInput.placeholder =
      "例如：多安排雾晶学院的角色互动 / 增加某个特定传闻的讨论度…";
    customSysInput.addEventListener("change", () => {
      settings.customSystemPrompt = customSysInput.value;
      saveSettings();
    });
    customSysField.append(customSysInput);

    const apiErrHint = make("div", "wf-scan-drawer");
    apiErrHint.style.marginTop = "6px";
    apiErrHint.innerHTML = `
      <div><strong style="color:var(--accent-gold);">💡 常见报错具体说明：</strong></div>
      <div>• 报错 <span class="wf-pill-code">[,[3,"The input token count exceeds the maximum number of tokens allowed 131072.",[["type.googleapis.com/google.internal.alkali.applications.makersuite.v1.GeminiApiErrorDetails"]]]]</span>：代表<b>被路由请重试</b>（请求被反代分流至 128k 限制节点，直接重试即可）。</div>
      <div>• 报错 <span class="wf-pill-code">429 / 502 / 504</span>：代表上游渠道限流或网关等待超时，稍候几秒重新点击生成即可。</div>
    `;
    paramCard.append(paramGrid, togglesRow, customSysField, apiErrHint);
    contentArea.append(apiCard, paramCard);
  }

  function renderFavoritesTab() {
    contentArea.replaceChildren();
    contentArea.classList.toggle("hide-admin-identity", !settings.showAdminIdentity);

    // 顶部控制栏：搜索框 + 清空收藏夹
    controlStrip.hidden = false;
    controlStrip.replaceChildren();
    const searchInput = make("input", "direction-input");
    searchInput.type = "text";
    searchInput.autocomplete = "off";
    searchInput.value = favSearchQuery;
    searchInput.placeholder = "🔍 在个人书签中搜索标题、发帖人、真实身份或正文关键词…";
    searchInput.style.flex = "1 1 240px";
    searchInput.addEventListener("input", () => {
      favSearchQuery = searchInput.value;
      renderFavoritesTab();
      try {
        searchInput.focus({ preventScroll: true });
      } catch {}
    });
    controlStrip.append(searchInput);

    if (favorites.length > 0) {
      const clearFavBtn = make("button", "pill-btn", "🗑️ 清空收藏夹");
      clearFavBtn.type = "button";
      clearFavBtn.addEventListener("click", () => {
        favorites = [];
        saveFavorites();
        setStatus("🗑️ 已清空个人书签收藏夹。");
        render();
      });
      controlStrip.append(clearFavBtn);
    }

    if (!favorites.length) {
      boardFilterBar.hidden = true;
      const empty = make("div", "empty-state");
      empty.innerHTML = `
        <div style="font-size:30px;margin-bottom:8px;">⭐</div>
        <div style="font-size:15px;font-weight:700;color:var(--accent-gold);margin-bottom:6px;">
          单帖收藏夹（个人书签）暂无内容
        </div>
        <div>在「📰 首页」任意喜欢的帖子下方点击 <b>「⭐ 收藏此帖」</b>，即可将该帖永久保存到此处（不受历史期刊 25 期自动滚动清理影响），并支持在收藏夹内随时生图、盖楼追问或设为行动线索。</div>
      `;
      contentArea.append(empty);
      return;
    }

    // 板块筛选栏
    const favBoards = new Set();
    favorites.forEach((f) => {
      if (f?.board) favBoards.add(f.board);
    });
    if (activeFavBoardFilter !== "ALL" && !favBoards.has(activeFavBoardFilter)) {
      activeFavBoardFilter = "ALL";
    }

    boardFilterBar.replaceChildren();
    boardFilterBar.hidden = false;
    const allChip = make(
      "button",
      "board-chip" + (activeFavBoardFilter === "ALL" ? " active" : ""),
      `全部收藏 (${favorites.length})`
    );
    allChip.type = "button";
    allChip.addEventListener("click", () => {
      activeFavBoardFilter = "ALL";
      renderFavoritesTab();
    });
    boardFilterBar.append(allChip);

    for (const bName of favBoards) {
      const count = favorites.filter((f) => f.board === bName).length;
      const chip = make(
        "button",
        "board-chip" + (activeFavBoardFilter === bName ? " active" : ""),
        `${bName} (${count})`
      );
      chip.type = "button";
      chip.addEventListener("click", () => {
        activeFavBoardFilter = bName;
        renderFavoritesTab();
      });
      boardFilterBar.append(chip);
    }

    const q = favSearchQuery.trim().toLowerCase();
    const filteredFavs = favorites.filter((item) => {
      if (!item) return false;
      if (activeFavBoardFilter !== "ALL" && item.board !== activeFavBoardFilter) return false;
      if (!q) return true;
      const hay = `${item.title || ""} ${item.author || ""} ${item.adminIdentity || ""} ${item.board || ""} ${item.htmlContent || ""}`.toLowerCase();
      return hay.includes(q);
    });

    if (!filteredFavs.length) {
      contentArea.append(make("div", "empty-state", "没有匹配当前筛选条件的收藏帖子。"));
      return;
    }

    const rootWrap = make("div", "ast-net forum-render-root");
    filteredFavs.forEach((favItem, idx) => {
      const temp = doc.createElement("div");
      temp.innerHTML = favItem.htmlContent || "";
      stripInjectedPostControls(temp);
      const postEl = queryTopLevelPosts(temp)[0] || temp.firstElementChild;
      if (!postEl) return;

      const boardName = favItem.board || postEl.getAttribute("data-board") || "综合";
      const postId = favItem.postId || postEl.getAttribute("data-post-id") || `fav-post-${idx + 1}`;
      postEl.classList.add("ast-post");
      postEl.setAttribute("data-board", boardName);
      postEl.setAttribute("data-post-id", postId);

      if (favItem.chatu8Prompt) {
        const imgBox = postEl.querySelector(".ast-img");
        if (imgBox && !imgBox.getAttribute("data-chatu8-prompt")) {
          imgBox.setAttribute("data-chatu8-prompt", favItem.chatu8Prompt);
        }
      }

      enhancePostMagicStoneImage(postEl, idx, false);

      const titleEl = postEl.querySelector(".ast-post-title, h3, h2");
      const titleText = favItem.title || (titleEl ? titleEl.textContent.trim() : `收藏帖 #${idx + 1}`);

      const actionBar = make("div", "post-actions-bar");
      const modeTag = make(
        "span",
        "wf-badge",
        `${favItem.mode === "dark" ? "🔞 里版" : "🌐 表版"} · 收藏于 ${favItem.savedAt || "近期"}`
      );
      const replyBtn = make("button", "pill-btn", "💬 盖楼/追问此帖");
      replyBtn.type = "button";
      const fillChatBtn = make("button", "pill-btn", "📥 设为行动线索（填入聊天框）");
      fillChatBtn.type = "button";
      const unfavBtn = make("button", "pill-btn fav-active", "🗑️ 取消收藏");
      unfavBtn.type = "button";

      unfavBtn.addEventListener("click", () => {
        const realIdx = favorites.findIndex((x) => x.favId === favItem.favId);
        if (realIdx >= 0) favorites.splice(realIdx, 1);
        saveFavorites();
        setStatus(`🗑️ 已从个人书签移除《${titleText}》`);
        render();
      });

      const replyDrawer = make("div", "post-reply-drawer");
      replyDrawer.hidden = true;
      const replyNick = make("input");
      replyNick.type = "text";
      replyNick.autocomplete = "off";
      replyNick.value = settings.activeUserAlias || "";
      replyNick.placeholder = "你的匿名回复昵称（留空默认：匿名星轨旅人）";
      const replyAliasBar = createAliasSelectorBar(replyNick);
      const replyInput = make("textarea");
      replyInput.placeholder = `在收藏帖《${titleText}》下继续盖楼追问，演化完成后将自动同步更新此条书签…`;
      const submitReplyBtn = make("button", "pill-btn primary", "✨ 提交回复并演化后续楼层");
      submitReplyBtn.type = "button";

      submitReplyBtn.addEventListener("click", () => {
        const val = replyInput.value.trim();
        if (!val) {
          setStatus("请先输入你的回复内容！");
          return;
        }
        const chosenAuthor = replyNick.value.trim() || settings.activeUserAlias || "匿名星轨旅人";
        settings.activeUserAlias = chosenAuthor;
        saveSettings();
        const chatu8Prompt =
          postEl.querySelector(".ast-img")?.getAttribute("data-chatu8-prompt") || favItem.chatu8Prompt || "";
        const cleanPostHtml = extractCleanPostHtml(postEl, boardName, postId, true);
        if (!currentHtml || !currentHtml.includes(titleText)) {
          const rootCls = (favItem.mode || settings.forumMode) === "dark" ? "ast-dark" : "ast-net";
          currentHtml = `<div class="${rootCls}">\n${cleanPostHtml}\n</div>`;
        }
        triggerForumGeneration({
          actionType: "reply_post",
          replyTargetData: {
            postId,
            postIndex: 0,
            board: boardName,
            title: titleText,
            htmlContent: cleanPostHtml,
            chatu8Prompt,
            userReply: val,
            author: chosenAuthor,
          },
        });
      });

      replyDrawer.append(replyNick, replyAliasBar, replyInput, submitReplyBtn);
      replyBtn.addEventListener("click", () => {
        replyDrawer.hidden = !replyDrawer.hidden;
      });

      const injectedBadge = make("span", "post-injected-badge", "📘 已入线索世界书");
      injectedBadge.hidden = postEl.getAttribute("data-mvu-injected") !== "true";

      fillChatBtn.addEventListener("click", () => {
        const postData = ForumVariableTreeManager.extractPostStructuredData(
          postEl,
          boardName,
          postId,
          favItem.mode || settings.forumMode
        );
        openForumClueInjectionModal({
          postEl,
          postData,
          onInjected: () => {
            postEl.setAttribute("data-mvu-injected", "true");
            injectedBadge.hidden = false;
            favItem.htmlContent = extractCleanPostHtml(postEl, boardName, postId, false);
            saveFavorites();
          },
        });
      });

      actionBar.append(modeTag, replyBtn, fillChatBtn, unfavBtn, injectedBadge);
      postEl.append(actionBar, replyDrawer);
      rootWrap.append(postEl);
    });

    contentArea.append(rootWrap);
  }

  function renderArchivesTab() {
    boardFilterBar.hidden = true;
    controlStrip.hidden = true;
    contentArea.replaceChildren();

    const card = make("div", "form-card");
    const headRow = make("div", "row-inline");
    headRow.style.justifyContent = "space-between";
    headRow.append(make("h3", "", `🗂️ 命定论坛历史期刊存档 (${archives.length} 期)`));
    if (archives.length > 0) {
      const clearBtn = make("button", "pill-btn", "🗑️ 清空全部存档");
      clearBtn.addEventListener("click", () => {
        archives = [];
        currentHtml = "";
        saveArchives();
        renderArchivesTab();
      });
      headRow.append(clearBtn);
    }
    card.append(headRow);

    if (!archives.length) {
      card.append(make("div", "empty-state", "暂无历史论坛存档，生成后的每一期论坛会自动保存在此处。"));
    } else {
      archives.forEach((item, index) => {
        const row = make("div", "row-inline");
        row.style.justifyContent = "space-between";
        row.style.padding = "8px 10px";
        row.style.borderRadius = "7px";
        row.style.background = "rgba(0,0,0,0.25)";
        row.style.border = "1px solid var(--border-soft)";

        const info = make(
          "div",
          "",
          `[${item.mode === "dark" ? "🔞 里版" : "🌐 表版"} · ${item.board}] ${
            item.worldTime
          } （生成于 ${item.time}）`
        );
        const btns = make("div", "row-inline");
        const viewBtn = make("button", "pill-btn primary", "📖 查看此期");
        viewBtn.addEventListener("click", () => {
          settings.forumMode = item.mode || "surface";
          currentHtml = item.html;
          activeTab = "forum";
          activeBoardFilter = "ALL";
          updateLauncherFace();
          render();
        });
        const delBtn = make("button", "pill-btn", "删除");
        delBtn.addEventListener("click", () => {
          archives.splice(index, 1);
          saveArchives();
          renderArchivesTab();
        });
        btns.append(viewBtn, delBtn);
        row.append(info, btns);
        card.append(row);
      });
    }
    contentArea.append(card);
  }

  function render() {
    if (disposed) return;
    const isDark = settings.forumMode === "dark";
    shell.dataset.mode = settings.forumMode;
    launcher.dataset.mode = settings.forumMode;

    handleTitle.textContent = isDark
      ? "✦ 命定论坛 · 里版"
      : "✦ 命定论坛 · 表版";
    handleSub.textContent = isDark ? "🔞 无审查暗网" : "🌐 3层+准入";

    modeSwitchBtn.textContent = isDark ? "🔄 切回表版" : "🔞 切至里版";
    imgModeToggleBtn.textContent = settings.enableImageGenMode
      ? "🎨 生图:开"
      : "🎨 生图:关";
    imgModeToggleBtn.style.borderColor = settings.enableImageGenMode
      ? "var(--accent-gold)"
      : "var(--border-soft)";
    imgModeToggleBtn.style.opacity = settings.enableImageGenMode ? "1" : "0.72";

    adminToggleBtn.textContent = settings.showAdminIdentity
      ? "👁️ 透视:开"
      : "🕶️ 透视:关";

    subbar.replaceChildren();
    for (const [id, label] of [
      ["forum", "📰 首页"],
      ["post", "📝 发帖"],
      ["favorites", `⭐ 收藏(${favorites.length})`],
      ["variables", "📘 线索世界书"],
      ["workflow", "🧩 上下文/世界书"],
      ["archives", `🗂️ 期刊(${archives.length})`],
      ["api", "🔌 API"],
    ]) {
      const btn = make("button", "nav-tab" + (activeTab === id ? " active" : ""), label);
      btn.setAttribute("data-nav-id", id);
      btn.addEventListener("click", () => {
        activeTab = id;
        render();
      });
      subbar.append(btn);
    }

    const makeSubbarTogglePill = (isActive, emojiText, labelText, titleText, onToggle) => {
      const btn = make(
        "button",
        "wf-selectable-pill subbar-toggle-pill" + (isActive ? " active" : "")
      );
      btn.type = "button";
      btn.title = titleText;
      btn.setAttribute("aria-pressed", String(Boolean(isActive)));
      const chkBox = make("span", "pill-chk-box");
      chkBox.innerHTML =
        '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2.2 6.2L4.8 8.8L9.8 3.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
      const ico = make("span", "pill-ico", emojiText);
      const txt = make("span", "pill-txt", labelText);
      btn.append(chkBox, ico, txt);
      btn.addEventListener("click", onToggle);
      return btn;
    };

    const userPostBtn = makeSubbarTogglePill(
      Boolean(settings.allowUserPosts),
      "👤",
      "生成user帖子",
      "勾选后，点击「⚡ 刷新论坛」将自动生成由主角(user)本人发布的帖子或围绕主角展开的热帖",
      () => {
        settings.allowUserPosts = !settings.allowUserPosts;
        userPostBtn.classList.toggle("active", settings.allowUserPosts);
        userPostBtn.setAttribute("aria-pressed", String(Boolean(settings.allowUserPosts)));
        saveSettings();
      }
    );

    const imgModeBtn = makeSubbarTogglePill(
      Boolean(settings.enableImageGenMode),
      "🎨",
      "留影石生图模式",
      "开启后，刷帖/发帖将通过《新版通用角色变量世界书》在魔导留影石画面内生成画图Tag，并显示「🎨 生成图片」按钮联动 st-chatu8 生图",
      () => {
        settings.enableImageGenMode = !settings.enableImageGenMode;
        saveSettings();
        render();
      }
    );

    const subRight = make("div", "subbar-right");
    const genBtn = make(
      "button",
      "pill-btn primary gen-main-btn",
      isGenerating ? "⏳ 推演中..." : "⚡ 刷新论坛"
    );
    genBtn.type = "button";
    genBtn.disabled = isGenerating;
    genBtn.addEventListener("click", () => triggerForumGeneration({ actionType: "browse" }));

    const contInfo = detectForumTruncation(currentHtml);
    const contBtn = make(
      "button",
      "pill-btn" + (contInfo.truncated ? " primary" : ""),
      contInfo.truncated
        ? `▶️ 继续生成 (${contInfo.postCount}篇·未完)`
        : "▶️ 继续加更"
    );
    contBtn.type = "button";
    contBtn.disabled = isGenerating;
    contBtn.title = contInfo.truncated ? contInfo.reason : "顺着当前上下文继续加更更多论坛热帖";
    if (contInfo.truncated) {
      contBtn.style.cssText =
        "border-color:#ffb347;color:#ffd08a;box-shadow:0 0 12px rgba(255,179,71,0.45);";
    }
    contBtn.addEventListener("click", () => triggerForumGeneration({ actionType: "continue" }));

    const gibberishBtn = makeSubbarTogglePill(
      Boolean(settings.enableHeaderGibberish),
      "🎲",
      "头部乱码",
      "开启后，每次发送前在头部第一条消息注入 <system_entropy_padding> 包裹的 6000 字符纯 ASCII 加密盐值，打断 API 前缀缓存并防止模型在思考链中解码",
      () => {
        settings.enableHeaderGibberish = !settings.enableHeaderGibberish;
        saveSettings();
        setStatus(
          settings.enableHeaderGibberish
            ? "🎲 已开启【头部 6000 字符乱码注入】：自动注入 <system_entropy_padding> 破缓存盐值与忽略元指令"
            : "🎲 已关闭【头部 6000 字符乱码注入】"
        );
        render();
      }
    );

    const toolOnceBtn = makeSubbarTogglePill(
      settings.tailOutputMode === "tool_once",
      "🛠️",
      "工具一次调用",
      "开启后，严格按《Prime-1.18》保留完整 user 破限消息，将 <Participant_input> 塞入伪造工具 submit_recorder_output 的 description 中并用函数输出",
      () => {
        settings.tailOutputMode = settings.tailOutputMode === "tool_once" ? "normal" : "tool_once";
        saveSettings();
        setStatus(
          settings.tailOutputMode === "tool_once"
            ? "🛠️ 已开启【工具一次调用】：保留完整 user 破限上下文，将 <Participant_input> 塞入 submit_recorder_output 并用函数输出"
            : "🔌 已切回【标准直接输出】模式"
        );
        render();
      }
    );

    subRight.append(userPostBtn, imgModeBtn, gibberishBtn, toolOnceBtn, contBtn, genBtn);
    subbar.append(subRight);

    if (activeTab === "forum") {
      controlStrip.hidden = false;
      controlStrip.replaceChildren();

      const dirInput = make("input", "direction-input");
      dirInput.type = "text";
      dirInput.autocomplete = "off";
      dirInput.value = customDirectionText;
      dirInput.placeholder =
        "可选：输入本轮刷帖风向/热议焦点（如：热议刚发生的重大事件、打听某位角色或悬赏）…";
      dirInput.addEventListener("input", () => {
        customDirectionText = dirInput.value;
      });

      controlStrip.append(dirInput);
      renderForumHtmlContent(currentHtml, isGenerating);
    } else if (activeTab === "post") {
      renderNewPostTab();
    } else if (activeTab === "favorites") {
      renderFavoritesTab();
    } else if (activeTab === "variables") {
      renderVariablesTab();
    } else if (activeTab === "workflow") {
      renderWorkflowPromptTab();
    } else if (activeTab === "api") {
      renderApiSettingsTab();
    } else if (activeTab === "archives") {
      renderArchivesTab();
    }

    if (open) clampPosition();
  }

  if (typeof eventOn === "function" && typeof tavern_events !== "undefined") {
    const listen = (ev, fn) => {
      if (!ev) return;
      eventOn(ev, fn);
      if (typeof eventRemoveListener === "function") {
        stops.push(() => eventRemoveListener(ev, fn));
      }
    };

    listen(tavern_events.MESSAGE_RECEIVED, () => {
      const everyN = Number(settings.autoGenerateEveryN) || 0;
      if (everyN > 0) {
        aiReplyCounter++;
        if (aiReplyCounter >= everyN) {
          aiReplyCounter = 0;
          triggerForumGeneration({ actionType: "browse", silent: true });
        }
      }
    });

    listen(tavern_events.CHAT_CHANGED, () => {
      aiReplyCounter = 0;
      ForumVariableTreeManager.readForumVariableTree(host, window)
        .then(({ forumData }) =>
          ForumVariableTreeManager.syncForumCluesToBlueLightWorldbook(host, window, forumData, {
            enabled: settings.forumVarInjectToMainPrompt !== false,
            scope: settings.forumVarPromptScope || "active_only",
            depth: settings.forumVarPromptDepth ?? 1,
            role: settings.forumVarPromptRole || "user",
          })
        )
        .catch(() => {});
      if (open) render();
    });
  }

  mobileEntry = createForumScriptEntry({
    host,
    doc,
    root,
    panel,
    backdrop,
    launcher,
    toolbar: topbar,
    name: "命定论坛",
    getMobileTopOffset: () => settings.mobileTopOffset ?? 54,
    onToggle: () => setOpen(!open),
    onLayout: clampPosition,
    onModeChange: () => stopDrag?.(),
  });
  stops.push(() => mobileEntry.dispose());
  mobileEntry.syncExpanded(open);

  const instance = {
    dispose() {
      if (disposed) return;
      disposed = true;
      ForumApiClient.cancelActiveRequest();
      runCleanup([
        () => stopDrag?.(),
        () => ForumChatu8Bridge.dispose(),
        ...stops,
        () => root.remove(),
        () => {
          if (host[instanceKey] === instance) delete host[instanceKey];
        },
      ]);
    },
  };

  root.__dlcForumUiDispose = () => instance.dispose();
  host[instanceKey] = instance;
  window.addEventListener("pagehide", () => instance.dispose(), { once: true });

  render();
})();
